Haz una web interactiva, moderna, funcional y mirando al futuro. Ponte en un experto senior en el sector logistico y del transporte de mercancias a nivel global. Te adjunto codigo generado en gemini:
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MF1012 - Distribución Capilar + AI</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700&display=swap');

        body {
            font-family: 'Inter', sans-serif;
            scroll-behavior: smooth;
        }

        .gradient-bg {
            background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);
        }

        .card-hover:hover {
            transform: translateY(-5px);
            transition: all 0.3s ease;
            box-shadow: 0 10px 20px rgba(0,0,0,0.1);
        }

        .glass-panel {
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.2);
        }

        /* Loading Spinner */
        .spinner {
            border: 3px solid rgba(255, 255, 255, 0.3);
            border-radius: 50%;
            border-top: 3px solid #ffffff;
            width: 20px;
            height: 20px;
            animation: spin 1s linear infinite;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
    </style>
</head>
<body class="bg-gray-50 text-gray-800">

    <!-- Navegación -->
    <nav class="sticky top-0 z-50 bg-white shadow-md">
        <div class="container mx-auto px-4 py-4 flex justify-between items-center">
            <div class="flex items-center space-x-2">
                <i class="fas fa-truck-fast text-blue-600 text-2xl"></i>
                <span class="font-bold text-xl tracking-tight text-blue-900">MF1012 Logística AI</span>
            </div>
            <div class="hidden md:flex space-x-6 font-medium">
                <a href="#inicio" class="hover:text-blue-600 transition">Inicio</a>
                <a href="#ia-tools" class="hover:text-blue-600 transition">Herramientas AI ✨</a>
                <a href="#unidades" class="hover:text-blue-600 transition">Unidades</a>
                <a href="#competencias" class="hover:text-blue-600 transition">Competencias</a>
            </div>
            <button class="md:hidden text-blue-600" onclick="toggleMenu()">
                <i class="fas fa-bars text-xl"></i>
            </button>
        </div>
        <div id="mobileMenu" class="hidden md:hidden bg-white border-t p-4">
            <a href="#inicio" class="block py-2 text-gray-600" onclick="toggleMenu()">Inicio</a>
            <a href="#ia-tools" class="block py-2 text-gray-600" onclick="toggleMenu()">Herramientas AI ✨</a>
            <a href="#unidades" class="block py-2 text-gray-600" onclick="toggleMenu()">Unidades</a>
        </div>
    </nav>

    <!-- Hero Section -->
    <header id="inicio" class="gradient-bg text-white py-20 px-4">
        <div class="container mx-auto text-center max-w-4xl">
            <h1 class="text-4xl md:text-6xl font-extrabold mb-6 leading-tight">Distribución Capilar Inteligente</h1>
            <p class="text-xl opacity-90 mb-8">Gestión de transporte potenciada por Inteligencia Artificial para la "última milla".</p>
            <div class="flex flex-wrap justify-center gap-4">
                <a href="#ia-tools" class="bg-white text-blue-700 font-bold px-8 py-3 rounded-full shadow-lg hover:bg-blue-50 transition">
                    Probar Herramientas AI ✨
                </a>
            </div>
        </div>
    </header>

    <!-- Gemini AI Tools Section -->
    <section id="ia-tools" class="py-16 container mx-auto px-4">
        <div class="text-center mb-12">
            <h2 class="text-3xl font-bold text-blue-900">Asistente Logístico Inteligente ✨</h2>
            <p class="text-gray-600 mt-2">Utiliza la potencia de Gemini para tareas complejas del MF1012</p>
        </div>

        <div class="grid lg:grid-cols-2 gap-8">
            <!-- Herramienta 1: Planificador de Rutas -->
            <div class="bg-white rounded-2xl shadow-xl p-8 border border-blue-100">
                <div class="flex items-center space-x-3 mb-6">
                    <div class="bg-blue-600 text-white p-3 rounded-lg">
                        <i class="fas fa-map-location-dot"></i>
                    </div>
                    <h3 class="text-xl font-bold">Planificador de Rutas Inteligente ✨</h3>
                </div>
                <p class="text-sm text-gray-500 mb-4">Introduce los puntos de entrega y deja que la IA sugiera una secuencia lógica.</p>
                <textarea id="routeInput" rows="3" class="w-full p-4 border rounded-xl mb-4 bg-gray-50 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Ej: 5 entregas en centro ciudad, 2 en periferia norte, prioridad 1 en calle Mayor..."></textarea>
                <button onclick="generatePlan('route')" id="routeBtn" class="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition flex items-center justify-center space-x-2">
                    <span>Generar Plan de Ruta ✨</span>
                    <div id="routeLoader" class="spinner hidden"></div>
                </button>
                <div id="routeOutput" class="mt-4 p-4 bg-blue-50 rounded-xl text-sm hidden whitespace-pre-line border border-blue-200"></div>
            </div>

            <!-- Herramienta 2: Redactor de Contratos -->
            <div class="bg-white rounded-2xl shadow-xl p-8 border border-blue-100">
                <div class="flex items-center space-x-3 mb-6">
                    <div class="bg-purple-600 text-white p-3 rounded-lg">
                        <i class="fas fa-file-contract"></i>
                    </div>
                    <h3 class="text-xl font-bold">Generador de Contratos/Cláusulas ✨</h3>
                </div>
                <p class="text-sm text-gray-500 mb-4">Crea borradores de contratos basados en la normativa de transporte.</p>
                <textarea id="contractInput" rows="3" class="w-full p-4 border rounded-xl mb-4 bg-gray-50 focus:ring-2 focus:ring-purple-500 outline-none" placeholder="Ej: Contrato de carga fraccionada, responsabilidad por retrasos, 1500€ de valor..."></textarea>
                <button onclick="generatePlan('contract')" id="contractBtn" class="w-full bg-purple-600 text-white font-bold py-3 rounded-xl hover:bg-purple-700 transition flex items-center justify-center space-x-2">
                    <span>Redactar Cláusulas ✨</span>
                    <div id="contractLoader" class="spinner hidden"></div>
                </button>
                <div id="contractOutput" class="mt-4 p-4 bg-purple-50 rounded-xl text-sm hidden whitespace-pre-line border border-purple-200"></div>
            </div>
        </div>
    </section>

    <!-- Secciones originales (Unidades y Competencias) -->
    <section id="unidades" class="py-16 bg-blue-50">
        <div class="container mx-auto px-4">
            <div class="text-center mb-16">
                <h2 class="text-3xl font-bold text-blue-900">Contenidos del Programa</h2>
                <p class="text-gray-600 mt-2">Basado en el manual oficial MF1012</p>
            </div>
            <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8" id="unitsGrid">
                <!-- Se rellena con JS -->
            </div>
        </div>
    </section>

    <!-- Footer -->
    <footer class="bg-gray-900 text-gray-400 py-12">
        <div class="container mx-auto px-4 text-center">
            <p class="text-sm">MF1012_3: Distribución Capilar + Gemini AI Integration</p>
            <p class="text-xs mt-2 uppercase tracking-widest opacity-50">Logística de Futuro</p>
        </div>
    </footer>

    <script>
        const apiKey = ""; // La plataforma inyectará la clave

        // Datos de las unidades (para renderizar)
        const units = [
            { id: 1, icon: 'fa-route', title: 'Reparto y Capilaridad', desc: 'Análisis de última milla y organización por zonas.' },
            { id: 2, icon: 'fa-calculator', title: 'Gestión Operativa', desc: 'Cálculo de costes y determinación de tarifas.' },
            { id: 3, icon: 'fa-van-shuttle', title: 'Vehículos y Normativa', desc: 'Clasificación, pesos y documentación técnica.' },
            { id: 4, icon: 'fa-clock', title: 'Planificación de Cargas', desc: 'Rutas, tacógrafo y cronogramas de entrega.' },
            { id: 5, icon: 'fa-file-signature', title: 'Contratación', desc: 'Seguros, responsabilidades y marco legal.' },
            { id: 6, icon: 'fa-leaf', title: 'Calidad y Ambiente', desc: 'Gestión de quejas y sostenibilidad logística.' }
        ];

        function renderUnits() {
            const grid = document.getElementById('unitsGrid');
            grid.innerHTML = units.map(u => `
                <div class="bg-white p-8 rounded-2xl shadow-sm card-hover border border-gray-100 opacity-0 translate-y-10 transition duration-700 unit-card">
                    <div class="text-blue-500 text-3xl mb-4"><i class="fas ${u.icon}"></i></div>
                    <h3 class="font-bold text-xl mb-3">${u.id}. ${u.title}</h3>
                    <p class="text-gray-500 text-sm leading-relaxed">${u.desc}</p>
                </div>
            `).join('');
        }

        async function callGemini(prompt) {
            const systemPrompt = "Eres un experto en logística de transporte y distribución capilar (MF1012). Ayuda al usuario a resolver tareas profesionales. Responde de forma clara, técnica pero concisa en español.";

            let retries = 0;
            const delays = [1000, 2000, 4000, 8000, 16000];

            while (retries < 5) {
                try {
                    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-09-2025:generateContent?key=${apiKey}`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            contents: [{ parts: [{ text: prompt }] }],
                            systemInstruction: { parts: [{ text: systemPrompt }] }
                        })
                    });

                    if (!response.ok) throw new Error('API Error');
                    const data = await response.json();
                    return data.candidates?.[0]?.content?.parts?.[0]?.text;
                } catch (error) {
                    retries++;
                    if (retries === 5) throw error;
                    await new Promise(r => setTimeout(r, delays[retries-1]));
                }
            }
        }

        async function generatePlan(type) {
            const inputId = type === 'route' ? 'routeInput' : 'contractInput';
            const outputId = type === 'route' ? 'routeOutput' : 'contractOutput';
            const loaderId = type === 'route' ? 'routeLoader' : 'contractLoader';

            const userInput = document.getElementById(inputId).value;
            const outputDiv = document.getElementById(outputId);
            const loader = document.getElementById(loaderId);

            if (!userInput) return;

            loader.classList.remove('hidden');
            outputDiv.classList.add('hidden');

            const prompt = type === 'route' 
                ? `Planifica una secuencia de ruta lógica para estas entregas, indicando posibles ahorros de tiempo y factores a considerar según el manual MF1012: ${userInput}`
                : `Redacta un borrador breve o las cláusulas legales clave para este supuesto de transporte basado en la Ley del Contrato de Transporte Terrestre: ${userInput}`;

            try {
                const result = await callGemini(prompt);
                outputDiv.textContent = result;
                outputDiv.classList.remove('hidden');
            } catch (err) {
                outputDiv.textContent = "Error al conectar con la IA. Por favor, inténtelo de nuevo más tarde.";
                outputDiv.classList.remove('hidden');
            } finally {
                loader.classList.add('hidden');
            }
        }

        function toggleMenu() {
            const menu = document.getElementById('mobileMenu');
            menu.classList.toggle('hidden');
        }

        window.onload = () => {
            renderUnits();
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('opacity-100', 'translate-y-0');
                        entry.target.classList.remove('opacity-0', 'translate-y-10');
                    }
                });
            }, { threshold: 0.1 });

            document.querySelectorAll('.unit-card').forEach(card => observer.observe(card));
        };
    </script>
</body>
</html>

