{
  "name": "Logística AI - MF1012",
  "description": "Plataforma moderna para la gestión de distribución capilar y transporte de mercancías potenciada por Gemini AI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { LucideIcon } from 'lucide-react';

export interface Unit {
  id: number;
  title: string;
  desc: string;
  iconName: string; 
}

export enum ToolType {
  ROUTE = 'ROUTE',
  CONTRACT = 'CONTRACT'
}

export interface GeneratedContentState {
  isLoading: boolean;
  content: string | null;
  error: string | null;
}

import { GoogleGenAI } from "@google/genai";
import { ToolType } from "../types";

const getSystemPrompt = (): string => {
  return "Eres un experto senior en logística de transporte y distribución capilar (MF1012), con amplio conocimiento en normativa de transporte, optimización de rutas y gestión de última milla. Tu objetivo es ayudar a profesionales del sector a resolver tareas complejas. Responde de forma clara, técnica, estructurada y concisa en español.";
};

const getToolPrompt = (type: ToolType, userInput: string): string => {
  if (type === ToolType.ROUTE) {
    return `Como experto en distribución capilar, planifica una secuencia de ruta lógica y eficiente para las siguientes entregas. Indica el orden óptimo, estimación de factores críticos (tráfico, horarios) y posibles ahorros de tiempo según el manual MF1012.

    Datos de entrada: "${userInput}"`;
  } else {
    return `Como experto legal en transporte de mercancías, redacta un borrador estructurado o las cláusulas legales clave para el siguiente supuesto, basándote en la Ley del Contrato de Transporte Terrestre y normativa vigente (LOTT/ROTT).

    Supuesto: "${userInput}"`;
  }
};

export const generateLogisticsResponse = async (
  type: ToolType, 
  userInput: string
): Promise<string> => {

  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your configuration.");
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Using gemini-3-flash-preview for fast, reasoning-capable text generation
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: getToolPrompt(type, userInput),
      config: {
        systemInstruction: getSystemPrompt(),
        temperature: 0.7, // Balanced creativity and precision
      },
    });

    if (response.text) {
      return response.text;
    }

    return "No se pudo generar una respuesta. Por favor, inténtelo de nuevo.";

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Error al conectar con el Asistente Logístico. Por favor verifique su conexión o intente más tarde.");
  }
};

