import React, { useState } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check } from 'lucide-react';
import { ToolType, GeneratedContentState } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';

interface AIToolCardProps {
  type: ToolType;
}

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
  });
  const [copied, setCopied] = useState(false);

  const isRoute = type === ToolType.ROUTE;
  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'Ej: 5 entregas en centro ciudad, 2 en periferia norte, prioridad urgente en calle Mayor...' 
      : 'Ej: Contrato de carga fraccionada, responsabilidad por retrasos de 2 horas, valor mercancía 1500€...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega considerando tráfico y prioridades.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.'
  };

  const handleGenerate = async () => {
    if (!input.trim()) return;

    setState({ isLoading: true, content: null, error: null });
    try {
      const result = await generateLogisticsResponse(type, input);
      setState({ isLoading: false, content: result, error: null });
    } catch (err: any) {
      setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
    }
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center space-x-4 mb-6">
          <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
            <Icon size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
            <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                <Sparkles size={12} className="text-amber-500" />
                <span>AI Powered</span>
            </div>
          </div>
        </div>

        <p className="text-slate-500 mb-6 text-sm leading-relaxed min-h-[40px]">
            {config.description}
        </p>

        <div className="relative mb-6">
            <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            rows={4}
            className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 focus:ring-opacity-50 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400"
            style={{ 
                //@ts-ignore
                '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
            }}
            placeholder={config.placeholder}
            />
        </div>

        <button
          onClick={handleGenerate}
          disabled={state.isLoading || !input.trim()}
          className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed`}
        >
          {state.isLoading ? (
            <>
              <Loader2 className="animate-spin" size={20} />
              <span>Analizando datos...</span>
            </>
          ) : (
            <>
              <Sparkles size={20} />
              <span>Generar Respuesta</span>
            </>
          )}
        </button>

        {state.error && (
          <div className="mt-4 p-4 bg-red-50 text-red-600 text-sm rounded-xl border border-red-100 flex items-start gap-2">
             <span>⚠️</span>
             <p>{state.error}</p>
          </div>
        )}

        {state.content && (
          <div className={`mt-6 p-5 ${config.lightBg} rounded-xl border ${config.borderColor} relative group animate-in fade-in slide-in-from-bottom-4 duration-500`}>
             <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                    onClick={handleCopy}
                    className="p-2 bg-white rounded-lg shadow-sm hover:bg-slate-50 text-slate-600 transition"
                    title="Copiar texto"
                >
                    {copied ? <Check size={16} className="text-green-500" /> : <Copy size={16} />}
                </button>
             </div>
             <div className="prose prose-sm prose-slate max-w-none">
                 <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                     {state.content}
                 </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Route, Calculator, Truck, Clock, FileSignature, Leaf } from 'lucide-react';
import { Unit } from '../types';

export const UnitsSection: React.FC = () => {
  const units: Unit[] = [
    { id: 1, iconName: 'route', title: 'Reparto y Capilaridad', desc: 'Análisis estratégico de la última milla, diseño de redes y organización operativa por zonas geográficas.' },
    { id: 2, iconName: 'calculator', title: 'Gestión Operativa', desc: 'Cálculo avanzado de costes logísticos, escandallos y determinación de tarifas competitivas.' },
    { id: 3, iconName: 'truck', title: 'Vehículos y Normativa', desc: 'Clasificación técnica de flota, gestión de pesos y dimensiones, y documentación obligatoria.' },
    { id: 4, iconName: 'clock', title: 'Planificación de Cargas', desc: 'Optimización de rutas de reparto, gestión de tiempos de conducción (tacógrafo) y cronogramas.' },
