import { GoogleGenAI } from "@google/genai";
import { ToolType } from "../types";

const getSystemPrompt = (): string => {
  return "Eres un experto senior en logística de transporte y distribución capilar (MF1012), con amplio conocimiento en normativa de transporte, optimización de rutas y gestión de última milla. Tu objetivo es ayudar a profesionales del sector a resolver tareas complejas. Responde de forma clara, técnica, estructurada y concisa en español. Utiliza formato Markdown para estructurar la respuesta (listas, negritas, encabezados).";
};

const getToolPrompt = (type: ToolType, userInput: string): string => {
  if (type === ToolType.ROUTE) {
    return `Como experto en distribución capilar, planifica una secuencia de ruta lógica y eficiente para las siguientes entregas. Indica el orden óptimo, estimación de factores críticos (tráfico, horarios) y posibles ahorros de tiempo según el manual MF1012.

    Datos de entrada: "${userInput}"`;
  } else {
    return `Como experto legal en transporte de mercancías, redacta un borrador estructurado o las cláusulas legales clave para el siguiente supuesto, basándote en la Ley del Contrato de Transporte Terrestre y normativa vigente (LOTT/ROTT).

    Supuesto: "${userInput}"`;
  }
};

export const generateLogisticsResponse = async function* (
  type: ToolType, 
  userInput: string
): AsyncGenerator<string, void, unknown> {

  if (!process.env.API_KEY) {
    throw new Error("API Key no configurada. Por favor, revisa las variables de entorno.");
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Upgrade to gemini-3-pro-preview for complex logistics reasoning tasks
    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: getToolPrompt(type, userInput),
      config: {
        systemInstruction: getSystemPrompt(),
        temperature: 0.7,
      },
    });

    for await (const chunk of response) {
      const text = chunk.text;
      if (text) {
        yield text;
      }
    }

  } catch (error: any) {
    console.error("Gemini API Error:", error);

    let message = "Ocurrió un error inesperado al procesar tu solicitud.";

    if (error.message) {
        if (error.message.includes("API key")) {
            message = "Error de autenticación: API Key inválida o no detectada.";
        } else if (error.message.includes("429")) {
            message = "El servicio está saturado (Límite de cuota excedido). Por favor espera unos momentos antes de reintentar.";
        } else if (error.message.includes("503") || error.message.includes("500")) {
            message = "El servicio de IA no está disponible temporalmente. Inténtalo más tarde.";
        } else if (error.message.includes("safety")) {
            message = "La solicitud fue bloqueada por los filtros de seguridad del contenido.";
        } else {
            message = `Error del sistema: ${error.message}`;
        }
    }

    throw new Error(message);
  }
};

