import { GoogleGenAI, Type } from "@google/genai";
import { ToolType, MapPoint } from "../types";

const getSystemPrompt = (): string => {
  return "Eres un consultor experto senior en logística integral. Manejas a la perfección el manual MF1012 (Distribución Capilar), MF1013 (Transporte de Larga Distancia) y la normativa ADR (Mercancías Peligrosas). Tu objetivo es ayudar a profesionales del sector a resolver dudas técnicas, operativas y legales. Responde de forma técnica, rápida, estructurada y en español.";
};

export const generateLogisticsResponse = async function* (
  type: ToolType, 
  userInput: string,
  points?: MapPoint[]
): AsyncGenerator<string, void, unknown> {

  if (!process.env.API_KEY) {
    throw new Error("API Key no configurada. Por favor, revisa las variables de entorno.");
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = "";
    let schema: any = undefined;

    if (type === ToolType.ROUTE) {
      const pointsInfo = points && points.length > 0 
        ? `\nPuntos de entrega seleccionados en el mapa (índices 0 a ${points.length - 1}):\n${points.map((p, i) => `[${i}] Lat: ${p.lat}, Lng: ${p.lng}`).join('\n')}`
        : "";

      prompt = `Planifica una secuencia de ruta lógica y eficiente. ${pointsInfo}\n\nInstrucciones adicionales del usuario: "${userInput}"\n\nSi hay puntos en el mapa, devuelve el campo 'optimizedSequence' con el orden de los índices.`;

      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING, description: "Explicación detallada de la ruta optimizada en formato Markdown." },
          optimizedSequence: { 
            type: Type.ARRAY, 
            items: { type: Type.INTEGER },
            description: "Lista de índices de los puntos en el orden optimizado."
          }
        },
        required: ["explanation"]
      };
    } else if (type === ToolType.CONTRACT) {
      prompt = `Redacta un borrador estructurado o las cláusulas legales clave para el siguiente supuesto, basándote en la Ley del Contrato de Transporte Terrestre y normativa vigente (LOTT/ROTT).\n\nSupuesto: "${userInput}"`;
      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING }
        },
        required: ["explanation"]
      };
    } else {
      prompt = `Responde a la siguiente consulta técnica sobre logística integral, normativa internacional o mercancías peligrosas (ADR):\n\nConsulta: "${userInput}"`;
      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING }
        },
        required: ["explanation"]
      };
    }

    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemPrompt(),
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: schema
      },
    });

    let fullJson = "";
    for await (const chunk of response) {
      const text = chunk.text;
      if (text) {
        fullJson += text;
        // Yielding full string to be parsed by component if needed, 
        // but since it's JSON streaming, we might need a special approach.
        // For simplicity in this implementation, we will yield the raw JSON chunks.
        yield text;
      }
    }

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let message = error.message || "Error desconocido";
    throw new Error(message);
  }
};

import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, MapPin } from 'lucide-react';

// Fix for default marker icons in Leaflet with React
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
}

const MapEvents = ({ onAdd }: { onAdd: (lat: number, lng: number) => void }) => {
  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence }) => {
  const [center] = useState<[number, number]>([40.4168, -3.7038]); // Madrid as default

  const handleAddPoint = (lat: number, lng: number) => {
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: `Punto ${points.length + 1}`
    };
    onPointsChange([...points, newPoint]);
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
  };

  const routePath = routeSequence && routeSequence.length > 0
    ? routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number])
    : [];

  return (
    <div className="flex flex-col gap-4">
      <div className="h-[300px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative group">
        <MapContainer center={center} zoom={13} scrollWheelZoom={false}>
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapEvents onAdd={handleAddPoint} />
          {points.map((point, index) => (
            <Marker key={point.id} position={[point.lat, point.lng]}>
              <Popup>
                <div className="p-1">
                  <p className="font-bold text-slate-800">{point.label || `Punto ${index}`}</p>
                  <button 
                    onClick={() => handleRemovePoint(point.id)}
                    className="mt-2 text-xs text-red-600 flex items-center gap-1 hover:underline"
                  >
                    <Trash2 size={12} /> Eliminar
                  </button>
                </div>
              </Popup>
            </Marker>
          ))}
          {routePath.length > 1 && (
            <Polyline positions={routePath} color="#2563eb" weight={4} opacity={0.7} dashArray="10, 10" />
          )}
        </MapContainer>

        <div className="absolute bottom-4 right-4 z-[1000] bg-white/90 backdrop-blur p-2 rounded-lg border border-slate-200 shadow-sm text-[10px] text-slate-500 font-medium pointer-events-none">
          Click en el mapa para añadir puntos
        </div>
      </div>

      {points.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {points.map((p, i) => (
            <div key={p.id} className="bg-slate-100 border border-slate-200 rounded-full px-3 py-1 flex items-center gap-2 text-xs">
              <MapPin size={12} className="text-brand-600" />
              <span className="font-semibold">#{i}</span>
              <button onClick={() => handleRemovePoint(p.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                <Trash2 size={12} />
              </button>
            </div>
          ))}
          <button 
            onClick={() => onPointsChange([])}
            className="text-xs text-slate-400 hover:text-slate-600 underline ml-2"
          >
            Limpiar todo
          </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if (state.isLoading && state.content && resultRef.current) {
        if (state.content.length < 100) {
            resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
    }
  }, [state.isLoading, state.content]);

  const isRoute = type === ToolType.ROUTE;
  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'Añade puntos en el mapa o describe tu ruta aquí: 5 entregas en centro ciudad...' 
      : 'Ej: Contrato de carga fraccionada, responsabilidad por retrasos de 2 horas...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo desde el punto 0 a las 9:00 AM."
      : "Redacta una cláusula para un contrato de transporte continuado donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleGenerate = async () => {
    if (!input.trim() || state.isLoading) return;

    setState({ isLoading: true, content: '', error: null, routeData: undefined });

    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        fullJsonString += chunk;

        // Try to partially parse explanation for streaming UI
        try {
            // Very basic extraction since it's JSON
            // Look for content between "explanation": " and the next unescaped quote
            const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
            if (match && match[1]) {
                const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
                setState(prev => ({ ...prev, content: partialText }));
            }
        } catch (e) {
            // Silent catch for partial JSON
        }
      }

      if (isMounted.current) {
        try {
            const finalData = JSON.parse(fullJsonString) as RouteResponse;
            setState({ 
                isLoading: false, 
                content: finalData.explanation, 
                error: null,
                routeData: finalData.optimizedSequence
            });
        } catch (e) {
            setState(prev => ({ ...prev, isLoading: false }));
        }
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
      }
    }
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center space-x-4 mb-6">
          <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
            <Icon size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
            <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                <Sparkles size={12} className="text-amber-500" />
                <span>AI Guided Mapping</span>
            </div>
          </div>
        </div>

        <p className="text-slate-500 mb-6 text-sm leading-relaxed min-h-[40px]">
            {config.description}
        </p>

        {isRoute && (
            <div className="mb-6">
                <LogisticsMap 
                    points={points} 
                    onPointsChange={setPoints} 
                    routeSequence={state.routeData}
                />
            </div>
        )}

        <div className="flex justify-end mb-2">
            <button
                type="button"
                onClick={handleExampleClick}
                disabled={state.isLoading}
                className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100 border-brand-200' : 'text-purple-700 bg-purple-50 hover:bg-purple-100 border-purple-200'} border px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 shadow-sm group disabled:opacity-50`}
            >
                <Sparkles size={14} className="group-hover:text-amber-500 transition-colors" />
                Ver Ejemplo
            </button>
        </div>

        <div className="relative mb-6">
            <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={state.isLoading}
            rows={isRoute ? 3 : 5}
            className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 focus:ring-opacity-50 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400 disabled:bg-slate-100 disabled:text-slate-500"
            style={{ 
                //@ts-ignore
                '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
            }}
            placeholder={config.placeholder}
            />
        </div>

        <button
          onClick={handleGenerate}
          disabled={state.isLoading || (!input.trim() && points.length === 0)}
          className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed ${state.isLoading ? 'cursor-wait' : ''}`}
        >
          {state.isLoading ? (
            <>
              <Loader2 className="animate-spin" size={20} />
              <span>Optimizando...</span>
            </>
          ) : (
            <>
              <Sparkles size={20} />
              <span>Optimizar con IA</span>
            </>
          )}
