import React, { useEffect, useState, useCallback } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, MapPin, Search, Navigation, Loader2 } from 'lucide-react';

// Fix for default marker icons
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
}

// Component to handle map clicks and centering
const MapController = ({ onAdd, centerOn }: { onAdd: (lat: number, lng: number, label?: string) => void, centerOn?: [number, number] }) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 15);
    }
  }, [centerOn, map]);

  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Punto ${points.length + 1}`;
    } catch {
      return `Punto ${points.length + 1}`;
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: finalLabel
    };
    onPointsChange([...points, newPoint]);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const latitude = parseFloat(lat);
        const longitude = parseFloat(lon);
        setCenterOn([latitude, longitude]);
        handleAddPoint(latitude, longitude, display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Search error", err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setCenterOn([pos.coords.latitude, pos.coords.longitude]);
      });
    }
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
  };

  const routePath = routeSequence && routeSequence.length > 0
    ? routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number])
    : [];

  return (
    <div className="flex flex-col gap-4">
      {/* Search Bar */}
      <form onSubmit={handleSearch} className="relative flex gap-2">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar dirección para entrega..."
                className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
            />
        </div>
        <button 
            type="submit"
            disabled={isSearching}
            className="bg-brand-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-brand-700 transition flex items-center gap-2"
        >
            {isSearching ? <Loader2 size={16} className="animate-spin" /> : 'Añadir'}
        </button>
        <button 
            type="button"
            onClick={handleCurrentLocation}
            className="p-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition shadow-sm"
            title="Mi ubicación"
        >
            <Navigation size={20} />
        </button>
      </form>

      {/* Map Container */}
      <div className="h-[350px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative z-0">
        <MapContainer center={[40.4168, -3.7038]} zoom={13} scrollWheelZoom={true}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapController onAdd={handleAddPoint} centerOn={centerOn} />
          {points.map((point, index) => (
            <Marker key={point.id} position={[point.lat, point.lng]}>
              <Popup>
                <div className="p-1 min-w-[120px]">
                  <p className="font-bold text-slate-900 text-sm mb-1">{point.label}</p>
                  <p className="text-[10px] text-slate-500 mb-2">Orden: {index}</p>
                  <button 
                    onClick={() => handleRemovePoint(point.id)}
                    className="w-full text-xs text-red-600 bg-red-50 py-1.5 rounded-lg flex items-center justify-center gap-1 hover:bg-red-100 transition"
                  >
                    <Trash2 size={12} /> Eliminar
                  </button>
                </div>
              </Popup>
            </Marker>
          ))}
          {routePath.length > 1 && (
            <Polyline 
                positions={routePath} 
                color="#2563eb" 
                weight={5} 
                opacity={0.8} 
                lineCap="round"
                dashArray="1, 10"
            />
          )}
        </MapContainer>

        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2">
            <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 shadow-sm text-[10px] text-slate-600 font-bold uppercase tracking-wider flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></div>
                Modo Interactivo
            </div>
        </div>
      </div>

      {/* Points List */}
      {points.length > 0 && (
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4">
            <div className="flex justify-between items-center mb-3">
                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Puntos de Ruta ({points.length})</h4>
                <button 
                    onClick={() => onPointsChange([])}
                    className="text-[10px] font-bold text-red-600 hover:underline uppercase"
                >
                    Borrar Todo
                </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {points.map((p, i) => (
                    <div key={p.id} className="bg-white border border-slate-100 rounded-xl p-2.5 flex items-center gap-3 shadow-sm group">
                        <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center text-[10px] font-black shrink-0">
                            {i}
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-xs font-semibold text-slate-800 truncate">{p.label}</p>
                        </div>
                        <button 
                            onClick={() => handleRemovePoint(p.id)} 
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                ))}
            </div>
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { ToolType, MapPoint } from "../types";

const getSystemPrompt = (): string => {
  return "Eres un consultor experto senior en logística integral. Manejas a la perfección el manual MF1012 (Distribución Capilar), MF1013 (Transporte de Larga Distancia) y la normativa ADR (Mercancías Peligrosas). Tu objetivo es ayudar a profesionales del sector a resolver dudas técnicas, operativas y legales. Responde de forma técnica, rápida, estructurada y en español.";
};

export const generateLogisticsResponse = async function* (
  type: ToolType, 
  userInput: string,
  points?: MapPoint[]
): AsyncGenerator<string, void, unknown> {

  if (!process.env.API_KEY) {
    throw new Error("API Key no configurada. Por favor, revisa las variables de entorno.");
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = "";
    let schema: any = undefined;

    if (type === ToolType.ROUTE) {
      const pointsInfo = points && points.length > 0 
        ? `\nLISTADO DE ENTREGAS (Mapa):\n${points.map((p, i) => `[ID ${i}] Nombre/Zona: ${p.label} (Lat: ${p.lat}, Lng: ${p.lng})`).join('\n')}`
        : "";

      prompt = `Actúa como un planificador de tráfico avanzado. Optimiza la siguiente ruta de distribución capilar basándote en la eficiencia de última milla. 
      ${pointsInfo}

      Instrucciones adicionales: "${userInput}"

      Debes devolver:
      1. Una explicación detallada paso a paso, mencionando los nombres de las calles/puntos proporcionados.
      2. El orden numérico óptimo de los índices [ID X] en el campo optimizedSequence.`;

      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING, description: "Análisis logístico paso a paso usando nombres de calles y consejos de eficiencia." },
          optimizedSequence: { 
            type: Type.ARRAY, 
            items: { type: Type.INTEGER },
            description: "Secuencia numérica de los índices proporcionados (ej: [0, 2, 1])."
          }
        },
        required: ["explanation", "optimizedSequence"]
      };
    } else if (type === ToolType.CONTRACT) {
      prompt = `Redacta un borrador estructurado o las cláusulas legales clave para el siguiente supuesto, basándote en la Ley del Contrato de Transporte Terrestre y normativa vigente (LOTT/ROTT).\n\nSupuesto: "${userInput}"`;
      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING }
        },
        required: ["explanation"]
      };
    } else {
      prompt = `Responde a la siguiente consulta técnica sobre logística integral, normativa internacional o mercancías peligrosas (ADR):\n\nConsulta: "${userInput}"`;
      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING }
        },
        required: ["explanation"]
      };
    }

    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemPrompt(),
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: schema
      },
    });

    let fullJson = "";
    for await (const chunk of response) {
      const text = chunk.text;
      if (text) {
        fullJson += text;
        yield text;
      }
    }

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let message = error.message || "Error desconocido";
    throw new Error(message);
  }
};

