import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  // Auto-scroll to result area when content starts appearing or error occurs
  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isRoute = type === ToolType.ROUTE;
  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'Añade puntos en el mapa o describe tu ruta aquí: 5 entregas en centro ciudad...' 
      : 'Ej: Contrato de carga fraccionada, responsabilidad por retrasos de 2 horas...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo desde el punto 0 a las 9:00 AM."
      : "Redacta una cláusula para un contrato de transporte continuado donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleGenerate = async () => {
    if ((!input.trim() && points.length === 0) || state.isLoading) return;

    setState({ isLoading: true, content: '', error: null, routeData: undefined });

    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        fullJsonString += chunk;

        try {
            const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
            if (match && match[1]) {
                const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
                setState(prev => ({ ...prev, content: partialText }));
            }
        } catch (e) {}
      }

      if (isMounted.current) {
        try {
            const finalData = JSON.parse(fullJsonString) as RouteResponse;
            setState({ 
                isLoading: false, 
                content: finalData.explanation, 
                error: null,
                routeData: finalData.optimizedSequence
            });
        } catch (e) {
            setState(prev => ({ ...prev, isLoading: false }));
        }
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
      }
    }
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center space-x-4 mb-6">
          <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
            <Icon size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
            <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                <Sparkles size={12} className="text-amber-500" />
                <span>AI Guided Mapping</span>
            </div>
          </div>
        </div>

        <p className="text-slate-500 mb-6 text-sm leading-relaxed min-h-[40px]">
            {config.description}
        </p>

        {isRoute && (
            <div className="mb-6">
                <LogisticsMap 
                    points={points} 
                    onPointsChange={setPoints} 
                    routeSequence={state.routeData}
                />
            </div>
        )}

        <div className="flex justify-end mb-2">
            <button
                type="button"
                onClick={handleExampleClick}
                disabled={state.isLoading}
                className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100 border-brand-200' : 'text-purple-700 bg-purple-50 hover:bg-purple-100 border-purple-200'} border px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 shadow-sm group disabled:opacity-50`}
            >
                <Sparkles size={14} className="group-hover:text-amber-500 transition-colors" />
                Ver Ejemplo
            </button>
        </div>

        <div className="relative mb-6">
            <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={state.isLoading}
            rows={isRoute ? 3 : 5}
            className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 focus:ring-opacity-50 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400 disabled:bg-slate-100 disabled:text-slate-500"
            style={{ 
                //@ts-ignore
                '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
            }}
            placeholder={config.placeholder}
            />
        </div>

        <button
          onClick={handleGenerate}
          disabled={state.isLoading || (!input.trim() && points.length === 0)}
          className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed ${state.isLoading ? 'cursor-wait' : ''}`}
        >
          {state.isLoading ? (
            <>
              <Loader2 className="animate-spin" size={20} />
              <span>Optimizando...</span>
            </>
          ) : (
            <>
              <Sparkles size={20} />
              <span>Optimizar con IA</span>
            </>
          )}
        </button>

        <div ref={resultRef} className="scroll-mt-24">
          {state.error && (
            <div className="mt-4 p-4 bg-red-50 text-red-800 text-sm rounded-xl border border-red-200 flex flex-col gap-2 animate-in fade-in slide-in-from-top-2">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="shrink-0 mt-0.5 text-red-600" size={18} />
                   <div className="flex-1">
                      <p className="font-medium text-red-900 mb-1">Error al procesar la ruta</p>
                      <p className="text-red-700 leading-relaxed">{state.error}</p>
                   </div>
               </div>
               <button 
                  onClick={handleGenerate}
                  className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-red-200 text-red-700 text-xs font-semibold rounded-lg hover:bg-red-50 hover:border-red-300 transition-all shadow-sm"
               >
                  <RefreshCw size={12} /> Reintentar
               </button>
            </div>
          )}

          {state.content !== null && (
            <div 
              className={`mt-6 p-5 ${config.lightBg} rounded-xl border ${config.borderColor} relative group animate-in fade-in slide-in-from-bottom-4 duration-500`}
            >
               <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                      onClick={handleCopy}
                      className="p-2 bg-white rounded-lg shadow-sm hover:bg-slate-50 text-slate-600 transition"
                      title="Copiar texto"
                  >
                      {copied ? <Check size={16} className="text-green-500" /> : <Copy size={16} />}
                  </button>
               </div>
               <div className="prose prose-sm prose-slate max-w-none">
                   <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                       {state.content}
                       {state.isLoading && (
                         <span className="inline-block w-1.5 h-4 ml-1 bg-current opacity-70 align-middle animate-pulse">|</span>
                       )}
                   </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

