    if (!input.trim() || state.isLoading) return;

    setState({ isLoading: true, content: '', error: null });

    try {
      const stream = generateLogisticsResponse(ToolType.CONSULTANT, input);
      let fullContent = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        // The consultant currently returns raw text directly, not JSON with explanation field
        // as the ToolType.CONSULTANT prompt in geminiService doesn't enforce JSON schema yet in a simple way
        // but we handle it as raw chunks here. 
        // Note: geminiService.ts handles JSON responseSchema for all tools now.

        try {
          const match = chunk.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/) || chunk.match(/"explanation":\s*"(.*)"/);
          if (match && match[1]) {
             fullContent += match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
          } else if (!chunk.includes('{')) {
             // Fallback for non-json chunks or raw text if schema fails
             fullContent += chunk;
          }
        } catch (e) {
          fullContent += chunk;
        }

        setState(prev => ({
          ...prev,
          content: fullContent
        }));
      }

      if (isMounted.current) {
        setState(prev => ({ ...prev, isLoading: false }));
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message });
      }
    }
  };

  return (
    <section className="py-12 bg-slate-50 border-y border-slate-200" id="consultor">
      <div className="container mx-auto px-4">
        <div className="mb-8 text-center max-w-3xl mx-auto">
            <h2 className="text-3xl font-bold text-slate-900 mb-2">Consultor Logístico Integral</h2>
            <p className="text-slate-600">
                Resuelve dudas sobre MF1012, MF1013 y Normativa ADR en tiempo real.
            </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-6">
            {/* AI Input Section */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col h-full">
                <h3 className="font-bold text-lg mb-4 text-slate-800 flex items-center gap-2">
                    <Brain className="text-blue-600" size={24} />
                    <span>Pregunta al Experto</span>
                </h3>

                <textarea 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    disabled={state.isLoading}
                    className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 text-sm min-h-[120px] focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all resize-none placeholder:text-slate-400" 
                    placeholder="Ej: ¿Qué Incoterm usar para transporte marítimo? o ¿Qué paneles debe llevar un camión con explosivos?"
                ></textarea>

                <button 
                    onClick={handleConsult}
                    disabled={state.isLoading || !input.trim()}
                    className="mt-4 w-full bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white py-3.5 rounded-xl font-bold flex items-center justify-center space-x-2 transition-all shadow-md"
                >
                    {state.isLoading ? (
                        <>
                            <Loader2 className="animate-spin" size={18} />
                            <span>Analizando normativa...</span>
                        </>
                    ) : (
                        <>
                            <span>Consultar a Gemini</span>
                            <Send size={16} />
                        </>
                    )}
                </button>

                {/* AI Output Area */}
                <div ref={resultRef} className="scroll-mt-24">
                  {(state.content || state.error) && (
                      <div 
                          className={`mt-6 p-5 rounded-xl text-sm leading-relaxed border-l-4 animate-in fade-in slide-in-from-top-2 duration-300 ${state.error ? 'bg-red-50 border-red-500 text-red-800' : 'bg-slate-50 border-blue-600 text-slate-700'}`}
                      >
                           {state.error ? (
                               <p>{state.error}</p>
                           ) : (
                               <div className="prose prose-sm prose-slate max-w-none">
                                  <div className="whitespace-pre-wrap font-medium">
                                      {state.content}
                                      {state.isLoading && <span className="inline-block w-1.5 h-4 ml-1 bg-blue-600 animate-pulse align-middle"></span>}
                                  </div>
                               </div>
                           )}
                      </div>
                  )}
                </div>
            </div>

            {/* Dashboard Cards */}
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100 flex flex-col justify-center items-center text-center transition-transform hover:scale-[1.02]">
                    <Radiation className="text-orange-600 mb-3" size={32} />
                    <span className="text-xs font-bold text-orange-800 uppercase tracking-wide">ADR Clases</span>
                    <span className="text-3xl font-black text-orange-900 mt-1">9</span>
                    <span className="text-xs text-orange-700/70 mt-1">Grupos Peligrosos</span>
