import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2 } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [isLocating, setIsLocating] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;

        try {
          // Geocodificación inversa rápida
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          // Añadimos como primer punto (punto de partida)
          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          console.error("Error geocoding current location", err);
        } finally {
          setIsLocating(false);
        }
      },
      (err) => {
        console.error("Geolocation error", err);
        setIsLocating(false);
        alert("No se pudo obtener tu ubicación. Asegúrate de dar permisos en el navegador.");
      },
      { enableHighAccuracy: true }
    );
  };

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'Añade puntos en el mapa o describe tu ruta aquí: 5 entregas en centro ciudad...' 
      : 'Ej: Contrato de carga fraccionada, responsabilidad por retrasos de 2 horas...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo desde el punto 0 a las 9:00 AM."
      : "Redacta una cláusula para un contrato de transporte continuado donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleGenerate = async () => {
    if ((!input.trim() && points.length === 0) || state.isLoading) return;

    setState({ isLoading: true, content: '', error: null, routeData: undefined });

    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        fullJsonString += chunk;

        try {
            const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
            if (match && match[1]) {
                const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
                setState(prev => ({ ...prev, content: partialText }));
            }
        } catch (e) {}
      }

      if (isMounted.current) {
        try {
            const finalData = JSON.parse(fullJsonString) as RouteResponse;
            setState({ 
                isLoading: false, 
                content: finalData.explanation, 
                error: null,
                routeData: finalData.optimizedSequence
            });
        } catch (e) {
            setState(prev => ({ ...prev, isLoading: false }));
        }
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
      }
    }
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                  <Sparkles size={12} className="text-amber-500" />
                  <span>AI Guided Mapping</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={handleAddCurrentLocation}
              disabled={isLocating}
              className="hidden sm:flex items-center gap-2 px-4 py-2 bg-brand-50 text-brand-700 text-xs font-bold rounded-xl border border-brand-200 hover:bg-brand-100 transition-all shadow-sm group"
            >
              {isLocating ? (
                <Loader2 size={16} className="animate-spin" />
              ) : (
                <Navigation2 size={16} className="group-hover:translate-y-[-2px] transition-transform" />
              )}
              {isLocating ? "Localizando..." : "Mi Ubicación como Origen"}
            </button>
          )}
        </div>

        <p className="text-slate-500 mb-6 text-sm leading-relaxed min-h-[40px]">
            {config.description}
        </p>

        {isRoute && (
            <div className="mb-6">
                <div className="sm:hidden mb-4">
                  <button 
                    onClick={handleAddCurrentLocation}
                    disabled={isLocating}
                    className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-brand-50 text-brand-700 text-sm font-bold rounded-xl border border-brand-200"
                  >
                    <Navigation2 size={18} />
                    {isLocating ? "Localizando..." : "Usar mi ubicación actual"}
                  </button>
                </div>
                <LogisticsMap 
                    points={points} 
                    onPointsChange={setPoints} 
                    routeSequence={state.routeData}
                    externalCenter={externalCenter}
                />
            </div>
        )}

        <div className="flex justify-end mb-2">
            <button
                type="button"
                onClick={handleExampleClick}
                disabled={state.isLoading}
                className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100 border-brand-200' : 'text-purple-700 bg-purple-50 hover:bg-purple-100 border-purple-200'} border px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 shadow-sm group disabled:opacity-50`}
            >
                <Sparkles size={14} className="group-hover:text-amber-500 transition-colors" />
                Ver Ejemplo
            </button>
        </div>

        <div className="relative mb-6">
            <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={state.isLoading}
            rows={isRoute ? 3 : 5}
            className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 focus:ring-opacity-50 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400 disabled:bg-slate-100 disabled:text-slate-500"
            style={{ 
                //@ts-ignore
                '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
            }}
            placeholder={config.placeholder}
            />
        </div>

        <button
          onClick={handleGenerate}
          disabled={state.isLoading || (!input.trim() && points.length === 0)}
          className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed ${state.isLoading ? 'cursor-wait' : ''}`}
        >
          {state.isLoading ? (
            <>
              <Loader2 className="animate-spin" size={20} />
              <span>Optimizando...</span>
            </>
          ) : (
            <>
              <Sparkles size={20} />
              <span>Optimizar con IA</span>
            </>
          )}
        </button>

        <div ref={resultRef} className="scroll-mt-24">
          {state.error && (
            <div className="mt-4 p-4 bg-red-50 text-red-800 text-sm rounded-xl border border-red-200 flex flex-col gap-2 animate-in fade-in slide-in-from-top-2">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="shrink-0 mt-0.5 text-red-600" size={18} />
                   <div className="flex-1">
                      <p className="font-medium text-red-900 mb-1">Error al procesar la ruta</p>
                      <p className="text-red-700 leading-relaxed">{state.error}</p>
                   </div>
               </div>
               <button 
                  onClick={handleGenerate}
                  className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-red-200 text-red-700 text-xs font-semibold rounded-lg hover:bg-red-50 hover:border-red-300 transition-all shadow-sm"
               >
                  <RefreshCw size={12} /> Reintentar
               </button>
            </div>
          )}

          {state.content !== null && (
            <div 
              className={`mt-6 p-5 ${config.lightBg} rounded-xl border ${config.borderColor} relative group animate-in fade-in slide-in-from-bottom-4 duration-500`}
            >
               <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                      onClick={handleCopy}
                      className="p-2 bg-white rounded-lg shadow-sm hover:bg-slate-50 text-slate-600 transition"
                      title="Copiar texto"
                  >
                      {copied ? <Check size={16} className="text-green-500" /> : <Copy size={16} />}
                  </button>
               </div>
               <div className="prose prose-sm prose-slate max-w-none">
                   <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                       {state.content}
                       {state.isLoading && (
                         <span className="inline-block w-1.5 h-4 ml-1 bg-current opacity-70 align-middle animate-pulse">|</span>
                       )}
                   </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useCallback } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, MapPin, Search, Navigation, Loader2 } from 'lucide-react';

// Fix for default marker icons
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
  externalCenter?: [number, number];
}

// Component to handle map clicks and centering
const MapController = ({ onAdd, centerOn }: { onAdd: (lat: number, lng: number, label?: string) => void, centerOn?: [number, number] }) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 15);
    }
  }, [centerOn, map]);

  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  // Reaccionar a cambios externos (como el botón GPS en AIToolCard)
  useEffect(() => {
    if (externalCenter) {
      setCenterOn(externalCenter);
    }
  }, [externalCenter]);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Punto ${points.length + 1}`;
    } catch {
      return `Punto ${points.length + 1}`;
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: finalLabel
    };
    onPointsChange([...points, newPoint]);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const latitude = parseFloat(lat);
        const longitude = parseFloat(lon);
        setCenterOn([latitude, longitude]);
        handleAddPoint(latitude, longitude, display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Search error", err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setCenterOn([pos.coords.latitude, pos.coords.longitude]);
      });
    }
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
  };

  const routePath = routeSequence && routeSequence.length > 0
    ? routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number])
    : [];

  return (
    <div className="flex flex-col gap-4">
      {/* Search Bar */}
      <form onSubmit={handleSearch} className="relative flex gap-2">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar dirección para entrega..."
                className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
            />
        </div>
        <button 
            type="submit"
            disabled={isSearching}
            className="bg-brand-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-brand-700 transition flex items-center gap-2"
        >
            {isSearching ? <Loader2 size={16} className="animate-spin" /> : 'Añadir'}
        </button>
        <button 
            type="button"
            onClick={handleCurrentLocation}
            className="p-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition shadow-sm"
            title="Mi ubicación"
        >
            <Navigation size={20} />
        </button>
      </form>

      {/* Map Container */}
      <div className="h-[350px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative z-0">
        <MapContainer center={[40.4168, -3.7038]} zoom={13} scrollWheelZoom={true}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapController onAdd={handleAddPoint} centerOn={centerOn} />
          {points.map((point, index) => (
            <Marker key={point.id} position={[point.lat, point.lng]}>
              <Popup>
                <div className="p-1 min-w-[120px]">
                  <p className="font-bold text-slate-900 text-sm mb-1">{point.label}</p>
                  <p className="text-[10px] text-slate-500 mb-2">Orden: {index}</p>
                  <button 
                    onClick={() => handleRemovePoint(point.id)}
                    className="w-full text-xs text-red-600 bg-red-50 py-1.5 rounded-lg flex items-center justify-center gap-1 hover:bg-red-100 transition"
                  >
                    <Trash2 size={12} /> Eliminar
                  </button>
                </div>
              </Popup>
            </Marker>
          ))}
          {routePath.length > 1 && (
            <Polyline 
                positions={routePath} 
                color="#2563eb" 
                weight={5} 
                opacity={0.8} 
                lineCap="round"
                dashArray="1, 10"
            />
          )}
        </MapContainer>

        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2">
            <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 shadow-sm text-[10px] text-slate-600 font-bold uppercase tracking-wider flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></div>
                Modo Interactivo
            </div>
        </div>
      </div>

      {/* Points List */}
      {points.length > 0 && (
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4">
            <div className="flex justify-between items-center mb-3">
                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Puntos de Ruta ({points.length})</h4>
                <button 
                    onClick={() => onPointsChange([])}
                    className="text-[10px] font-bold text-red-600 hover:underline uppercase"
                >
                    Borrar Todo
                </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {points.map((p, i) => (
                    <div key={p.id} className="bg-white border border-slate-100 rounded-xl p-2.5 flex items-center gap-3 shadow-sm group">
                        <div className="w-6 h-6 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center text-[10px] font-black shrink-0">
                            {i}
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-xs font-semibold text-slate-800 truncate">{p.label}</p>
                        </div>
                        <button 
                            onClick={() => handleRemovePoint(p.id)} 
                            className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                        >
                            <Trash2 size={14} />
                        </button>
                    </div>
                ))}
            </div>
        </div>
      )}
    </div>
  );
};

