    html: `
      <div class="relative flex items-center justify-center">
        <div class="absolute w-8 h-8 ${isStart ? 'bg-emerald-500' : 'bg-brand-600'} rounded-full border-2 border-white shadow-lg animate-in zoom-in duration-300"></div>
        <span class="relative text-white font-black text-[11px]">${number}</span>
        ${isStart ? '<div class="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full flex items-center justify-center"><div class="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div></div>' : ''}
      </div>
    `,
    className: 'custom-div-icon',
    iconSize: [32, 32],
    iconAnchor: [16, 16],
  });
};

// Component to handle map clicks, centering, and bounds
const MapController = ({ 
  onAdd, 
  centerOn, 
  routePath 
}: { 
  onAdd: (lat: number, lng: number, label?: string) => void, 
  centerOn?: [number, number],
  routePath?: [number, number][]
}) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 15, { animate: true });
    }
  }, [centerOn, map]);

  useEffect(() => {
    if (routePath && routePath.length > 1) {
      const bounds = L.latLngBounds(routePath);
      map.fitBounds(bounds, { padding: [50, 50], maxZoom: 16, animate: true });
    }
  }, [routePath, map]);

  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  useEffect(() => {
    if (externalCenter) {
      setCenterOn(externalCenter);
    }
  }, [externalCenter]);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Entrega ${points.length + 1}`;
    } catch {
      return `Entrega ${points.length + 1}`;
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: finalLabel
    };
    onPointsChange([...points, newPoint]);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const latitude = parseFloat(lat);
        const longitude = parseFloat(lon);
        setCenterOn([latitude, longitude]);
        handleAddPoint(latitude, longitude, display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Search error", err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setCenterOn([pos.coords.latitude, pos.coords.longitude]);
      });
    }
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
  };

  const routePath = useMemo(() => {
    if (routeSequence && routeSequence.length > 0) {
      return routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number]);
    }
    return [];
  }, [routeSequence, points]);

  // Map each point ID to its position in the optimized route
  const getRouteIndex = (pointIndex: number) => {
    if (!routeSequence) return null;
    const pos = routeSequence.indexOf(pointIndex);
    return pos !== -1 ? pos : null;
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Search Bar */}
      <form onSubmit={handleSearch} className="relative flex gap-2">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar dirección para entrega..."
                className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
            />
        </div>
        <button 
            type="submit"
            disabled={isSearching}
            className="bg-brand-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-brand-700 transition flex items-center gap-2"
        >
            {isSearching ? <Loader2 size={16} className="animate-spin" /> : 'Añadir'}
        </button>
        <button 
            type="button"
            onClick={handleCurrentLocation}
            className="p-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition shadow-sm"
            title="Mi ubicación"
        >
            <Navigation size={20} />
        </button>
      </form>

      {/* Map Container */}
      <div className="h-[400px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative z-0 group">
        <MapContainer center={[40.4168, -3.7038]} zoom={13} scrollWheelZoom={true}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapController onAdd={handleAddPoint} centerOn={centerOn} routePath={routePath} />

          {/* Main Points Markers */}
          {points.map((point, index) => {
            const routePos = getRouteIndex(index);
            const isRouteActive = routePos !== null;

            return (
              <Marker 
                key={point.id} 
                position={[point.lat, point.lng]}
                icon={isRouteActive ? createNumberedIcon(routePos, routePos === 0) : undefined}
              >
                <Popup className="custom-popup">
                  <div className="p-2 min-w-[150px]">
                    <p className="font-black text-slate-900 text-sm mb-1 leading-tight">{point.label}</p>
                    <div className="flex items-center justify-between mt-2 mb-3">
                      <span className="text-[10px] font-bold text-slate-400 uppercase">Ref: ID ${index}</span>
                      {isRouteActive && (
                        <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full text-[10px] font-bold">
                          Parada #${routePos}
                        </span>
                      )}
                    </div>
                    <button 
                      onClick={() => handleRemovePoint(point.id)}
                      className="w-full text-[10px] font-bold uppercase tracking-wider text-red-500 bg-red-50 py-2 rounded-lg flex items-center justify-center gap-1.5 hover:bg-red-100 transition-colors"
                    >
                      <Trash2 size={12} /> Eliminar Punto
                    </button>
                  </div>
                </Popup>
              </Marker>
            );
          })}

          {/* Optimized Route Line */}
          {routePath.length > 1 && (
            <>
              {/* Shadow/Glow Line */}
              <Polyline 
                  positions={routePath} 
                  color="#2563eb" 
                  weight={10} 
                  opacity={0.2} 
                  lineCap="round"
              />
              {/* Main Technical Line */}
              <Polyline 
                  positions={routePath} 
                  color="#3b82f6" 
                  weight={4} 
                  opacity={1} 
                  lineCap="round"
                  dashArray={routeSequence ? "none" : "5, 10"}
              />
            </>
          )}
        </MapContainer>

        {/* Map Overlays */}
        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2 pointer-events-none">
            <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 shadow-md text-[10px] text-slate-600 font-bold uppercase tracking-wider flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${routeSequence ? 'bg-emerald-500' : 'bg-amber-500'} animate-pulse`}></div>
                {routeSequence ? 'Ruta Optimizada' : 'Modo Edición'}
            </div>
        </div>
      </div>

      {/* Points Summary Grid */}
      {points.length > 0 && (
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 transition-all">
            <div className="flex justify-between items-center mb-4">
                <div className="flex items-center gap-2">
                  <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Plan de Ruta</h4>
                  <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded text-[10px] font-bold">{points.length} puntos</span>
                </div>
                <button 
                    onClick={() => onPointsChange([])}
                    className="text-[10px] font-bold text-red-500 hover:text-red-700 uppercase tracking-tight"
                >
                    Reiniciar Mapa
                </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                {points.map((p, i) => {
                    const routePos = getRouteIndex(i);
                    return (
                      <div key={p.id} className={`bg-white border ${routePos !== null ? 'border-brand-200 ring-1 ring-brand-50' : 'border-slate-100'} rounded-xl p-3 flex items-center gap-3 shadow-sm group hover:border-brand-300 transition-all`}>
                          <div className={`w-7 h-7 rounded-lg ${routePos !== null ? 'bg-brand-600 text-white' : 'bg-slate-100 text-slate-400'} flex items-center justify-center text-[11px] font-black shrink-0 shadow-sm`}>
                              {routePos !== null ? routePos : i}
                          </div>
                          <div className="flex-1 min-w-0">
                              <p className="text-[11px] font-bold text-slate-800 truncate leading-none mb-1">{p.label}</p>
                              <p className="text-[9px] text-slate-400 font-medium">ID: ${i}</p>
                          </div>
                          <button 
                              onClick={() => handleRemovePoint(p.id)} 
                              className="text-slate-300 hover:text-red-500 transition-colors p-1"
                              title="Eliminar"
                          >
                              <Trash2 size={14} />
                          </button>
                      </div>
                    );
                })}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [isLocating, setIsLocating] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  // Validación de requisitos
  const hasMinPoints = points.length >= 2;
  const hasDescription = input.trim().length >= 5;
  const canGenerate = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;

        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          console.error("Error geocoding current location", err);
        } finally {
          setIsLocating(false);
        }
      },
      (err) => {
        console.error("Geolocation error", err);
        setIsLocating(false);
        alert("No se pudo obtener tu ubicación.");
      },
      { enableHighAccuracy: true }
    );
  };

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'O describe tu ruta aquí: "Reparto en zona norte, 5 paradas urgentes..."' 
      : 'Ej: Contrato de transporte fraccionado, responsabilidad por daños...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo a las 9:00 AM."
      : "Redacta una cláusula para un contrato donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleGenerate = async () => {
    if (!canGenerate || state.isLoading) return;

    setState({ isLoading: true, content: '', error: null, routeData: undefined });

    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        fullJsonString += chunk;

        try {
            const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
            if (match && match[1]) {
                const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
                setState(prev => ({ ...prev, content: partialText }));
            }
        } catch (e) {}
      }

      if (isMounted.current) {
        try {
            const finalData = JSON.parse(fullJsonString) as RouteResponse;
            setState({ 
                isLoading: false, 
                content: finalData.explanation, 
                error: null,
                routeData: finalData.optimizedSequence
            });
        } catch (e) {
            setState(prev => ({ ...prev, isLoading: false }));
        }
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
      }
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                  <Sparkles size={12} className="text-amber-500" />
                  <span>AI Professional Tool</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={handleAddCurrentLocation}
              disabled={isLocating}
              className="hidden sm:flex items-center gap-2 px-4 py-2 bg-brand-50 text-brand-700 text-xs font-bold rounded-xl border border-brand-200 hover:bg-brand-100 transition-all shadow-sm group"
            >
              {isLocating ? <Loader2 size={16} className="animate-spin" /> : <Navigation2 size={16} className="group-hover:translate-y-[-2px] transition-transform" />}
              {isLocating ? "Localizando..." : "GPS Origen"}
            </button>
          )}
        </div>

        <p className="text-slate-500 mb-6 text-sm leading-relaxed">
            {config.description}
        </p>

        {isRoute && (
            <div className="mb-6">
                <LogisticsMap 
                    points={points} 
                    onPointsChange={setPoints} 
                    routeSequence={state.routeData}
                    externalCenter={externalCenter}
                />
            </div>
        )}

        <div className="flex justify-end mb-2">
            <button
                type="button"
                onClick={handleExampleClick}
                disabled={state.isLoading}
                className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100' : 'text-purple-700 bg-purple-50 hover:bg-purple-100'} px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 disabled:opacity-50`}
            >
                <Sparkles size={14} /> Ver Ejemplo
            </button>
        </div>

        <div className="relative mb-6">
            <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={state.isLoading}
            rows={isRoute ? 3 : 5}
            className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400"
            style={{ 
                //@ts-ignore
                '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
            }}
            placeholder={config.placeholder}
            />
        </div>

        <div className="mt-auto">
          <button
            onClick={handleGenerate}
            disabled={state.isLoading || !canGenerate}
            className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-40 disabled:grayscale disabled:cursor-not-allowed`}
          >
            {state.isLoading ? (
              <>
                <Loader2 className="animate-spin" size={20} />
                <span>Procesando...</span>
              </>
            ) : (
              <>
                <Sparkles size={20} />
                <span>Optimizar con IA</span>
              </>
            )}
          </button>

          {/* Mensaje de validación dinámico */}
          {!canGenerate && !state.isLoading && (
            <div className="mt-3 flex items-center justify-center gap-2 text-[11px] font-semibold text-slate-400 animate-in fade-in duration-500">
              <Info size={12} className="shrink-0" />
              <span>
                {isRoute 
                  ? "Añade al menos 2 puntos en el mapa o escribe una descripción." 
                  : "Por favor, escribe una descripción detallada del supuesto."}
              </span>
            </div>
          )}
        </div>

        <div ref={resultRef} className="scroll-mt-24">
          {state.error && (
            <div className="mt-4 p-4 bg-red-50 text-red-800 text-sm rounded-xl border border-red-200 flex flex-col gap-2">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="shrink-0 mt-0.5 text-red-600" size={18} />
                   <p className="text-red-700 leading-relaxed">{state.error}</p>
               </div>
               <button onClick={handleGenerate} className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-red-200 text-red-700 text-xs font-semibold rounded-lg hover:bg-red-50 transition-all shadow-sm">
                  <RefreshCw size={12} /> Reintentar
               </button>
            </div>
          )}

          {state.content !== null && (
            <div className={`mt-6 p-5 ${config.lightBg} rounded-xl border ${config.borderColor} relative group animate-in fade-in slide-in-from-bottom-4 duration-500`}>
               <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                      onClick={() => {
                        navigator.clipboard.writeText(state.content || '');
                        setCopied(true);
                        setTimeout(() => setCopied(false), 2000);
                      }}
                      className="p-2 bg-white rounded-lg shadow-sm hover:bg-slate-50 text-slate-600 transition"
                  >
                      {copied ? <Check size={16} className="text-green-500" /> : <Copy size={16} />}
                  </button>
               </div>
               <div className="prose prose-sm prose-slate max-w-none">
                   <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                       {state.content}
                   </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, Search, Navigation, Loader2, Edit3, Check, X } from 'lucide-react';

// Fix for default marker icons
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
  externalCenter?: [number, number];
}

// Create a custom numbered icon
const createNumberedIcon = (number: number, isStart: boolean) => {
  return L.divIcon({
    html: `
      <div class="relative flex items-center justify-center">
        <div class="absolute w-8 h-8 ${isStart ? 'bg-emerald-500' : 'bg-brand-600'} rounded-full border-2 border-white shadow-lg animate-in zoom-in duration-300"></div>
        <span class="relative text-white font-black text-[11px]">${number}</span>
        ${isStart ? '<div class="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full flex items-center justify-center"><div class="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div></div>' : ''}
      </div>
    `,
    className: 'custom-div-icon',
    iconSize: [32, 32],
    iconAnchor: [16, 16],
  });
};

// Component to handle map clicks, centering, and bounds
const MapController = ({ 
  onAdd, 
  centerOn, 
  routePath 
}: { 
  onAdd: (lat: number, lng: number, label?: string) => void, 
  centerOn?: [number, number],
  routePath?: [number, number][]
}) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 15, { animate: true });
    }
  }, [centerOn, map]);

  useEffect(() => {
    if (routePath && routePath.length > 1) {
      const bounds = L.latLngBounds(routePath);
      map.fitBounds(bounds, { padding: [50, 50], maxZoom: 16, animate: true });
    }
  }, [routePath, map]);

  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  // State for editing labels
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  useEffect(() => {
    if (externalCenter) {
      setCenterOn(externalCenter);
    }
  }, [externalCenter]);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Entrega ${points.length + 1}`;
    } catch {
      return `Entrega ${points.length + 1}`;
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: finalLabel
    };
    onPointsChange([...points, newPoint]);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const latitude = parseFloat(lat);
        const longitude = parseFloat(lon);
        setCenterOn([latitude, longitude]);
        handleAddPoint(latitude, longitude, display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Search error", err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setCenterOn([pos.coords.latitude, pos.coords.longitude]);
      });
    }
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
  };

  const handleUpdateLabel = (id: string) => {
    if (!editValue.trim()) return;
    onPointsChange(points.map(p => p.id === id ? { ...p, label: editValue } : p));
    setEditingId(null);
  };

  const startEditing = (point: MapPoint) => {
    setEditingId(point.id);
    setEditValue(point.label || '');
  };

  const routePath = useMemo(() => {
    if (routeSequence && routeSequence.length > 0) {
      return routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number]);
    }
    return [];
  }, [routeSequence, points]);

  // Map each point ID to its position in the optimized route
  const getRouteIndex = (pointIndex: number) => {
    if (!routeSequence) return null;
    const pos = routeSequence.indexOf(pointIndex);
    return pos !== -1 ? pos : null;
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Search Bar */}
      <form onSubmit={handleSearch} className="relative flex gap-2">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar dirección para entrega..."
                className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
            />
        </div>
        <button 
            type="submit"
            disabled={isSearching}
            className="bg-brand-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-brand-700 transition flex items-center gap-2"
        >
            {isSearching ? <Loader2 size={16} className="animate-spin" /> : 'Añadir'}
        </button>
        <button 
            type="button"
            onClick={handleCurrentLocation}
            className="p-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition shadow-sm"
            title="Mi ubicación"
        >
            <Navigation size={20} />
        </button>
      </form>

      {/* Map Container */}
      <div className="h-[400px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative z-0 group">
        <MapContainer center={[40.4168, -3.7038]} zoom={13} scrollWheelZoom={true}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapController onAdd={handleAddPoint} centerOn={centerOn} routePath={routePath} />

          {/* Main Points Markers */}
          {points.map((point, index) => {
            const routePos = getRouteIndex(index);
            const isRouteActive = routePos !== null;
            const isEditing = editingId === point.id;

            return (
              <Marker 
                key={point.id} 
                position={[point.lat, point.lng]}
                icon={isRouteActive ? createNumberedIcon(routePos, routePos === 0) : undefined}
                eventHandlers={{
                  popupclose: () => setEditingId(null)
                }}
              >
                <Popup className="custom-popup">
                  <div className="p-2 min-w-[180px]">
                    {isEditing ? (
                      <div className="space-y-2 mb-3">
                        <label className="text-[10px] font-bold text-slate-400 uppercase">Renombrar entrega</label>
                        <div className="flex gap-1">
                          <input 
                            autoFocus
                            type="text"
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleUpdateLabel(point.id)}
                            className="flex-1 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500"
                          />
                          <button 
                            onClick={() => handleUpdateLabel(point.id)}
                            className="p-1 bg-brand-600 text-white rounded hover:bg-brand-700 transition"
                          >
                            <Check size={14} />
                          </button>
                          <button 
                            onClick={() => setEditingId(null)}
                            className="p-1 bg-slate-100 text-slate-400 rounded hover:bg-slate-200 transition"
                          >
                            <X size={14} />
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="group/label relative mb-1">
                        <p className="font-black text-slate-900 text-sm leading-tight pr-6">{point.label}</p>
                        <button 
                          onClick={() => startEditing(point)}
                          className="absolute top-0 right-0 p-1 text-slate-300 hover:text-brand-600 transition-colors"
                          title="Editar nombre"
                        >
                          <Edit3 size={14} />
                        </button>
                      </div>
                    )}

                    <div className="flex items-center justify-between mt-2 mb-3">
                      <span className="text-[10px] font-bold text-slate-400 uppercase">Ref: ID ${index}</span>
                      {isRouteActive && (
                        <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full text-[10px] font-bold">
                          Parada #${routePos}
                        </span>
                      )}
                    </div>

                    <button 
                      onClick={() => handleRemovePoint(point.id)}
                      className="w-full text-[10px] font-bold uppercase tracking-wider text-red-500 bg-red-50 py-2 rounded-lg flex items-center justify-center gap-1.5 hover:bg-red-100 transition-colors"
                    >
                      <Trash2 size={12} /> Eliminar Punto
                    </button>
                  </div>
                </Popup>
              </Marker>
            );
          })}

          {/* Optimized Route Line */}
          {routePath.length > 1 && (
            <>
              {/* Shadow/Glow Line */}
              <Polyline 
                  positions={routePath} 
                  color="#2563eb" 
                  weight={10} 
                  opacity={0.2} 
                  lineCap="round"
              />
              {/* Main Technical Line */}
              <Polyline 
                  positions={routePath} 
                  color="#3b82f6" 
                  weight={4} 
                  opacity={1} 
                  lineCap="round"
                  dashArray={routeSequence ? "none" : "5, 10"}
              />
            </>
          )}
        </MapContainer>

        {/* Map Overlays */}
        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2 pointer-events-none">
            <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 shadow-md text-[10px] text-slate-600 font-bold uppercase tracking-wider flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${routeSequence ? 'bg-emerald-500' : 'bg-amber-500'} animate-pulse`}></div>
                {routeSequence ? 'Ruta Optimizada' : 'Modo Edición'}
            </div>
        </div>
      </div>

      {/* Points Summary Grid */}
      {points.length > 0 && (
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 transition-all">
            <div className="flex justify-between items-center mb-4">
                <div className="flex items-center gap-2">
                  <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Plan de Ruta</h4>
                  <span className="bg-slate-200 text-slate-600 px-2 py-0.5 rounded text-[10px] font-bold">{points.length} puntos</span>
                </div>
                <button 
                    onClick={() => onPointsChange([])}
                    className="text-[10px] font-bold text-red-500 hover:text-red-700 uppercase tracking-tight"
                >
                    Reiniciar Mapa
                </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                {points.map((p, i) => {
                    const routePos = getRouteIndex(i);
                    return (
                      <div key={p.id} className={`bg-white border ${routePos !== null ? 'border-brand-200 ring-1 ring-brand-50' : 'border-slate-100'} rounded-xl p-3 flex items-center gap-3 shadow-sm group hover:border-brand-300 transition-all`}>
                          <div className={`w-7 h-7 rounded-lg ${routePos !== null ? 'bg-brand-600 text-white' : 'bg-slate-100 text-slate-400'} flex items-center justify-center text-[11px] font-black shrink-0 shadow-sm`}>
                              {routePos !== null ? routePos : i}
                          </div>
                          <div className="flex-1 min-w-0">
                              <p className="text-[11px] font-bold text-slate-800 truncate leading-none mb-1">{p.label}</p>
                              <p className="text-[9px] text-slate-400 font-medium">ID: ${i}</p>
                          </div>
                          <button 
                              onClick={() => handleRemovePoint(p.id)} 
                              className="text-slate-300 hover:text-red-500 transition-colors p-1"
                              title="Eliminar"
                          >
                              <Trash2 size={14} />
                          </button>
                      </div>
                    );
                })}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [isLocating, setIsLocating] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  // Validación de requisitos
  const hasMinPoints = points.length >= 2;
  const hasDescription = input.trim().length >= 5;
  const canGenerate = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;

        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          console.error("Error geocoding current location", err);
        } finally {
          setIsLocating(false);
        }
      },
      (err) => {
        console.error("Geolocation error", err);
        setIsLocating(false);
        alert("No se pudo obtener tu ubicación.");
      },
      { enableHighAccuracy: true }
    );
  };

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-brand-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'O describe tu ruta aquí: "Reparto en zona norte, 5 paradas urgentes..."' 
      : 'Ej: Contrato de transporte fraccionado, responsabilidad por daños...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo a las 9:00 AM."
      : "Redacta una cláusula para un contrato donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleGenerate = async () => {
    if (!canGenerate || state.isLoading) return;

    setState({ isLoading: true, content: '', error: null, routeData: undefined });

    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        fullJsonString += chunk;

        try {
            const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
            if (match && match[1]) {
                const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
                setState(prev => ({ ...prev, content: partialText }));
            }
        } catch (e) {}
      }

      if (isMounted.current) {
        try {
            const finalData = JSON.parse(fullJsonString) as RouteResponse;
            setState({ 
                isLoading: false, 
                content: finalData.explanation, 
                error: null,
                routeData: finalData.optimizedSequence
            });
        } catch (e) {
            setState(prev => ({ ...prev, isLoading: false }));
        }
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
      }
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                  <Sparkles size={12} className="text-amber-500" />
                  <span>AI Professional Tool</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={handleAddCurrentLocation}
              disabled={isLocating}
              className="hidden sm:flex items-center gap-2 px-4 py-2 bg-brand-50 text-brand-700 text-xs font-bold rounded-xl border border-brand-200 hover:bg-brand-100 transition-all shadow-sm group"
            >
              {isLocating ? <Loader2 size={16} className="animate-spin" /> : <Navigation2 size={16} className="group-hover:translate-y-[-2px] transition-transform" />}
              {isLocating ? "Localizando..." : "GPS Origen"}
            </button>
          )}
        </div>

        <p className="text-slate-500 mb-6 text-sm leading-relaxed">
            {config.description}
        </p>

        {isRoute && (
            <div className="mb-6">
                <LogisticsMap 
                    points={points} 
                    onPointsChange={setPoints} 
                    routeSequence={state.routeData}
                    externalCenter={externalCenter}
                />
            </div>
        )}

        <div className="flex justify-end mb-2">
            <button
                type="button"
                onClick={handleExampleClick}
                disabled={state.isLoading}
                className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100' : 'text-purple-700 bg-purple-50 hover:bg-purple-100'} px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 disabled:opacity-50`}
            >
                <Sparkles size={14} /> Ver Ejemplo
            </button>
        </div>

        <div className="relative mb-6">
            <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={state.isLoading}
            rows={isRoute ? 3 : 5}
            className="w-full p-4 border border-slate-200 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400"
            style={{ 
                //@ts-ignore
                '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
            }}
            placeholder={config.placeholder}
            />
        </div>

        <div className="mt-auto">
          <button
            onClick={handleGenerate}
            disabled={state.isLoading || !canGenerate}
            className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-40 disabled:grayscale disabled:cursor-not-allowed`}
          >
            {state.isLoading ? (
              <>
                <Loader2 className="animate-spin" size={20} />
                <span>Procesando...</span>
              </>
            ) : (
              <>
                <Sparkles size={20} />
                <span>Optimizar con IA</span>
              </>
            )}
          </button>

          {!canGenerate && !state.isLoading && (
            <div className="mt-3 flex items-center justify-center gap-2 text-[11px] font-semibold text-slate-400 animate-in fade-in duration-500">
              <Info size={12} className="shrink-0" />
              <span>
                {isRoute 
                  ? "Añade al menos 2 puntos en el mapa o escribe una descripción." 
                  : "Por favor, escribe una descripción detallada del supuesto."}
              </span>
            </div>
          )}
        </div>

        <div ref={resultRef} className="scroll-mt-24">
          {state.error && (
            <div className="mt-4 p-4 bg-red-50 text-red-800 text-sm rounded-xl border border-red-200 flex flex-col gap-2">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="shrink-0 mt-0.5 text-red-600" size={18} />
                   <p className="text-red-700 leading-relaxed">{state.error}</p>
               </div>
               <button onClick={handleGenerate} className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-red-200 text-red-700 text-xs font-semibold rounded-lg hover:bg-red-50 transition-all shadow-sm">
                  <RefreshCw size={12} /> Reintentar
               </button>
            </div>
          )}

          {state.content !== null && (
            <div className={`mt-6 rounded-2xl border ${config.borderColor} overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500`}>
               <div className={`p-5 ${config.lightBg}`}>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                          {state.content}
                          {state.isLoading && <span className={`inline-block w-1.5 h-4 ml-1 ${config.bgColor} animate-pulse align-middle`}></span>}
                      </div>
                  </div>
               </div>

               {/* Botón de copiar prominente debajo del resultado */}
               <div className="bg-white border-t border-slate-100 p-3 flex justify-between items-center">
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-2">
                    {state.isLoading ? 'Generando respuesta...' : 'Resultado finalizado'}
                  </span>
                  <button 
                      onClick={handleCopy}
                      disabled={!state.content}
                      className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all duration-200 ${copied ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-slate-50 text-slate-700 border border-slate-200 hover:bg-slate-100'}`}
                  >
                      {copied ? (
                        <>
                          <Check size={14} className="text-emerald-500" />
                          <span>¡Copiado!</span>
                        </>
                      ) : (
                        <>
                          <Copy size={14} />
                          <span>Copiar resultado</span>
                        </>
                      )}
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'preparing' | 'connecting' | 'streaming' | 'finalizing' | 'locating';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

