  lat: number;
  lng: number;
  id: string;
  label?: string;
}

export interface GeneratedContentState {
  isLoading: boolean;
  content: string | null;
  error: string | null;
  routeData?: number[]; // Order of point indices
}

export interface RouteResponse {
  explanation: string;
  optimizedSequence: number[]; // Indices of input points
}

