export const GeneralConsultant: React.FC = () => {
  const [input, setInput] = useState('');
  const [showError, setShowError] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
  });

  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isValid = input.trim().length >= 10;

  const handleConsult = async () => {
    if (!isValid) {
      setShowError(true);
      return;
    }

    setState({ isLoading: true, content: '', error: null });
    setShowError(false);

    try {
      const stream = generateLogisticsResponse(ToolType.CONSULTANT, input);
      let fullContent = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;

        try {
          const match = chunk.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/) || chunk.match(/"explanation":\s*"(.*)"/);
          if (match && match[1]) {
             fullContent += match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
          } else if (!chunk.includes('{')) {
             fullContent += chunk;
          }
        } catch (e) {
          fullContent += chunk;
        }

        setState(prev => ({
          ...prev,
          content: fullContent
        }));
      }

      if (isMounted.current) {
        setState(prev => ({ ...prev, isLoading: false }));
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message });
      }
    }
  };

  return (
    <section className="py-12 bg-slate-50 border-y border-slate-200" id="consultor">
