import React, { useEffect, useState, useMemo } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, Search, Navigation, Loader2, Edit3, Check, X, Tag } from 'lucide-react';

// Fix for default marker icons
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
  externalCenter?: [number, number];
}

// Create a custom numbered icon
const createNumberedIcon = (number: number, isStart: boolean) => {
  return L.divIcon({
    html: `
      <div class="relative flex items-center justify-center">
        <div class="absolute w-8 h-8 ${isStart ? 'bg-emerald-500' : 'bg-brand-600'} rounded-full border-2 border-white shadow-lg animate-in zoom-in duration-300"></div>
        <span class="relative text-white font-black text-[11px]">${number}</span>
        ${isStart ? '<div class="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full flex items-center justify-center"><div class="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div></div>' : ''}
      </div>
    `,
    className: 'custom-div-icon',
    iconSize: [32, 32],
    iconAnchor: [16, 16],
  });
};

const MapController = ({ 
  onAdd, 
  centerOn, 
  routePath 
}: { 
  onAdd: (lat: number, lng: number, label?: string) => void, 
  centerOn?: [number, number],
  routePath?: [number, number][]
}) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 15, { animate: true });
    }
  }, [centerOn, map]);

  useEffect(() => {
    if (routePath && routePath.length > 1) {
      const bounds = L.latLngBounds(routePath);
      map.fitBounds(bounds, { padding: [50, 50], maxZoom: 16, animate: true });
    }
  }, [routePath, map]);

  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  // State for editing labels (Shared between Map and List)
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  useEffect(() => {
    if (externalCenter) {
      setCenterOn(externalCenter);
    }
  }, [externalCenter]);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Entrega ${points.length + 1}`;
    } catch {
      return `Entrega ${points.length + 1}`;
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: finalLabel
    };
    onPointsChange([...points, newPoint]);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const latitude = parseFloat(lat);
        const longitude = parseFloat(lon);
        setCenterOn([latitude, longitude]);
        handleAddPoint(latitude, longitude, display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Search error", err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleCurrentLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setCenterOn([pos.coords.latitude, pos.coords.longitude]);
      });
    }
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
    if (editingId === id) setEditingId(null);
  };

  const handleUpdateLabel = (id: string) => {
    if (!editValue.trim()) {
      setEditingId(null);
      return;
    }
    onPointsChange(points.map(p => p.id === id ? { ...p, label: editValue } : p));
    setEditingId(null);
  };

  const startEditing = (point: MapPoint) => {
    setEditingId(point.id);
    setEditValue(point.label || '');
  };

  const routePath = useMemo(() => {
    if (routeSequence && routeSequence.length > 0) {
      return routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number]);
    }
    return [];
  }, [routeSequence, points]);

  const getRouteIndex = (pointIndex: number) => {
    if (!routeSequence) return null;
    const pos = routeSequence.indexOf(pointIndex);
    return pos !== -1 ? pos : null;
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Search Bar */}
      <form onSubmit={handleSearch} className="relative flex gap-2">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar dirección para entrega..."
                className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
            />
        </div>
        <button 
            type="submit"
            disabled={isSearching}
            className="bg-brand-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-brand-700 transition flex items-center gap-2"
        >
            {isSearching ? <Loader2 size={16} className="animate-spin" /> : 'Añadir'}
        </button>
        <button 
            type="button"
            onClick={handleCurrentLocation}
            className="p-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition shadow-sm"
            title="Mi ubicación"
        >
            <Navigation size={20} />
        </button>
      </form>

      {/* Map Container */}
      <div className="h-[400px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative z-0 group">
        <MapContainer center={[40.4168, -3.7038]} zoom={13} scrollWheelZoom={true}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapController onAdd={handleAddPoint} centerOn={centerOn} routePath={routePath} />

          {points.map((point, index) => {
            const routePos = getRouteIndex(index);
            const isRouteActive = routePos !== null;
            const isEditing = editingId === point.id;

            return (
              <Marker 
                key={point.id} 
                position={[point.lat, point.lng]}
                icon={isRouteActive ? createNumberedIcon(routePos, routePos === 0) : undefined}
                eventHandlers={{
                  popupclose: () => setEditingId(null),
                  click: () => setCenterOn([point.lat, point.lng])
                }}
              >
                <Popup className="custom-popup">
                  <div className="p-2 min-w-[180px]">
                    {isEditing ? (
                      <div className="space-y-2 mb-3">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Renombrar parada</label>
                        <div className="flex gap-1">
                          <input 
                            autoFocus
                            type="text"
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') handleUpdateLabel(point.id);
                              if (e.key === 'Escape') setEditingId(null);
                            }}
                            className="flex-1 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500"
                          />
                          <button 
                            onClick={() => handleUpdateLabel(point.id)}
                            className="p-1 bg-brand-600 text-white rounded hover:bg-brand-700 transition"
                          >
                            <Check size={14} />
                          </button>
                          <button 
                            onClick={() => setEditingId(null)}
                            className="p-1 bg-slate-100 text-slate-400 rounded hover:bg-slate-200 transition"
                          >
                            <X size={14} />
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="group/label relative mb-1">
                        <p className="font-black text-slate-900 text-sm leading-tight pr-6">{point.label}</p>
                        <button 
                          onClick={() => startEditing(point)}
                          className="absolute top-0 right-0 p-1 text-slate-300 hover:text-brand-600 transition-colors"
                          title="Editar nombre"
                        >
                          <Edit3 size={14} />
                        </button>
                      </div>
                    )}

                    <div className="flex items-center justify-between mt-2 mb-3">
                      <span className="text-[10px] font-bold text-slate-400 uppercase">Referencia: #${index}</span>
                      {isRouteActive && (
                        <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full text-[10px] font-bold">
                          Parada n.º {routePos}
                        </span>
                      )}
                    </div>

                    <button 
                      onClick={() => handleRemovePoint(point.id)}
                      className="w-full text-[10px] font-bold uppercase tracking-wider text-red-500 bg-red-50 py-2 rounded-lg flex items-center justify-center gap-1.5 hover:bg-red-100 transition-colors"
                    >
                      <Trash2 size={12} /> Eliminar Punto
                    </button>
                  </div>
                </Popup>
              </Marker>
            );
          })}

          {routePath.length > 1 && (
            <>
              <Polyline 
                  positions={routePath} 
                  color="#2563eb" 
                  weight={10} 
                  opacity={0.2} 
                  lineCap="round"
              />
              <Polyline 
                  positions={routePath} 
                  color="#3b82f6" 
                  weight={4} 
                  opacity={1} 
                  lineCap="round"
              />
            </>
          )}
        </MapContainer>

        {/* Map Overlays */}
        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2 pointer-events-none">
            <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 shadow-md text-[10px] text-slate-600 font-bold uppercase tracking-wider flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${routeSequence ? 'bg-emerald-500' : 'bg-amber-500'} animate-pulse`}></div>
                {routeSequence ? 'Ruta Optimizada' : 'Planificador Manual'}
            </div>
        </div>
      </div>

      {/* Points Summary Grid - UPGRADED WITH INLINE EDITING */}
      {points.length > 0 && (
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-5 transition-all animate-in slide-in-from-bottom-4">
            <div className="flex justify-between items-center mb-5">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-slate-200 rounded-lg text-slate-600">
                    <Tag size={16} />
                  </div>
                  <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Gestión de Entregas</h4>
                  <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded text-[10px] font-bold shadow-sm">{points.length} puntos registrados</span>
                </div>
                <button 
                    onClick={() => onPointsChange([])}
                    className="text-[10px] font-bold text-red-500 hover:text-red-700 uppercase tracking-widest bg-red-50 px-3 py-1 rounded-lg transition-colors border border-red-100"
                >
                    Limpiar Mapa
                </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {points.map((p, i) => {
                    const routePos = getRouteIndex(i);
                    const isEditing = editingId === p.id;

                    return (
                      <div 
                        key={p.id} 
                        className={`bg-white border-2 rounded-xl p-3 flex items-center gap-3 shadow-sm transition-all duration-300 ${isEditing ? 'border-brand-500 ring-4 ring-brand-50 shadow-md scale-[1.02]' : 'border-slate-100 hover:border-brand-200'}`}
                      >
                          <div className={`w-8 h-8 rounded-lg ${routePos !== null ? 'bg-brand-600 text-white' : 'bg-slate-100 text-slate-400'} flex items-center justify-center text-[11px] font-black shrink-0 shadow-sm`}>
                              {routePos !== null ? routePos : i}
                          </div>

                          <div className="flex-1 min-w-0">
                              {isEditing ? (
                                <div className="flex flex-col gap-1">
                                  <input 
                                    autoFocus
                                    type="text"
                                    value={editValue}
                                    onChange={(e) => setEditValue(e.target.value)}
                                    onKeyDown={(e) => {
                                      if (e.key === 'Enter') handleUpdateLabel(p.id);
                                      if (e.key === 'Escape') setEditingId(null);
                                    }}
                                    className="w-full px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500 font-bold"
                                  />
                                  <div className="flex gap-2">
                                    <button onClick={() => handleUpdateLabel(p.id)} className="text-[9px] font-black text-emerald-600 uppercase">Guardar</button>
                                    <button onClick={() => setEditingId(null)} className="text-[9px] font-black text-slate-400 uppercase">Cancelar</button>
                                  </div>
                                </div>
                              ) : (
                                <div className="group/text flex flex-col cursor-pointer" onClick={() => startEditing(p)}>
                                  <div className="flex items-center gap-1">
                                    <p className="text-[11px] font-black text-slate-800 truncate leading-none mb-1">{p.label}</p>
                                    <Edit3 size={10} className="text-slate-300 opacity-0 group-hover/text:opacity-100 transition-opacity" />
                                  </div>
                                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">Referencia: #${i}</p>
                                </div>
                              )}
                          </div>

                          <div className="flex items-center gap-1">
                            {!isEditing && (
                              <button 
                                onClick={() => startEditing(p)} 
                                className="text-slate-300 hover:text-brand-600 transition-colors p-1.5 rounded-lg hover:bg-brand-50"
                                title="Editar nombre"
                              >
                                <Edit3 size={14} />
                              </button>
                            )}
                            <button 
                                onClick={() => handleRemovePoint(p.id)} 
                                className="text-slate-300 hover:text-red-500 transition-colors p-1.5 rounded-lg hover:bg-red-50"
                                title="Eliminar"
                            >
                                <Trash2 size={14} />
                            </button>
                          </div>
                      </div>
                    );
                })}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'preparing' | 'geocoding' | 'connecting' | 'streaming' | 'finalizing' | 'locating';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  // States for Saved Routes
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showSavedList, setShowSavedList] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [editingRouteId, setEditingRouteId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try {
          setSavedRoutes(JSON.parse(stored));
        } catch (e) {
          console.error("Error loading saved routes", e);
        }
      }
    }
    return () => {
      isMounted.current = false;
    };
  }, [type]);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  const hasMinPoints = points.length >= 2;
  const hasDescription = input.trim().length >= 5;
  const isInputValid = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  // Haversine formula for distance calculation
  const calculateTotalDistance = (routePoints: MapPoint[], sequence: number[]) => {
    if (sequence.length < 2) return 0;
    let total = 0;
    const R = 6371; // Earth radius in km

    for (let i = 0; i < sequence.length - 1; i++) {
      const p1 = routePoints[sequence[i]];
      const p2 = routePoints[sequence[i + 1]];

      const dLat = (p2.lat - p1.lat) * Math.PI / 180;
      const dLon = (p2.lng - p1.lng) * Math.PI / 180;
      const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(p1.lat * Math.PI / 180) * Math.cos(p2.lat * Math.PI / 180) * 
        Math.sin(dLon/2) * Math.sin(dLon/2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
      total += R * c;
    }
    return parseFloat(total.toFixed(2));
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
          setShowValidationErrors(false);
        } catch (err) {
          console.error("Geocoding error", err);
        } finally {
          setLoadingStage('idle');
        }
      },
      (err) => {
        setLoadingStage('idle');
        alert("No se pudo obtener tu ubicación.");
      },
      { enableHighAccuracy: true }
    );
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;

    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || '',
      totalDistance: calculateTotalDistance(points, state.routeData)
    };

    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const handleRenameRoute = (id: string) => {
    if (!editingName.trim()) return;
    const updated = savedRoutes.map(r => r.id === id ? { ...r, name: editingName.trim() } : r);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setEditingRouteId(null);
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({
      isLoading: false,
      content: route.explanation,
      error: null,
      routeData: route.routeData
    });
    setShowSavedList(false);
    setShowValidationErrors(false);
    setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Estás seguro de que deseas eliminar esta ruta?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const downloadRouteJson = (route: SavedRoute, e: React.MouseEvent) => {
    e.stopPropagation();
    const blob = new Blob([JSON.stringify(route, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${route.name.replace(/\s+/g, '_')}_logistics.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const filteredRoutes = useMemo(() => {
    return savedRoutes.filter(r => 
      r.name.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [savedRoutes, searchQuery]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-brand-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'O describe tu ruta aquí: "Reparto en zona norte, 5 paradas urgentes..."' 
      : 'Ej: Contrato de transporte fraccionado, responsabilidad por daños...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo a las 9:00 AM."
      : "Redacta una cláusula para un contrato donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setShowValidationErrors(false);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleGenerate = async () => {
    if (!isInputValid) {
      setShowValidationErrors(true);
      return;
    }

    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    setShowValidationErrors(false);

    try {
      await new Promise(r => setTimeout(r, 400));
      if (!isMounted.current) return;

      setLoadingStage('preparing');
      await new Promise(r => setTimeout(r, 400));

      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (loadingStage !== 'streaming') setLoadingStage('streaming');
        fullJsonString += chunk;

        try {
            const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
            if (match && match[1]) {
                const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
                setState(prev => ({ ...prev, content: partialText }));
            }
        } catch (e) {}
      }

      if (isMounted.current) {
        setLoadingStage('finalizing');
        try {
            const finalData = JSON.parse(fullJsonString) as RouteResponse;
            setState({ 
                isLoading: false, 
                content: finalData.explanation, 
                error: null,
                routeData: finalData.optimizedSequence
            });
        } catch (e) {
            setState(prev => ({ ...prev, isLoading: false }));
        }
        setLoadingStage('idle');
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
        setLoadingStage('idle');
      }
    }
  };

  const getStageStatus = (stage: LoadingStage) => {
    const stages: LoadingStage[] = ['validating', 'preparing', 'connecting', 'streaming', 'finalizing'];
    const currentIndex = stages.indexOf(loadingStage);
    const stageIndex = stages.indexOf(stage);

    if (currentIndex > stageIndex) return 'completed';
    if (currentIndex === stageIndex) return 'active';
    return 'pending';
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'validating': return "Validando restricciones...";
      case 'preparing': return isRoute ? "Analizando coordenadas..." : "Preparando normativa...";
      case 'connecting': return "Accediendo a Gemini Pro...";
      case 'streaming': return isRoute ? "Optimizando secuencia..." : "Generando cláusulas...";
      case 'finalizing': return "Aplicando telemetría final...";
      case 'locating': return "Obteniendo coordenadas GPS...";
      default: return "Cargando...";
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
