const POI_PRESETS = [
  { id: 'wh', label: 'Almacén Central', icon: <Warehouse size={14} />, prefix: '🏭' },
  { id: 'hub', label: 'Hub Urbano', icon: <Building2 size={14} />, prefix: '📦' },
  { id: 'factory', label: 'Fábrica/Producción', icon: <Factory size={14} />, prefix: '⚙️' },
  { id: 'port', label: 'Puerto Seco', icon: <Ship size={14} />, prefix: '⚓' },
  { id: 'airport', label: 'Terminal Carga', icon: <Plane size={14} />, prefix: '✈️' },
];

// Create a custom numbered icon
const createNumberedIcon = (number: number, isStart: boolean) => {
  return L.divIcon({
    html: `
      <div class="relative flex items-center justify-center">
        <div class="absolute w-8 h-8 ${isStart ? 'bg-emerald-500' : 'bg-brand-600'} rounded-full border-2 border-white shadow-lg animate-in zoom-in duration-300"></div>
        <span class="relative text-white font-black text-[11px]">${number}</span>
        ${isStart ? '<div class="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full flex items-center justify-center"><div class="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div></div>' : ''}
      </div>
    `,
    className: 'custom-div-icon',
    iconSize: [32, 32],
    iconAnchor: [16, 16],
  });
};

const MapController = ({ 
  onAdd, 
  centerOn, 
  routePath 
}: { 
  onAdd: (lat: number, lng: number, label?: string) => void, 
  centerOn?: [number, number],
  routePath?: [number, number][]
}) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 15, { animate: true });
    }
  }, [centerOn, map]);

  useEffect(() => {
    if (routePath && routePath.length > 1) {
      const bounds = L.latLngBounds(routePath);
      map.fitBounds(bounds, { padding: [50, 50], maxZoom: 16, animate: true });
    }
  }, [routePath, map]);

  useMapEvents({
    click(e) {
      onAdd(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
};

// Component helper to handle preset addition at center
const AddPresetAtCenter = ({ onAdd }: { onAdd: (lat: number, lng: number, label: string) => void }) => {
  const map = useMap();
  window.addPoiAtCenter = (label: string) => {
    const center = map.getCenter();
    onAdd(center.lat, center.lng, label);
  };
  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [mapActivity, setMapActivity] = useState<string | null>(null);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  // State for editing labels (Shared between Map and List)
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  useEffect(() => {
    if (externalCenter) {
      setCenterOn(externalCenter);
    }
  }, [externalCenter]);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    setMapActivity("Identificando zona...");
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Entrega ${points.length + 1}`;
    } catch {
      return `Entrega ${points.length + 1}`;
    } finally {
      setMapActivity(null);
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    const newPoint: MapPoint = {
      lat,
      lng,
      id: Math.random().toString(36).substr(2, 9),
      label: finalLabel
    };
    onPointsChange([...points, newPoint]);
  };

  const handleAddPreset = (label: string, prefix: string) => {
    // This is called via window helper to access map context
    if (typeof (window as any).addPoiAtCenter === 'function') {
      (window as any).addPoiAtCenter(`${prefix} ${label}`);
    }
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    setMapActivity("Geocodificando...");
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const latitude = parseFloat(lat);
        const longitude = parseFloat(lon);
        setCenterOn([latitude, longitude]);
        handleAddPoint(latitude, longitude, display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Search error", err);
    } finally {
      setIsSearching(false);
      setMapActivity(null);
    }
  };

  const handleCurrentLocation = () => {
    if (navigator.geolocation) {
      setMapActivity("Conectando con GPS...");
      navigator.geolocation.getCurrentPosition((pos) => {
        setCenterOn([pos.coords.latitude, pos.coords.longitude]);
        setMapActivity(null);
      }, () => setMapActivity(null));
    }
  };

  const handleRemovePoint = (id: string) => {
    onPointsChange(points.filter(p => p.id !== id));
    if (editingId === id) setEditingId(null);
  };

  const handleUpdateLabel = (id: string) => {
    if (!editValue.trim()) {
      setEditingId(null);
      return;
    }
    onPointsChange(points.map(p => p.id === id ? { ...p, label: editValue } : p));
    setEditingId(null);
  };

  const startEditing = (point: MapPoint) => {
    setEditingId(point.id);
    setEditValue(point.label || '');
  };

  const routePath = useMemo(() => {
    if (routeSequence && routeSequence.length > 0) {
      return routeSequence.map(index => [points[index].lat, points[index].lng] as [number, number]);
    }
    return [];
  }, [routeSequence, points]);

  const getRouteIndex = (pointIndex: number) => {
    if (!routeSequence) return null;
    const pos = routeSequence.indexOf(pointIndex);
    return pos !== -1 ? pos : null;
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Top Toolbar: Search + Quick POIs */}
      <div className="flex flex-col md:flex-row gap-3">
          <form onSubmit={handleSearch} className="relative flex-1 flex gap-2">
            <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                    type="text" 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Buscar dirección para entrega..."
                    className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
                />
                {mapActivity && (
                  <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-2 animate-in fade-in duration-300">
                    <Loader2 size={12} className="animate-spin text-brand-500" />
                  </div>
                )}
            </div>
            <button 
                type="submit"
                disabled={isSearching}
                className="bg-brand-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-brand-700 transition flex items-center gap-2 shadow-sm shrink-0"
            >
                {isSearching ? <Loader2 size={16} className="animate-spin" /> : 'Añadir'}
            </button>
            <button 
                type="button"
                onClick={handleCurrentLocation}
                className="p-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition shadow-sm shrink-0"
                title="Mi ubicación"
            >
                <Navigation size={20} />
            </button>
          </form>

          {/* Quick POI Selection */}
          <div className="flex items-center gap-2 p-1.5 bg-slate-100 rounded-xl border border-slate-200 overflow-x-auto no-scrollbar">
            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest pl-2 pr-1 shrink-0">Nodos:</span>
            {POI_PRESETS.map((poi) => (
              <button
                key={poi.id}
                onClick={() => handleAddPreset(poi.label, poi.prefix)}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold text-slate-700 hover:border-brand-500 hover:text-brand-600 hover:shadow-sm transition-all shrink-0 active:scale-95"
                title={`Añadir ${poi.label} al centro`}
              >
                {poi.icon}
                <span className="hidden sm:inline">{poi.label}</span>
              </button>
            ))}
          </div>
      </div>

      {/* Map Container */}
      <div className="h-[400px] w-full rounded-2xl overflow-hidden border border-slate-200 shadow-inner relative z-0 group">
        <MapContainer center={[40.4168, -3.7038]} zoom={13} scrollWheelZoom={true}>
          <TileLayer
            attribution='&copy; OpenStreetMap'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />
          <MapController onAdd={handleAddPoint} centerOn={centerOn} routePath={routePath} />
          <AddPresetAtCenter onAdd={handleAddPoint} />

          {points.map((point, index) => {
            const routePos = getRouteIndex(index);
            const isRouteActive = routePos !== null;
            const isEditing = editingId === point.id;

            return (
              <Marker 
                key={point.id} 
                position={[point.lat, point.lng]}
                icon={isRouteActive ? createNumberedIcon(routePos, routePos === 0) : undefined}
                eventHandlers={{
                  popupclose: () => setEditingId(null),
                  click: () => setCenterOn([point.lat, point.lng])
                }}
              >
                <Popup className="custom-popup">
                  <div className="p-2 min-w-[180px]">
                    {isEditing ? (
                      <div className="space-y-2 mb-3">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Renombrar parada</label>
                        <div className="flex gap-1">
                          <input 
                            autoFocus
                            type="text"
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') handleUpdateLabel(point.id);
                              if (e.key === 'Escape') setEditingId(null);
                            }}
                            className="flex-1 px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500"
                          />
                          <button 
                            onClick={() => handleUpdateLabel(point.id)}
                            className="p-1 bg-brand-600 text-white rounded hover:bg-brand-700 transition"
                          >
                            <Check size={14} />
                          </button>
                          <button 
                            onClick={() => setEditingId(null)}
                            className="p-1 bg-slate-100 text-slate-400 rounded hover:bg-slate-200 transition"
                          >
                            <X size={14} />
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="group/label relative mb-1">
                        <p className="font-black text-slate-900 text-sm leading-tight pr-6">{point.label}</p>
                        <button 
                          onClick={() => startEditing(point)}
                          className="absolute top-0 right-0 p-1 text-slate-300 hover:text-brand-600 transition-colors"
                          title="Editar nombre"
                        >
                          <Edit3 size={14} />
                        </button>
                      </div>
                    )}

                    <div className="flex items-center justify-between mt-2 mb-3">
                      <span className="text-[10px] font-bold text-slate-400 uppercase">Referencia: #${index}</span>
                      {isRouteActive && (
                        <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded-full text-[10px] font-bold">
                          Parada n.º {routePos}
                        </span>
                      )}
                    </div>

                    <button 
                      onClick={() => handleRemovePoint(point.id)}
                      className="w-full text-[10px] font-bold uppercase tracking-wider text-red-500 bg-red-50 py-2 rounded-lg flex items-center justify-center gap-1.5 hover:bg-red-100 transition-colors"
                    >
                      <Trash2 size={12} /> Eliminar Punto
                    </button>
                  </div>
                </Popup>
              </Marker>
            );
          })}

          {routePath.length > 1 && (
            <>
              <Polyline 
                  positions={routePath} 
                  color="#2563eb" 
                  weight={10} 
                  opacity={0.2} 
                  lineCap="round"
              />
              <Polyline 
                  positions={routePath} 
                  color="#3b82f6" 
                  weight={4} 
                  opacity={1} 
                  lineCap="round"
              />
            </>
          )}
        </MapContainer>

        {/* Map Overlays */}
        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2 pointer-events-none items-end">
            <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 shadow-md text-[10px] text-slate-600 font-bold uppercase tracking-wider flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${routeSequence ? 'bg-emerald-500' : 'bg-amber-500'} animate-pulse`}></div>
                {routeSequence ? 'Ruta Optimizada' : 'Planificador Manual'}
            </div>
            {mapActivity && (
              <div className="bg-slate-900/90 backdrop-blur px-3 py-1.5 rounded-lg text-[9px] text-white font-black uppercase tracking-[0.15em] flex items-center gap-2 animate-in slide-in-from-right-4 duration-300 shadow-xl border border-white/10">
                <Activity size={12} className="animate-pulse text-brand-400" />
                {mapActivity}
              </div>
            )}
        </div>

        <div className="absolute bottom-4 left-4 z-[1000] pointer-events-none">
          <div className="bg-white/90 backdrop-blur px-2 py-1 rounded-md border border-slate-200 shadow-sm text-[8px] text-slate-400 font-bold uppercase">
            Interactividad Leaflet 1.9.4
          </div>
        </div>
      </div>

      {/* Points Summary Grid - UPGRADED WITH INLINE EDITING */}
      {points.length > 0 && (
        <div className="bg-slate-50 border border-slate-200 rounded-2xl p-5 transition-all animate-in slide-in-from-bottom-4">
            <div className="flex justify-between items-center mb-5">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-slate-200 rounded-lg text-slate-600">
                    <Tag size={16} />
                  </div>
                  <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest">Gestión de Entregas</h4>
                  <span className="bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded text-[10px] font-bold shadow-sm">{points.length} puntos registrados</span>
                </div>
                <button 
                    onClick={() => onPointsChange([])}
                    className="text-[10px] font-bold text-red-500 hover:text-red-700 uppercase tracking-widest bg-red-50 px-3 py-1 rounded-lg transition-colors border border-red-100"
                >
                    Limpiar Mapa
                </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {points.map((p, i) => {
                    const routePos = getRouteIndex(i);
                    const isEditing = editingId === p.id;

                    return (
                      <div 
                        key={p.id} 
                        className={`bg-white border-2 rounded-xl p-3 flex items-center gap-3 shadow-sm transition-all duration-300 ${isEditing ? 'border-brand-500 ring-4 ring-brand-50 shadow-md scale-[1.02]' : 'border-slate-100 hover:border-brand-200'}`}
                      >
                          <div className={`w-8 h-8 rounded-lg ${routePos !== null ? 'bg-brand-600 text-white' : 'bg-slate-100 text-slate-400'} flex items-center justify-center text-[11px] font-black shrink-0 shadow-sm`}>
                              {routePos !== null ? routePos : i}
                          </div>

                          <div className="flex-1 min-w-0">
                              {isEditing ? (
                                <div className="flex flex-col gap-1">
                                  <input 
                                    autoFocus
                                    type="text"
                                    value={editValue}
                                    onChange={(e) => setEditValue(e.target.value)}
                                    onKeyDown={(e) => {
                                      if (e.key === 'Enter') handleUpdateLabel(p.id);
                                      if (e.key === 'Escape') setEditingId(null);
                                    }}
                                    className="w-full px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500 font-bold"
                                  />
                                  <div className="flex gap-2">
                                    <button onClick={() => handleUpdateLabel(p.id)} className="text-[9px] font-black text-emerald-600 uppercase">Guardar</button>
                                    <button onClick={() => setEditingId(null)} className="text-[9px] font-black text-slate-400 uppercase">Cancelar</button>
                                  </div>
                                </div>
                              ) : (
                                <div className="group/text flex flex-col cursor-pointer" onClick={() => startEditing(p)}>
                                  <div className="flex items-center gap-1">
                                    <p className="text-[11px] font-black text-slate-800 truncate leading-none mb-1">{p.label}</p>
                                    <Edit3 size={10} className="text-slate-300 opacity-0 group-hover/text:opacity-100 transition-opacity" />
                                  </div>
                                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">Referencia: #${i}</p>
                                </div>
                              )}
                          </div>

                          <div className="flex items-center gap-1">
                            {!isEditing && (
                              <button 
                                onClick={() => startEditing(p)} 
                                className="text-slate-300 hover:text-brand-600 transition-colors p-1.5 rounded-lg hover:bg-brand-50"
                                title="Editar nombre"
                              >
                                <Edit3 size={14} />
                              </button>
                            )}
                            <button 
                                onClick={() => handleRemovePoint(p.id)} 
                                className="text-slate-300 hover:text-red-500 transition-colors p-1.5 rounded-lg hover:bg-red-50"
                                title="Eliminar"
                            >
                                <Trash2 size={14} />
                            </button>
                          </div>
                      </div>
                    );
                })}
            </div>
        </div>
      )}
      <style>{`
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
        .no-scrollbar {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
};

