import { GoogleGenAI, Type } from "@google/genai";
import { ToolType, MapPoint } from "../types";

const getSystemPrompt = (): string => {
  return "Eres un consultor experto senior en logística integral. Manejas a la perfección el manual MF1012 (Distribución Capilar), MF1013 (Transporte de Larga Distancia) y la normativa ADR (Mercancías Peligrosas). Tu objetivo es ayudar a profesionales del sector a resolver dudas técnicas, operativas y legales. Responde de forma técnica, rápida, estructurada y en español.";
};

export const generateLogisticsResponse = async function* (
  type: ToolType, 
  userInput: string,
  points?: MapPoint[]
): AsyncGenerator<string, void, unknown> {

  if (!process.env.API_KEY) {
    throw new Error("API Key no configurada. Por favor, revisa las variables de entorno.");
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = "";
    let schema: any = undefined;
    let responseMimeType = "text/plain";

    if (type === ToolType.ROUTE) {
      responseMimeType = "application/json";
      const pointsInfo = points && points.length > 0 
        ? `\nLISTADO DE ENTREGAS (Mapa):\n${points.map((p, i) => `[ID ${i}] Nombre/Zona: ${p.label} (Lat: ${p.lat}, Lng: ${p.lng})`).join('\n')}`
        : "";

      prompt = `Actúa como un planificador de tráfico avanzado. Optimiza la siguiente ruta de distribución capilar basándote en la eficiencia de última milla. 
      ${pointsInfo}

      Instrucciones adicionales: "${userInput}"

      Debes devolver UN OBJETO JSON con:
      1. explanation: Una explicación detallada paso a paso, mencionando los nombres de las calles/puntos proporcionados.
      2. optimizedSequence: El orden numérico óptimo de los índices [ID X] (ej: [0, 2, 1]).`;

      schema = {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING, description: "Análisis logístico paso a paso usando nombres de calles y consejos de eficiencia." },
          optimizedSequence: { 
            type: Type.ARRAY, 
            items: { type: Type.INTEGER },
            description: "Secuencia numérica de los índices proporcionados."
          }
        },
        required: ["explanation", "optimizedSequence"]
      };
    } else if (type === ToolType.CONTRACT) {
      prompt = `Redacta un borrador estructurado o las cláusulas legales clave para el siguiente supuesto, basándote en la Ley del Contrato de Transporte Terrestre y normativa vigente (LOTT/ROTT).\n\nSupuesto: "${userInput}"`;
    } else {
      prompt = `Responde a la siguiente consulta técnica sobre logística integral, normativa internacional o mercancías peligrosas (ADR):\n\nConsulta: "${userInput}"`;
    }

    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemPrompt(),
        temperature: 0.7,
        responseMimeType: responseMimeType as any,
        responseSchema: schema
      },
    });

    for await (const chunk of response) {
      const text = chunk.text;
      if (text) {
        yield text;
      }
    }

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    let message = error.message || "Error desconocido";
    throw new Error(message);
  }
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'preparing' | 'geocoding' | 'connecting' | 'streaming' | 'finalizing' | 'locating';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  // States for Saved Routes
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showSavedList, setShowSavedList] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [editingRouteId, setEditingRouteId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try {
          setSavedRoutes(JSON.parse(stored));
        } catch (e) {
          console.error("Error loading saved routes", e);
        }
      }
    }
    return () => {
      isMounted.current = false;
    };
  }, [type]);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content !== null, state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  const hasMinPoints = points.length >= 2;
  const hasDescription = input.trim().length >= 5;
  const isInputValid = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  // Haversine formula for distance calculation
  const calculateTotalDistance = (routePoints: MapPoint[], sequence: number[]) => {
    if (sequence.length < 2) return 0;
    let total = 0;
    const R = 6371; // Earth radius in km

    for (let i = 0; i < sequence.length - 1; i++) {
      const p1 = routePoints[sequence[i]];
      const p2 = routePoints[sequence[i + 1]];

      const dLat = (p2.lat - p1.lat) * Math.PI / 180;
      const dLon = (p2.lng - p1.lng) * Math.PI / 180;
      const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(p1.lat * Math.PI / 180) * Math.cos(p2.lat * Math.PI / 180) * 
        Math.sin(dLon/2) * Math.sin(dLon/2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
      total += R * c;
    }
    return parseFloat(total.toFixed(2));
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
          setShowValidationErrors(false);
        } catch (err) {
          console.error("Geocoding error", err);
        } finally {
          setLoadingStage('idle');
        }
      },
      (err) => {
        setLoadingStage('idle');
        alert("No se pudo obtener tu ubicación.");
      },
      { enableHighAccuracy: true }
    );
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;

    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || '',
      totalDistance: calculateTotalDistance(points, state.routeData)
    };

    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const handleRenameRoute = (id: string) => {
    if (!editingName.trim()) return;
    const updated = savedRoutes.map(r => r.id === id ? { ...r, name: editingName.trim() } : r);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setEditingRouteId(null);
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({
      isLoading: false,
      content: route.explanation,
      error: null,
      routeData: route.routeData
    });
    setShowSavedList(false);
    setShowValidationErrors(false);
    setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Estás seguro de que deseas eliminar esta ruta?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const downloadRouteJson = (route: SavedRoute, e: React.MouseEvent) => {
    e.stopPropagation();
    const blob = new Blob([JSON.stringify(route, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${route.name.replace(/\s+/g, '_')}_logistics.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const filteredRoutes = useMemo(() => {
    return savedRoutes.filter(r => 
      r.name.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [savedRoutes, searchQuery]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-brand-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'O describe tu ruta aquí: "Reparto en zona norte, 5 paradas urgentes..."' 
      : 'Ej: Contrato de transporte fraccionado, responsabilidad por daños...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo a las 9:00 AM."
      : "Redacta una cláusula para un contrato donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setShowValidationErrors(false);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleGenerate = async () => {
    if (!isInputValid) {
      setShowValidationErrors(true);
      return;
    }

    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    setShowValidationErrors(false);

    try {
      await new Promise(r => setTimeout(r, 400));
      if (!isMounted.current) return;

      setLoadingStage('preparing');
      await new Promise(r => setTimeout(r, 400));

      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (loadingStage !== 'streaming') setLoadingStage('streaming');

        if (isRoute) {
          fullJsonString += chunk;
          // Extraer la explicación del JSON parcial de forma segura
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
            setState(prev => ({ ...prev, content: partialText }));
          }
        } else {
          // Streaming de texto plano directo
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current) {
        setLoadingStage('finalizing');
        if (isRoute) {
          try {
              // Limpiar posibles caracteres extra al final del stream de Gemini antes del parseo
              const cleanJson = fullJsonString.trim();
              const finalData = JSON.parse(cleanJson) as RouteResponse;
              setState({ 
                  isLoading: false, 
                  content: finalData.explanation, 
                  error: null,
                  routeData: finalData.optimizedSequence
              });
          } catch (e) {
              console.error("Parse final error", e);
              setState(prev => ({ ...prev, isLoading: false }));
          }
        } else {
          setState(prev => ({ ...prev, isLoading: false }));
        }
        setLoadingStage('idle');
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
        setLoadingStage('idle');
      }
    }
  };

  const getStageStatus = (stage: LoadingStage) => {
    const stages: LoadingStage[] = ['validating', 'preparing', 'connecting', 'streaming', 'finalizing'];
    const currentIndex = stages.indexOf(loadingStage);
    const stageIndex = stages.indexOf(stage);

    if (currentIndex > stageIndex) return 'completed';
    if (currentIndex === stageIndex) return 'active';
    return 'pending';
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'validating': return "Validando restricciones...";
      case 'preparing': return isRoute ? "Analizando coordenadas..." : "Preparando normativa...";
      case 'connecting': return "Accediendo a Gemini Pro...";
      case 'streaming': return isRoute ? "Optimizando secuencia..." : "Generando cláusulas...";
      case 'finalizing': return "Aplicando telemetría final...";
      case 'locating': return "Obteniendo coordenadas GPS...";
      default: return "Cargando...";
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                  <Sparkles size={12} className="text-amber-500" />
                  <span>AI Professional Tool</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <div className="flex gap-2">
              <button 
                onClick={() => setShowSavedList(!showSavedList)}
                className={`flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold border transition-all shadow-sm ${showSavedList ? 'bg-brand-600 text-white border-brand-600' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
              >
                <History size={16} />
                <span className="hidden sm:inline">Historial</span>
                {savedRoutes.length > 0 && !showSavedList && (
                  <span className="bg-brand-100 text-brand-600 w-4 h-4 rounded-full flex items-center justify-center text-[10px]">
                    {savedRoutes.length}
                  </span>
                )}
              </button>
              <button 
                onClick={handleAddCurrentLocation}
                disabled={loadingStage === 'locating'}
                className="hidden sm:flex items-center gap-2 px-3 py-2 bg-brand-50 text-brand-700 text-xs font-bold rounded-xl border border-brand-200 hover:bg-brand-100 transition-all shadow-sm group disabled:opacity-50"
              >
                {loadingStage === 'locating' ? <Loader2 size={16} className="animate-spin" /> : <Navigation2 size={16} />}
                {loadingStage === 'locating' ? "GPS" : "GPS"}
              </button>
            </div>
          )}
        </div>

        {isRoute && showSavedList ? (
          <div className="mb-6 animate-in slide-in-from-top-4 duration-300 flex-1 flex flex-col">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-4 flex-1 flex flex-col shadow-inner">
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                    <FolderOpen size={14} /> Biblioteca de Rutas
                  </h4>
                  <button onClick={() => setShowSavedList(false)} className="text-[10px] font-bold text-slate-400 hover:text-slate-600 uppercase">Cerrar</button>
                </div>

                <div className="relative mb-4">
                  <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">
                    <Search size={16} />
                  </div>
                  <input 
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Filtrar por nombre de ruta..."
                    className="w-full pl-10 pr-10 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm transition-all placeholder:text-slate-400"
                  />
                  {searchQuery ? (
                    <button 
                      onClick={() => setSearchQuery('')}
                      className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 text-slate-300 hover:text-slate-600 transition-colors"
                    >
                      <X size={16} />
                    </button>
                  ) : (
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300">
                      <Filter size={16} />
                    </div>
                  )}
                </div>

                {filteredRoutes.length === 0 ? (
                  <div className="flex flex-col items-center justify-center flex-1 text-center text-slate-400 py-10 bg-white/50 rounded-xl border border-dashed border-slate-200">
                    <History size={48} className="mb-3 opacity-10" />
                    <p className="text-sm font-medium px-4">
                      {searchQuery 
                        ? `No se encontraron rutas con el nombre "${searchQuery}"` 
                        : 'Tu biblioteca de rutas está vacía'}
                    </p>
                    {searchQuery && (
                      <button 
                        onClick={() => setSearchQuery('')} 
                        className="mt-4 text-xs font-bold text-brand-600 bg-brand-50 px-4 py-2 rounded-lg hover:bg-brand-100 transition-colors"
                      >
                        Mostrar todas las rutas
                      </button>
                    )}
                  </div>
                ) : (
                  <div className="space-y-3 max-h-[480px] overflow-y-auto pr-2 custom-scrollbar flex-1">
                    <div className="flex items-center justify-between mb-1 px-1">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        {filteredRoutes.length} {filteredRoutes.length === 1 ? 'resultado' : 'resultados'}
                      </span>
                    </div>
                    {filteredRoutes.map((route) => (
                      <div 
                        key={route.id} 
                        onClick={() => !editingRouteId && loadSavedRoute(route)}
                        className={`group bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:border-brand-400 hover:shadow-md transition-all cursor-pointer ${editingRouteId === route.id ? 'ring-2 ring-brand-500' : ''}`}
                      >
                        <div className="flex items-center justify-between mb-3">
                          <div className="flex items-center gap-3 flex-1 min-w-0">
                            <div className="w-10 h-10 bg-brand-50 rounded-lg flex items-center justify-center text-brand-600 shrink-0 group-hover:bg-brand-600 group-hover:text-white transition-colors">
                              <MapPin size={20} />
                            </div>
                            <div className="flex-1 min-w-0">
                              {editingRouteId === route.id ? (
                                <div className="flex gap-1" onClick={(e) => e.stopPropagation()}>
                                  <input 
                                    autoFocus
                                    type="text" 
                                    value={editingName} 
                                    onChange={(e) => setEditingName(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleRenameRoute(route.id)}
                                    className="w-full px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500"
                                  />
                                  <button onClick={() => handleRenameRoute(route.id)} className="p-1 text-emerald-600 hover:bg-emerald-50 rounded"><Check size={14}/></button>
                                  <button onClick={() => setEditingRouteId(null)} className="p-1 text-slate-400 hover:bg-slate-50 rounded"><X size={14}/></button>
                                </div>
                              ) : (
                                <p className="text-sm font-bold text-slate-800 truncate group-hover:text-brand-700">{route.name}</p>
                              )}
                              <p className="text-[10px] text-slate-400 flex items-center gap-2 mt-0.5 font-medium">
                                <Clock size={10} />
                                <span>{new Date(route.timestamp).toLocaleDateString()}</span>
                                <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                                <span>{route.points.length} puntos</span>
                                {route.totalDistance && (
                                  <>
                                    <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                                    <span className="text-brand-600 font-bold">{route.totalDistance} km</span>
                                  </>
                                )}
                              </p>
                            </div>
                          </div>
                        </div>

                        <div className="flex justify-between items-center pt-2 border-t border-slate-50" onClick={(e) => e.stopPropagation()}>
                           <button 
                              onClick={() => loadSavedRoute(route)}
                              className="flex items-center gap-2 px-4 py-2 bg-brand-600 text-white rounded-xl text-[11px] font-black uppercase tracking-wider hover:bg-brand-700 transition-all shadow-md active:scale-95"
                           >
                              <PlayCircle size={16} /> Cargar Ruta
                           </button>

                           <div className="flex gap-1.5">
                              <button 
                                onClick={() => { setEditingRouteId(route.id); setEditingName(route.name); }}
                                className="p-2 text-slate-400 hover:text-brand-600 hover:bg-brand-50 rounded-lg transition-colors"
                                title="Renombrar"
                              >
                                <Edit2 size={14} />
                              </button>
                              <button 
                                onClick={(e) => downloadRouteJson(route, e)}
                                className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"
                                title="Exportar JSON"
                              >
                                <Download size={14} />
                              </button>
                              <button 
                                onClick={(e) => deleteSavedRoute(route.id, e)}
                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                title="Eliminar"
                              >
                                <Trash2 size={14} />
                              </button>
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
             </div>
          </div>
        ) : (
          <>
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">
                {config.description}
            </p>

            {isRoute && (
                <div className={`mb-6 relative rounded-2xl overflow-hidden border-2 transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-red-400 ring-2 ring-red-100' : 'border-slate-200'}`}>
                    <LogisticsMap 
                        points={points} 
                        onPointsChange={(newPoints) => {
                          setPoints(newPoints);
                          if (newPoints.length >= 2) setShowValidationErrors(false);
                        }} 
                        routeSequence={state.routeData}
                        externalCenter={externalCenter}
                    />
                    {loadingStage === 'locating' && (
                      <div className="absolute inset-0 z-[2000] bg-white/40 backdrop-blur-[2px] flex items-center justify-center rounded-2xl">
                        <div className="bg-white p-4 rounded-2xl shadow-xl border border-slate-100 flex flex-col items-center gap-2 animate-in zoom-in duration-300">
                          <Loader2 className="animate-spin text-brand-600" size={32} />
                          <span className="text-xs font-black text-slate-700 uppercase tracking-widest">Localizando...</span>
                        </div>
                      </div>
                    )}
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button
                    type="button"
                    onClick={handleExampleClick}
                    disabled={state.isLoading}
                    className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100' : 'text-purple-700 bg-purple-50 hover:bg-purple-100'} px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 disabled:opacity-50`}
                >
                    <Sparkles size={14} /> Ver Ejemplo
                </button>
            </div>

            <div className="relative mb-6">
                <textarea
                  ref={textareaRef}
                  value={input}
                  onChange={(e) => {
                    setInput(e.target.value);
                    if (e.target.value.trim().length >= 5) setShowValidationErrors(false);
                  }}
                  disabled={state.isLoading}
                  rows={isRoute ? 3 : 5}
                  className={`w-full p-4 border-2 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400 ${showValidationErrors && !hasDescription ? 'border-red-400 animate-shake' : 'border-slate-200'}`}
                  style={{ 
                      //@ts-ignore
                      '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
                  }}
                  placeholder={config.placeholder}
                />
                {showValidationErrors && !hasDescription && (
                  <div className="absolute -bottom-5 left-1 text-[10px] font-bold text-red-500 uppercase flex items-center gap-1">
                    <AlertCircle size={10} /> La descripción es demasiado corta (mín. 5 carac.)
                  </div>
                )}
            </div>

            <div className="mt-auto">
              {state.isLoading && (
                <div className="mb-6 bg-slate-50 rounded-2xl p-4 border border-slate-200 animate-in fade-in zoom-in duration-300">
                  <div className="flex items-center justify-between mb-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                      <Zap size={14} className="text-brand-500 animate-pulse" />
                      Procesando con Gemini AI
                    </h4>
                    <span className="text-[10px] font-bold text-brand-600 bg-brand-50 px-2 py-0.5 rounded-full animate-pulse">
                      {getLoadingMessage()}
                    </span>
                  </div>

                  <div className="flex gap-2">
                    {['validating', 'preparing', 'connecting', 'streaming', 'finalizing'].map((stage, idx) => {
                      const status = getStageStatus(stage as LoadingStage);
                      return (
                        <div key={stage} className="flex-1 flex flex-col gap-2">
                          <div className={`h-1.5 rounded-full transition-all duration-500 ${
                            status === 'completed' ? config.bgColor : 
                            status === 'active' ? config.bgColor + ' animate-pulse' : 
                            'bg-slate-200'
                          }`}></div>
                          <span className={`text-[8px] font-bold uppercase text-center ${status === 'active' ? 'text-slate-900' : 'text-slate-400'}`}>
                            Paso 0{idx + 1}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="relative">
                <button
                  onClick={handleGenerate}
                  disabled={state.isLoading}
                  className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-40 disabled:grayscale disabled:cursor-not-allowed`}
                >
                  {state.isLoading ? (
                    <>
                      <Loader2 className="animate-spin" size={20} />
                      <span>{getLoadingMessage()}</span>
                    </>
                  ) : (
                    <>
                      <Sparkles size={20} />
                      <span>Optimizar con IA</span>
                    </>
                  )}
                </button>
                {state.isLoading && (
                  <div className="absolute -bottom-1 left-0 w-full h-1 bg-slate-100 rounded-full overflow-hidden">
                    <div className={`h-full ${config.bgColor} animate-progress-indeterminate rounded-full`}></div>
                  </div>
                )}
              </div>
              {showValidationErrors && (
                <div className="mt-3 flex items-center justify-center gap-2 text-[11px] font-bold text-red-500 animate-in fade-in slide-in-from-top-1 duration-300">
                  <AlertCircle size={14} className="shrink-0" />
                  <span>
                    {isRoute 
                      ? "Se requiere al menos 2 puntos en el mapa o una descripción de min. 5 caracteres." 
                      : "Por favor, escribe una descripción detallada del supuesto (mín. 5 caracteres)."}
                  </span>
                </div>
              )}
            </div>
          </>
        )}

        <div ref={resultRef} className="scroll-mt-24">
          {state.error && (
            <div className="mt-4 p-4 bg-red-50 text-red-800 text-sm rounded-xl border border-red-200 flex flex-col gap-2">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="shrink-0 mt-0.5 text-red-600" size={18} />
                   <p className="text-red-700 leading-relaxed">{state.error}</p>
               </div>
               <button onClick={handleGenerate} className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-red-200 text-red-700 text-xs font-semibold rounded-lg hover:bg-red-50 transition-all shadow-sm">
                  <RefreshCw size={12} /> Reintentar
               </button>
            </div>
          )}

          {state.content !== null && !showSavedList && (
            <div className={`mt-6 rounded-2xl border ${config.borderColor} overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500`}>
               <div className={`p-5 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <Clock size={14} className={isRoute ? 'text-brand-600' : 'text-purple-600'} />
                      <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                        {state.isLoading ? 'Análisis en curso...' : 'Informe generado'}
                      </span>
                    </div>
                    {!state.isLoading && isRoute && !isSaving && (
                      <button 
                        onClick={() => setIsSaving(true)}
                        className="flex items-center gap-1.5 px-3 py-1 bg-white border border-brand-200 text-brand-700 rounded-lg text-[10px] font-bold hover:bg-brand-50 transition-all"
                      >
                        <Save size={12} /> Guardar Ruta
                      </button>
                    )}
                  </div>

                  {isSaving && (
                    <div className="mb-4 p-3 bg-white rounded-xl border border-brand-200 animate-in zoom-in duration-200">
                      <p className="text-[10px] font-bold text-slate-500 uppercase mb-2">Nombre de la ruta</p>
                      <div className="flex gap-2">
                        <input 
                          autoFocus
                          type="text"
                          value={routeName}
                          onChange={(e) => setRouteName(e.target.value)}
                          placeholder="Ej: Reparto Mañana Zona Centro"
                          className="flex-1 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs outline-none focus:ring-1 focus:ring-brand-500"
                        />
                        <button 
                          onClick={handleSaveRoute}
                          disabled={!routeName.trim()}
                          className="px-4 py-2 bg-brand-600 text-white rounded-lg text-xs font-bold hover:bg-brand-700 disabled:opacity-50"
                        >
                          Confirmar
                        </button>
                        <button 
                          onClick={() => setIsSaving(false)}
                          className="px-4 py-2 bg-slate-100 text-slate-500 rounded-lg text-xs font-bold hover:bg-slate-200"
                        >
                          Cancelar
                        </button>
                      </div>
                    </div>
                  )}

                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                          {state.content}
                          {state.isLoading && <span className={`inline-block w-1.5 h-4 ml-1 ${config.bgColor} animate-pulse align-middle`}></span>}
                      </div>
                  </div>
               </div>

               <div className="bg-white border-t border-slate-100 p-3 flex justify-between items-center">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-2">
                      {state.isLoading ? getLoadingMessage() : 'Resultado finalizado'}
                    </span>
                  </div>
                  <button 
                      onClick={handleCopy}
                      disabled={!state.content}
                      className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all duration-200 ${copied ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-slate-50 text-slate-700 border border-slate-200 hover:bg-slate-100'} disabled:opacity-50`}
                  >
                      {copied ? (
                        <>
                          <Check size={14} className="text-emerald-500" />
                          <span>¡Copiado!</span>
                        </>
                      ) : (
                        <>
                          <Copy size={14} />
                          <span>Copiar resultado</span>
                        </>
                      )}
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        @keyframes progress-indeterminate {
          0% { transform: translateX(-100%); width: 30%; }
          50% { transform: translateX(50%); width: 60%; }
          100% { transform: translateX(100%); width: 30%; }
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-progress-indeterminate {
          animation: progress-indeterminate 1.5s infinite linear;
        }
        .animate-shake {
          animation: shake 0.2s ease-in-out 0s 2;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter, SortAsc, LayoutGrid, List } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'preparing' | 'geocoding' | 'connecting' | 'streaming' | 'finalizing' | 'locating';
type SortOption = 'date' | 'name' | 'distance';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  // States for Saved Routes
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showSavedList, setShowSavedList] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [editingRouteId, setEditingRouteId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try {
          setSavedRoutes(JSON.parse(stored));
        } catch (e) {
          console.error("Error loading saved routes", e);
        }
      }
    }
    return () => {
      isMounted.current = false;
    };
  }, [type]);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content !== null, state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  const hasMinPoints = points.length >= 2;
  const hasDescription = input.trim().length >= 5;
  const isInputValid = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  // Haversine formula for distance calculation
  const calculateTotalDistance = (routePoints: MapPoint[], sequence: number[]) => {
    if (sequence.length < 2) return 0;
    let total = 0;
    const R = 6371; // Earth radius in km

    for (let i = 0; i < sequence.length - 1; i++) {
      const p1 = routePoints[sequence[i]];
      const p2 = routePoints[sequence[i + 1]];

      const dLat = (p2.lat - p1.lat) * Math.PI / 180;
      const dLon = (p2.lng - p1.lng) * Math.PI / 180;
      const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(p1.lat * Math.PI / 180) * Math.cos(p2.lat * Math.PI / 180) * 
        Math.sin(dLon/2) * Math.sin(dLon/2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
      total += R * c;
    }
    return parseFloat(total.toFixed(2));
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
          setShowValidationErrors(false);
        } catch (err) {
          console.error("Geocoding error", err);
        } finally {
          setLoadingStage('idle');
        }
      },
      (err) => {
        setLoadingStage('idle');
        alert("No se pudo obtener tu ubicación.");
      },
      { enableHighAccuracy: true }
    );
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;

    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || '',
      totalDistance: calculateTotalDistance(points, state.routeData)
    };

    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const handleRenameRoute = (id: string) => {
    if (!editingName.trim()) return;
    const updated = savedRoutes.map(r => r.id === id ? { ...r, name: editingName.trim() } : r);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setEditingRouteId(null);
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({
      isLoading: false,
      content: route.explanation,
      error: null,
      routeData: route.routeData
    });
    setShowSavedList(false);
    setShowValidationErrors(false);
    setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Estás seguro de que deseas eliminar esta ruta?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const downloadRouteJson = (route: SavedRoute, e: React.MouseEvent) => {
    e.stopPropagation();
    const blob = new Blob([JSON.stringify(route, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${route.name.replace(/\s+/g, '_')}_logistics.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Advanced Sorting & Filtering
  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => 
      r.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return filtered.sort((a, b) => {
      if (sortBy === 'date') return b.timestamp - a.timestamp;
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'distance') return (b.totalDistance || 0) - (a.totalDistance || 0);
      return 0;
    });
  }, [savedRoutes, searchQuery, sortBy]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-brand-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'O describe tu ruta aquí: "Reparto en zona norte, 5 paradas urgentes..."' 
      : 'Ej: Contrato de transporte fraccionado, responsabilidad por daños...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo a las 9:00 AM."
      : "Redacta una cláusula para un contrato donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setShowValidationErrors(false);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleGenerate = async () => {
    if (!isInputValid) {
      setShowValidationErrors(true);
      return;
    }

    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    setShowValidationErrors(false);

    try {
      await new Promise(r => setTimeout(r, 400));
      if (!isMounted.current) return;

      setLoadingStage('preparing');
      await new Promise(r => setTimeout(r, 400));

      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (loadingStage !== 'streaming') setLoadingStage('streaming');

        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
            setState(prev => ({ ...prev, content: partialText }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current) {
        setLoadingStage('finalizing');
        if (isRoute) {
          try {
              const cleanJson = fullJsonString.trim();
              const finalData = JSON.parse(cleanJson) as RouteResponse;
              setState({ 
                  isLoading: false, 
                  content: finalData.explanation, 
                  error: null,
                  routeData: finalData.optimizedSequence
              });
          } catch (e) {
              console.error("Parse final error", e);
              setState(prev => ({ ...prev, isLoading: false }));
          }
        } else {
          setState(prev => ({ ...prev, isLoading: false }));
        }
        setLoadingStage('idle');
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
        setLoadingStage('idle');
      }
    }
  };

  const getStageStatus = (stage: LoadingStage) => {
    const stages: LoadingStage[] = ['validating', 'preparing', 'connecting', 'streaming', 'finalizing'];
    const currentIndex = stages.indexOf(loadingStage);
    const stageIndex = stages.indexOf(stage);

    if (currentIndex > stageIndex) return 'completed';
    if (currentIndex === stageIndex) return 'active';
    return 'pending';
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'validating': return "Validando restricciones...";
      case 'preparing': return isRoute ? "Analizando coordenadas..." : "Preparando normativa...";
      case 'connecting': return "Accediendo a Gemini Pro...";
      case 'streaming': return isRoute ? "Optimizando secuencia..." : "Generando cláusulas...";
      case 'finalizing': return "Aplicando telemetría final...";
      case 'locating': return "Obteniendo coordenadas GPS...";
      default: return "Cargando...";
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-xs font-semibold text-slate-500 uppercase tracking-wider mt-1">
                  <Sparkles size={12} className="text-amber-500" />
                  <span>AI Professional Tool</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <div className="flex gap-2">
              <button 
                onClick={() => setShowSavedList(!showSavedList)}
                className={`flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold border transition-all shadow-sm ${showSavedList ? 'bg-brand-600 text-white border-brand-600' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
              >
                <History size={16} />
                <span className="hidden sm:inline">Historial</span>
                {savedRoutes.length > 0 && !showSavedList && (
                  <span className="bg-brand-100 text-brand-600 w-4 h-4 rounded-full flex items-center justify-center text-[10px]">
                    {savedRoutes.length}
                  </span>
                )}
              </button>
              <button 
                onClick={handleAddCurrentLocation}
                disabled={loadingStage === 'locating'}
                className="hidden sm:flex items-center gap-2 px-3 py-2 bg-brand-50 text-brand-700 text-xs font-bold rounded-xl border border-brand-200 hover:bg-brand-100 transition-all shadow-sm group disabled:opacity-50"
              >
                {loadingStage === 'locating' ? <Loader2 size={16} className="animate-spin" /> : <Navigation2 size={16} />}
                {loadingStage === 'locating' ? "GPS" : "GPS"}
              </button>
            </div>
          )}
        </div>

        {isRoute && showSavedList ? (
          <div className="mb-6 animate-in slide-in-from-top-4 duration-300 flex-1 flex flex-col">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-4 flex-1 flex flex-col shadow-inner">
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                    <FolderOpen size={14} /> Biblioteca de Rutas
                  </h4>
                  <button onClick={() => setShowSavedList(false)} className="text-[10px] font-bold text-slate-400 hover:text-slate-600 uppercase">Cerrar</button>
                </div>

                {/* Advanced Search & Filter Bar */}
                <div className="flex flex-col sm:flex-row gap-2 mb-4">
                  <div className="relative flex-1">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">
                      <Search size={16} />
                    </div>
                    <input 
                      type="text"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder="Buscar por nombre..."
                      className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm transition-all placeholder:text-slate-400"
                    />
                    {searchQuery && (
                      <button 
                        onClick={() => setSearchQuery('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
                      >
                        <X size={14} />
                      </button>
                    )}
                  </div>
                  <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-xl px-2 py-1 shadow-sm">
                    <SortAsc size={14} className="text-slate-400 ml-1" />
                    <select 
                      value={sortBy}
                      onChange={(e) => setSortBy(e.target.value as SortOption)}
                      className="bg-transparent text-xs font-bold text-slate-600 outline-none pr-1 cursor-pointer"
                    >
                      <option value="date">Recientes</option>
                      <option value="name">Nombre</option>
                      <option value="distance">Distancia</option>
                    </select>
                  </div>
                </div>

                {processedRoutes.length === 0 ? (
                  <div className="flex flex-col items-center justify-center flex-1 text-center text-slate-400 py-10 bg-white/50 rounded-xl border border-dashed border-slate-200">
                    <History size={48} className="mb-3 opacity-10" />
                    <p className="text-sm font-medium px-4 leading-relaxed">
                      {searchQuery 
                        ? `No hay resultados para "${searchQuery}"` 
                        : 'Tu biblioteca de rutas está vacía'}
                    </p>
                    {searchQuery && (
                      <button 
                        onClick={() => setSearchQuery('')} 
                        className="mt-4 text-xs font-bold text-brand-600 bg-brand-50 px-4 py-2 rounded-lg hover:bg-brand-100 transition-colors"
                      >
                        Limpiar filtros
                      </button>
                    )}
                  </div>
                ) : (
                  <div className="space-y-3 max-h-[480px] overflow-y-auto pr-2 custom-scrollbar flex-1">
                    <div className="flex items-center justify-between mb-1 px-1">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        {processedRoutes.length} {processedRoutes.length === 1 ? 'ruta encontrada' : 'rutas encontradas'}
                      </span>
                    </div>
                    {processedRoutes.map((route) => (
                      <div 
                        key={route.id} 
                        className={`group bg-white p-4 rounded-2xl border border-slate-200 shadow-sm hover:border-brand-400 hover:shadow-md transition-all ${editingRouteId === route.id ? 'ring-2 ring-brand-500' : ''}`}
                      >
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center gap-3 flex-1 min-w-0">
                            <div className="w-10 h-10 bg-brand-50 rounded-xl flex items-center justify-center text-brand-600 shrink-0 group-hover:bg-brand-600 group-hover:text-white transition-colors">
                              <MapPin size={20} />
                            </div>
                            <div className="flex-1 min-w-0">
                              {editingRouteId === route.id ? (
                                <div className="flex gap-1">
                                  <input 
                                    autoFocus
                                    type="text" 
                                    value={editingName} 
                                    onChange={(e) => setEditingName(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleRenameRoute(route.id)}
                                    className="w-full px-2 py-1 bg-slate-50 border border-slate-200 rounded text-xs outline-none focus:ring-1 focus:ring-brand-500"
                                  />
                                  <button onClick={() => handleRenameRoute(route.id)} className="p-1 text-emerald-600 hover:bg-emerald-50 rounded"><Check size={14}/></button>
                                  <button onClick={() => setEditingRouteId(null)} className="p-1 text-slate-400 hover:bg-slate-50 rounded"><X size={14}/></button>
                                </div>
                              ) : (
                                <p className="text-sm font-black text-slate-800 truncate group-hover:text-brand-700">{route.name}</p>
                              )}
                              <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1">
                                <span className="text-[10px] text-slate-400 flex items-center gap-1 font-bold uppercase tracking-tight">
                                  <Clock size={10} /> {new Date(route.timestamp).toLocaleDateString()}
                                </span>
                                <span className="text-[10px] text-brand-600 flex items-center gap-1 font-bold uppercase tracking-tight">
                                  <Navigation2 size={10} /> {route.points.length} paradas
                                </span>
                                {route.totalDistance && (
                                  <span className="text-[10px] text-emerald-600 flex items-center gap-1 font-bold uppercase tracking-tight">
                                    <Activity size={10} /> {route.totalDistance} km
                                  </span>
                                )}
                              </div>
                            </div>
                          </div>
                        </div>

                        <div className="flex justify-between items-center pt-3 border-t border-slate-50">
                           <button 
                              onClick={() => loadSavedRoute(route)}
                              className="flex items-center gap-2 px-5 py-2.5 bg-brand-600 text-white rounded-xl text-[11px] font-black uppercase tracking-wider hover:bg-brand-700 transition-all shadow-lg active:scale-95 group/btn"
                           >
                              <PlayCircle size={16} className="group-hover/btn:scale-110 transition-transform" /> Cargar Ruta
                           </button>

                           <div className="flex gap-1">
                              <button 
                                onClick={() => { setEditingRouteId(route.id); setEditingName(route.name); }}
                                className="p-2 text-slate-400 hover:text-brand-600 hover:bg-brand-50 rounded-lg transition-colors"
                                title="Renombrar"
                              >
                                <Edit2 size={14} />
                              </button>
                              <button 
                                onClick={(e) => downloadRouteJson(route, e)}
                                className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"
                                title="Exportar JSON"
                              >
                                <Download size={14} />
                              </button>
                              <button 
                                onClick={(e) => deleteSavedRoute(route.id, e)}
                                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                title="Eliminar"
                              >
                                <Trash2 size={14} />
                              </button>
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
             </div>
          </div>
        ) : (
          <>
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">
                {config.description}
            </p>

            {isRoute && (
                <div className={`mb-6 relative rounded-2xl overflow-hidden border-2 transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-red-400 ring-2 ring-red-100' : 'border-slate-200'}`}>
                    <LogisticsMap 
                        points={points} 
                        onPointsChange={(newPoints) => {
                          setPoints(newPoints);
                          if (newPoints.length >= 2) setShowValidationErrors(false);
                        }} 
                        routeSequence={state.routeData}
                        externalCenter={externalCenter}
                    />
                    {loadingStage === 'locating' && (
                      <div className="absolute inset-0 z-[2000] bg-white/40 backdrop-blur-[2px] flex items-center justify-center rounded-2xl">
                        <div className="bg-white p-4 rounded-2xl shadow-xl border border-slate-100 flex flex-col items-center gap-2 animate-in zoom-in duration-300">
                          <Loader2 className="animate-spin text-brand-600" size={32} />
                          <span className="text-xs font-black text-slate-700 uppercase tracking-widest">Localizando...</span>
                        </div>
                      </div>
                    )}
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button
                    type="button"
                    onClick={handleExampleClick}
                    disabled={state.isLoading}
                    className={`text-xs font-semibold ${isRoute ? 'text-brand-700 bg-brand-50 hover:bg-brand-100' : 'text-purple-700 bg-purple-50 hover:bg-purple-100'} px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 disabled:opacity-50`}
                >
                    <Sparkles size={14} /> Ver Ejemplo
                </button>
            </div>

            <div className="relative mb-6">
                <textarea
                  ref={textareaRef}
                  value={input}
                  onChange={(e) => {
                    setInput(e.target.value);
                    if (e.target.value.trim().length >= 5) setShowValidationErrors(false);
                  }}
                  disabled={state.isLoading}
                  rows={isRoute ? 3 : 5}
                  className={`w-full p-4 border-2 rounded-xl bg-slate-50 focus:ring-2 focus:ring-offset-2 outline-none transition-all resize-none text-sm text-slate-700 placeholder:text-slate-400 ${showValidationErrors && !hasDescription ? 'border-red-400 animate-shake' : 'border-slate-200'}`}
                  style={{ 
                      //@ts-ignore
                      '--tw-ring-color': isRoute ? '#3b82f6' : '#9333ea' 
                  }}
                  placeholder={config.placeholder}
                />
                {showValidationErrors && !hasDescription && (
                  <div className="absolute -bottom-5 left-1 text-[10px] font-bold text-red-500 uppercase flex items-center gap-1">
                    <AlertCircle size={10} /> La descripción es demasiado corta (mín. 5 carac.)
                  </div>
                )}
            </div>

            <div className="mt-auto">
              {state.isLoading && (
                <div className="mb-6 bg-slate-50 rounded-2xl p-4 border border-slate-200 animate-in fade-in zoom-in duration-300">
                  <div className="flex items-center justify-between mb-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                      <Zap size={14} className="text-brand-500 animate-pulse" />
                      Procesando con Gemini AI
                    </h4>
                    <span className="text-[10px] font-bold text-brand-600 bg-brand-50 px-2 py-0.5 rounded-full animate-pulse">
                      {getLoadingMessage()}
                    </span>
                  </div>

                  <div className="flex gap-2">
                    {['validating', 'preparing', 'connecting', 'streaming', 'finalizing'].map((stage, idx) => {
                      const status = getStageStatus(stage as LoadingStage);
                      return (
                        <div key={stage} className="flex-1 flex flex-col gap-2">
                          <div className={`h-1.5 rounded-full transition-all duration-500 ${
                            status === 'completed' ? config.bgColor : 
                            status === 'active' ? config.bgColor + ' animate-pulse' : 
                            'bg-slate-200'
                          }`}></div>
                          <span className={`text-[8px] font-bold uppercase text-center ${status === 'active' ? 'text-slate-900' : 'text-slate-400'}`}>
                            Paso 0{idx + 1}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="relative">
                <button
                  onClick={handleGenerate}
                  disabled={state.isLoading}
                  className={`w-full ${config.buttonColor} text-white font-bold py-3.5 rounded-xl transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-40 disabled:grayscale disabled:cursor-not-allowed`}
                >
                  {state.isLoading ? (
                    <>
                      <Loader2 className="animate-spin" size={20} />
                      <span>{getLoadingMessage()}</span>
                    </>
                  ) : (
                    <>
                      <Sparkles size={20} />
                      <span>Optimizar con IA</span>
                    </>
                  )}
                </button>
                {state.isLoading && (
                  <div className="absolute -bottom-1 left-0 w-full h-1 bg-slate-100 rounded-full overflow-hidden">
                    <div className={`h-full ${config.bgColor} animate-progress-indeterminate rounded-full`}></div>
                  </div>
                )}
              </div>
              {showValidationErrors && (
                <div className="mt-3 flex items-center justify-center gap-2 text-[11px] font-bold text-red-500 animate-in fade-in slide-in-from-top-1 duration-300">
                  <AlertCircle size={14} className="shrink-0" />
                  <span>
                    {isRoute 
                      ? "Se requiere al menos 2 puntos en el mapa o una descripción de min. 5 caracteres." 
                      : "Por favor, escribe una descripción detallada del supuesto (mín. 5 caracteres)."}
                  </span>
                </div>
              )}
            </div>
          </>
        )}

        <div ref={resultRef} className="scroll-mt-24">
          {state.error && (
            <div className="mt-4 p-4 bg-red-50 text-red-800 text-sm rounded-xl border border-red-200 flex flex-col gap-2">
               <div className="flex items-start gap-3">
                   <AlertTriangle className="shrink-0 mt-0.5 text-red-600" size={18} />
                   <p className="text-red-700 leading-relaxed">{state.error}</p>
               </div>
               <button onClick={handleGenerate} className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-red-200 text-red-700 text-xs font-semibold rounded-lg hover:bg-red-50 transition-all shadow-sm">
                  <RefreshCw size={12} /> Reintentar
               </button>
            </div>
          )}

          {state.content !== null && !showSavedList && (
            <div className={`mt-6 rounded-2xl border ${config.borderColor} overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500`}>
               <div className={`p-5 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <Clock size={14} className={isRoute ? 'text-brand-600' : 'text-purple-600'} />
                      <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                        {state.isLoading ? 'Análisis en curso...' : 'Informe generado'}
                      </span>
                    </div>
                    {!state.isLoading && isRoute && !isSaving && (
                      <button 
                        onClick={() => setIsSaving(true)}
                        className="flex items-center gap-1.5 px-3 py-1 bg-white border border-brand-200 text-brand-700 rounded-lg text-[10px] font-bold hover:bg-brand-50 transition-all"
                      >
                        <Save size={12} /> Guardar Ruta
                      </button>
                    )}
                  </div>

                  {isSaving && (
                    <div className="mb-4 p-3 bg-white rounded-xl border border-brand-200 animate-in zoom-in duration-200">
                      <p className="text-[10px] font-bold text-slate-500 uppercase mb-2">Nombre de la ruta</p>
                      <div className="flex gap-2">
                        <input 
                          autoFocus
                          type="text"
                          value={routeName}
                          onChange={(e) => setRouteName(e.target.value)}
                          placeholder="Ej: Reparto Mañana Zona Centro"
                          className="flex-1 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs outline-none focus:ring-1 focus:ring-brand-500"
                        />
                        <button 
                          onClick={handleSaveRoute}
                          disabled={!routeName.trim()}
                          className="px-4 py-2 bg-brand-600 text-white rounded-lg text-xs font-bold hover:bg-brand-700 disabled:opacity-50"
                        >
                          Confirmar
                        </button>
                        <button 
                          onClick={() => setIsSaving(false)}
                          className="px-4 py-2 bg-slate-100 text-slate-500 rounded-lg text-xs font-bold hover:bg-slate-200"
                        >
                          Cancelar
                        </button>
                      </div>
                    </div>
                  )}

                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-700 font-medium leading-relaxed">
                          {state.content}
                          {state.isLoading && <span className={`inline-block w-1.5 h-4 ml-1 ${config.bgColor} animate-pulse align-middle`}></span>}
                      </div>
                  </div>
               </div>

               <div className="bg-white border-t border-slate-100 p-3 flex justify-between items-center">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest pl-2">
                      {state.isLoading ? getLoadingMessage() : 'Resultado finalizado'}
                    </span>
                  </div>
                  <button 
                      onClick={handleCopy}
                      disabled={!state.content}
                      className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all duration-200 ${copied ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-slate-50 text-slate-700 border border-slate-200 hover:bg-slate-100'} disabled:opacity-50`}
                  >
                      {copied ? (
                        <>
                          <Check size={14} className="text-emerald-500" />
                          <span>¡Copiado!</span>
                        </>
                      ) : (
                        <>
                          <Copy size={14} />
                          <span>Copiar resultado</span>
                        </>
                      )}
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        @keyframes progress-indeterminate {
          0% { transform: translateX(-100%); width: 30%; }
          50% { transform: translateX(50%); width: 60%; }
          100% { transform: translateX(100%); width: 30%; }
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-progress-indeterminate {
          animation: progress-indeterminate 1.5s infinite linear;
        }
        .animate-shake {
          animation: shake 0.2s ease-in-out 0s 2;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter, SortAsc, LayoutGrid, List, Activity } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'preparing' | 'geocoding' | 'connecting' | 'streaming' | 'finalizing' | 'locating';
type SortOption = 'date' | 'name' | 'distance';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  // States for Saved Routes
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showSavedList, setShowSavedList] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [editingRouteId, setEditingRouteId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try {
          setSavedRoutes(JSON.parse(stored));
        } catch (e) {
          console.error("Error loading saved routes", e);
        }
      }
    }
    return () => {
      isMounted.current = false;
    };
  }, [type]);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content !== null, state.error !== null]);

  const isRoute = type === ToolType.ROUTE;

  const hasMinPoints = points.length >= 2;
  const hasDescription = input.trim().length >= 5;
  const isInputValid = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  // Haversine formula for distance calculation
  const calculateTotalDistance = (routePoints: MapPoint[], sequence: number[]) => {
    if (sequence.length < 2) return 0;
    let total = 0;
    const R = 6371; // Earth radius in km

    for (let i = 0; i < sequence.length - 1; i++) {
      const p1 = routePoints[sequence[i]];
      const p2 = routePoints[sequence[i + 1]];

      const dLat = (p2.lat - p1.lat) * Math.PI / 180;
      const dLon = (p2.lng - p1.lng) * Math.PI / 180;
      const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(p1.lat * Math.PI / 180) * Math.cos(p2.lat * Math.PI / 180) * 
        Math.sin(dLon/2) * Math.sin(dLon/2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
      total += R * c;
    }
    return parseFloat(total.toFixed(2));
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("La geolocalización no está soportada por tu navegador.");
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Mi ubicación";

          const startPoint: MapPoint = {
            lat: latitude,
            lng: longitude,
            id: 'start-' + Date.now(),
            label: `🚩 Origen: ${address}`
          };

          setPoints(prev => [startPoint, ...prev.filter(p => !p.id.startsWith('start-'))]);
          setExternalCenter([latitude, longitude]);
          setShowValidationErrors(false);
        } catch (err) {
          console.error("Geocoding error", err);
        } finally {
          setLoadingStage('idle');
        }
      },
      (err) => {
        setLoadingStage('idle');
        alert("No se pudo obtener tu ubicación.");
      },
      { enableHighAccuracy: true }
    );
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;

    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || '',
      totalDistance: calculateTotalDistance(points, state.routeData)
    };

    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const handleRenameRoute = (id: string) => {
    if (!editingName.trim()) return;
    const updated = savedRoutes.map(r => r.id === id ? { ...r, name: editingName.trim() } : r);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setEditingRouteId(null);
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({
      isLoading: false,
      content: route.explanation,
      error: null,
      routeData: route.routeData
    });
    setShowSavedList(false);
    setShowValidationErrors(false);
    setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Estás seguro de que deseas eliminar esta ruta?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const downloadRouteJson = (route: SavedRoute, e: React.MouseEvent) => {
    e.stopPropagation();
    const blob = new Blob([JSON.stringify(route, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${route.name.replace(/\s+/g, '_')}_logistics.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Advanced Sorting & Filtering
  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => 
      r.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return filtered.sort((a, b) => {
      if (sortBy === 'date') return b.timestamp - a.timestamp;
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'distance') return (b.totalDistance || 0) - (a.totalDistance || 0);
      return 0;
    });
  }, [savedRoutes, searchQuery, sortBy]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    color: isRoute ? 'text-brand-600' : 'text-purple-600',
    bgColor: isRoute ? 'bg-brand-600' : 'bg-brand-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute 
      ? 'O describe tu ruta aquí: "Reparto en zona norte, 5 paradas urgentes..."' 
      : 'Ej: Contrato de transporte fraccionado, responsabilidad por daños...',
    description: isRoute 
      ? 'Optimiza secuencias de entrega usando el mapa interactivo y IA.' 
      : 'Redacta cláusulas y contratos basados en normativa LOTT/ROTT.',
    example: isRoute
      ? "Tengo estos puntos marcados en el mapa. Necesito optimizar el orden de entrega saliendo a las 9:00 AM."
      : "Redacta una cláusula para un contrato donde se especifique que el cargador es responsable de la estiba."
  };

  const handleExampleClick = () => {
    setInput(config.example);
    setShowValidationErrors(false);
    setTimeout(() => {
      if (textareaRef.current) {
        textareaRef.current.focus();
        textareaRef.current.setSelectionRange(config.example.length, config.example.length);
      }
    }, 0);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleGenerate = async () => {
    if (!isInputValid) {
      setShowValidationErrors(true);
      return;
    }

    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    setShowValidationErrors(false);

    try {
      await new Promise(r => setTimeout(r, 400));
      if (!isMounted.current) return;

      setLoadingStage('preparing');
      await new Promise(r => setTimeout(r, 400));

      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (loadingStage !== 'streaming') setLoadingStage('streaming');

        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            const partialText = match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
            setState(prev => ({ ...prev, content: partialText }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current) {
        setLoadingStage('finalizing');
        if (isRoute) {
          try {
              const cleanJson = fullJsonString.trim();
              const finalData = JSON.parse(cleanJson) as RouteResponse;
              setState({ 
                  isLoading: false, 
                  content: finalData.explanation, 
                  error: null,
                  routeData: finalData.optimizedSequence
              });
          } catch (e) {
              console.error("Parse final error", e);
              setState(prev => ({ ...prev, isLoading: false }));
          }
        } else {
          setState(prev => ({ ...prev, isLoading: false }));
        }
        setLoadingStage('idle');
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message || 'Error desconocido' });
        setLoadingStage('idle');
      }
    }
  };

  const getStageStatus = (stage: LoadingStage) => {
    const stages: LoadingStage[] = ['validating', 'preparing', 'connecting', 'streaming', 'finalizing'];
    const currentIndex = stages.indexOf(loadingStage);
    const stageIndex = stages.indexOf(stage);

    if (currentIndex > stageIndex) return 'completed';
    if (currentIndex === stageIndex) return 'active';
    return 'pending';
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'validating': return "Validando restricciones...";
      case 'preparing': return isRoute ? "Analizando coordenadas..." : "Preparando normativa...";
      case 'connecting': return "Accediendo a Gemini Pro...";
      case 'streaming': return isRoute ? "Optimizando secuencia..." : "Generando cláusulas...";
      case 'finalizing': return "Aplicando telemetría final...";
      case 'locating': return "Obteniendo coordenadas GPS...";
      default: return "Cargando...";
    }
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
