                  <button
                      onClick={handleExampleClick}
                      disabled={state.isLoading}
                      className="text-[10px] font-black uppercase tracking-widest text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg hover:bg-blue-100 transition-all flex items-center gap-1.5 disabled:opacity-50 group"
                  >
                      <Sparkles size={12} className="group-hover:rotate-12 transition-transform" /> Ver Ejemplo
                  </button>
                </div>

                <div className="relative">
                  <textarea 
                      value={input}
                      onChange={(e) => {
                        setInput(e.target.value);
                        if (e.target.value.trim().length >= 10) setShowError(false);
                      }}
                      disabled={state.isLoading}
                      className={`w-full p-4 border-2 rounded-xl bg-slate-50 text-sm min-h-[120px] focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all resize-none placeholder:text-slate-400 ${showError ? 'border-red-400 animate-shake' : 'border-slate-200'}`} 
                      placeholder="Ej: ¿Qué Incoterm usar para transporte marítimo? o ¿Qué paneles debe llevar un camión con explosivos?"
                  ></textarea>
                  {showError && (
                    <div className="absolute -bottom-5 left-1 text-[10px] font-bold text-red-500 uppercase flex items-center gap-1">
                      <AlertCircle size={10} /> La consulta debe tener al menos 10 caracteres
                    </div>
                  )}
                </div>

                <button 
                    onClick={handleConsult}
                    disabled={state.isLoading}
                    className="mt-6 w-full bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white py-3.5 rounded-xl font-bold flex items-center justify-center space-x-2 transition-all shadow-md active:scale-[0.99]"
                >
                    {state.isLoading ? (
                        <>
                            <Loader2 className="animate-spin" size={18} />
                            <span>Analizando normativa técnica...</span>
