import React, { useState, useRef, useEffect } from 'react';
import { Brain, Radiation, Ship, FileText, Gauge, Loader2, Send, AlertCircle, Sparkles, Clock, Copy, Check, RefreshCw } from 'lucide-react';
import { generateLogisticsResponse } from '../services/geminiService';
import { ToolType, GeneratedContentState } from '../types';

const LOGISTICS_EXAMPLES = [
  "¿Cuáles son los requisitos específicos de señalización ADR para un vehículo que transporta Baterías de Litio (UN 3480) y qué paneles debe portar?",
  "Explica la diferencia de responsabilidades entre los Incoterms FOB y CIF según las reglas de 2020, específicamente en la transmisión del riesgo.",
  "¿Cómo se calculan los tiempos de conducción y descanso semanales según el Reglamento (CE) nº 561/2006 para un conductor de larga distancia?",
  "Redacta los puntos clave que debe contener una Carta de Porte CMR para que sea legalmente válida en un transporte internacional a Francia.",
  "Calcula el coste por kilómetro de un vehículo articulado de 40t basándote en el Observatorio de Costes del MITMA, considerando gasóleo y personal."
];

export const GeneralConsultant: React.FC = () => {
  const [input, setInput] = useState('');
  const [showError, setShowError] = useState(false);
  const [copied, setCopied] = useState(false);
  const [exampleIndex, setExampleIndex] = useState(0);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
  });

  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      resultRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [state.content === '', state.error !== null]);

  const isValid = input.trim().length >= 10;

  const handleExampleClick = () => {
    const nextIndex = (exampleIndex + 1) % LOGISTICS_EXAMPLES.length;
    setInput(LOGISTICS_EXAMPLES[exampleIndex]);
    setExampleIndex(nextIndex);
    setShowError(false);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleConsult = async () => {
    if (!isValid) {
      setShowError(true);
      return;
    }

    setState({ isLoading: true, content: '', error: null });
    setShowError(false);

    try {
      const stream = generateLogisticsResponse(ToolType.CONSULTANT, input);
      let fullContent = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;

        try {
          // Attempt to extract explanation if it looks like JSON or just append
          const match = chunk.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/) || chunk.match(/"explanation":\s*"(.*)"/);
          if (match && match[1]) {
             fullContent += match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
          } else if (!chunk.includes('{')) {
             fullContent += chunk;
          }
        } catch (e) {
          fullContent += chunk;
        }

        setState(prev => ({
          ...prev,
          content: fullContent
        }));
      }

      if (isMounted.current) {
        setState(prev => ({ ...prev, isLoading: false }));
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message });
      }
    }
  };

  return (
    <section className="py-12 bg-slate-50 border-y border-slate-200" id="consultor">
      <div className="container mx-auto px-4">
        <div className="mb-8 text-center max-w-3xl mx-auto">
            <h2 className="text-3xl font-bold text-slate-900 mb-2 tracking-tight">Consultor Logístico Integral</h2>
            <p className="text-slate-600">
                Resuelve dudas técnicas sobre MF1012, MF1013 y Normativa ADR en tiempo real con IA avanzada.
            </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-col h-full">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-bold text-lg text-slate-800 flex items-center gap-2">
                      <Brain className="text-blue-600" size={24} />
                      <span>Pregunta al Experto</span>
                  </h3>
                  <button
                      onClick={handleExampleClick}
                      disabled={state.isLoading}
                      className="text-[10px] font-black uppercase tracking-widest text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg hover:bg-blue-100 transition-all flex items-center gap-1.5 disabled:opacity-50 group"
                      title="Ver otra sugerencia"
                  >
                      <Sparkles size={12} className="group-hover:rotate-12 transition-transform" /> 
                      <span>{input === '' ? 'Ver Ejemplo' : 'Sugerir otro'}</span>
                  </button>
                </div>

                <div className="relative">
                  <textarea 
                      value={input}
                      onChange={(e) => {
                        setInput(e.target.value);
                        if (e.target.value.trim().length >= 10) setShowError(false);
                      }}
                      disabled={state.isLoading}
                      className={`w-full p-4 border-2 rounded-xl bg-slate-50 text-sm min-h-[120px] focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all resize-none placeholder:text-slate-400 ${showError ? 'border-red-400 animate-shake' : 'border-slate-200'}`} 
                      placeholder="Ej: ¿Qué Incoterm usar para transporte marítimo? o ¿Qué paneles debe llevar un camión con explosivos?"
                  ></textarea>
                  {showError && (
                    <div className="absolute -bottom-5 left-1 text-[10px] font-bold text-red-500 uppercase flex items-center gap-1">
                      <AlertCircle size={10} /> La consulta debe tener al menos 10 caracteres
                    </div>
                  )}
                </div>

                <button 
                    onClick={handleConsult}
                    disabled={state.isLoading}
                    className="mt-6 w-full bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white py-3.5 rounded-xl font-bold flex items-center justify-center space-x-2 transition-all shadow-md active:scale-[0.99]"
                >
                    {state.isLoading ? (
                        <>
                            <Loader2 className="animate-spin" size={18} />
                            <span>Analizando normativa técnica...</span>
                        </>
                    ) : (
                        <>
                            <span>Consultar a Gemini</span>
                            <Send size={16} />
                        </>
                    )}
                </button>

                <div ref={resultRef} className="scroll-mt-24">
                  {(state.content || state.error) && (
                      <div 
                          className={`mt-6 rounded-xl overflow-hidden border transition-all duration-300 ${state.error ? 'bg-red-50 border-red-200 text-red-800' : 'bg-slate-50 border-blue-100 text-slate-800'}`}
                      >
                           <div className="bg-white/50 px-4 py-2 border-b border-inherit flex justify-between items-center">
                              <div className="flex items-center gap-2">
                                <Clock size={12} className="text-slate-400" />
                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Resultado de Consulta</span>
                              </div>
                              {state.content && !state.isLoading && (
                                <button onClick={handleCopy} className="text-slate-400 hover:text-blue-600 transition-colors">
                                  {copied ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
                                </button>
                              )}
                           </div>
                           <div className="p-5">
                             {state.error ? (
                                 <p className="font-semibold">{state.error}</p>
                             ) : (
                                 <div className="prose prose-sm prose-slate max-w-none">
                                    <div className="whitespace-pre-wrap font-medium leading-relaxed text-slate-800 break-words text-sm md:text-base">
                                        {state.content}
                                        {state.isLoading && <span className="inline-block w-1.5 h-4 ml-1 bg-blue-600 animate-pulse align-middle rounded-full"></span>}
                                    </div>
                                 </div>
                             )}
                           </div>
                      </div>
                  )}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100 flex flex-col justify-center items-center text-center transition-transform hover:scale-[1.02]">
                    <Radiation className="text-orange-600 mb-3" size={32} />
                    <span className="text-xs font-bold text-orange-800 uppercase tracking-wide">ADR Clases</span>
                    <span className="text-3xl font-black text-orange-900 mt-1">9</span>
                    <span className="text-xs text-orange-700/70 mt-1">Grupos Peligrosos</span>
                </div>
                <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 flex flex-col justify-center items-center text-center transition-transform hover:scale-[1.02]">
                    <Ship className="text-emerald-600 mb-3" size={32} />
                    <span className="text-xs font-bold text-emerald-800 uppercase tracking-wide">Incoterms</span>
                    <span className="text-3xl font-black text-emerald-900 mt-1">11</span>
                    <span className="text-xs text-emerald-700/70 mt-1">Reglas 2020</span>
                </div>
                <div className="bg-blue-50 p-6 rounded-2xl border border-blue-100 flex flex-col justify-center items-center text-center transition-transform hover:scale-[1.02]">
                    <FileText className="text-blue-600 mb-3" size={32} />
                    <span className="text-xs font-bold text-blue-800 uppercase tracking-wide">Doc. Internacional</span>
                    <span className="text-3xl font-black text-blue-900 mt-1">CMR</span>
                    <span className="text-xs text-blue-700/70 mt-1">Carta de Porte</span>
                </div>
                <div className="bg-purple-50 p-6 rounded-2xl border border-purple-100 flex flex-col justify-center items-center text-center transition-transform hover:scale-[1.02]">
                    <Gauge className="text-purple-600 mb-3" size={32} />
                    <span className="text-xs font-bold text-purple-800 uppercase tracking-wide">Tacógrafo</span>
                    <span className="text-3xl font-black text-purple-900 mt-1">DIG</span>
                    <span className="text-xs text-purple-700/70 mt-1">Digital Inteligente</span>
                </div>
            </div>
        </div>
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-shake {
          animation: shake 0.2s ease-in-out 0s 2;
        }
      `}</style>
    </section>
  );
};

