                    </div>
                    {!state.isLoading && isRoute && (
                      <button onClick={() => setIsSaving(true)} className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-brand-200 text-brand-700 rounded-lg text-[10px] font-bold hover:bg-brand-50 transition-all shadow-sm">
                        <Save size={12} /> Guardar
                      </button>
