                      <input value={routeName} onChange={(e) => setRouteName(e.target.value)} placeholder="Nombre de ruta..." className="flex-1 px-3 py-2 bg-slate-50 border rounded-lg text-xs outline-none focus:border-brand-500" />
                      <button onClick={handleSaveRoute} disabled={!routeName.trim()} className="px-3 py-2 bg-brand-600 text-white rounded-lg text-xs font-bold">OK</button>
                      <button onClick={() => setIsSaving(false)} className="px-3 py-2 bg-slate-100 text-slate-500 rounded-lg text-xs font-bold">X</button>
                    </div>
                  )}
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm md:text-base mb-6">
                          {state.content}
                          {state.isLoading && <span className={`inline-block w-1.5 h-4 ml-1 ${config.bgColor} animate-pulse align-middle rounded-full`}></span>}
                      </div>
                  </div>
                  {!state.isLoading && (
                    <div className="flex justify-end pt-2">
                        <button onClick={handleCopy} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all border ${copied ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-500 border-slate-200 hover:text-brand-600'}`}>
                            {copied ? <Check size={14} /> : <Copy size={14} />}
                            <span>{copied ? 'Copiado' : 'Copiar'}</span>
                        </button>
                    </div>
                  )}
               </div>
            </div>
          )}
