const createNumberedIcon = (number: number, isStart: boolean, isEnd: boolean) => {
  let bgClass = 'bg-brand-600 ring-4 ring-brand-100'; // Default Middle
  let borderClass = 'border-white';

  if (isStart) {
    bgClass = 'bg-emerald-500 ring-4 ring-emerald-100';
  } else if (isEnd) {
    bgClass = 'bg-red-500 ring-4 ring-red-100';
  }

  return L.divIcon({
    html: `
      <div class="relative flex items-center justify-center group">
        <div class="absolute w-9 h-9 ${bgClass} rounded-full border-2 ${borderClass} shadow-xl animate-in zoom-in duration-300 transition-transform group-hover:scale-110"></div>
        <span class="relative text-white font-black text-[12px]">${number}</span>
        ${isStart ? '<div class="absolute -top-1 -right-1 w-3 h-3 bg-emerald-300 rounded-full animate-ping"></div>' : ''}
      </div>
    `,
    className: 'custom-div-icon',
    iconSize: [36, 36],
    iconAnchor: [18, 18],
    popupAnchor: [0, -10]
  });
};

