          </div>
        ) : (
          <>
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[240px] relative rounded-2xl overflow-hidden border-2 transition-all ${showValidationErrors && !hasMinPoints && isInputEmpty ? 'border-red-400 shadow-[0_0_15px_rgba(239,68,68,0.2)] animate-shake' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={setPoints} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating'} 
                    />
                </div>
            )}
            <div className="flex justify-end mb-2">
                <button type="button" onClick={() => setInput(config.example)} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 uppercase tracking-wider group">
                    <Sparkles size={12} className="group-hover:animate-spin" /> Sugerir Ejemplo
                </button>
            </div>
            <div className="relative">
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                disabled={state.isLoading}
                rows={isRoute ? 3 : 5}
                className={`w-full p-4 border-2 rounded-xl bg-slate-50 text-sm focus:ring-2 focus:ring-brand-500 outline-none transition-all resize-none placeholder:text-slate-400 ${showValidationErrors && !hasDescription && (!isRoute || !hasMinPoints) ? 'border-red-500 animate-shake bg-red-50/20' : 'border-slate-100'}`}
                placeholder={config.placeholder}
              />
              {showValidationErrors && !hasDescription && (!isRoute || !hasMinPoints) && (
                <div className="absolute -bottom-5 left-1 flex items-center gap-1 text-[10px] font-bold text-red-600 uppercase tracking-widest animate-in fade-in slide-in-from-top-1">
                   <AlertCircle size={12} /> Este campo es obligatorio
                </div>
              )}
            </div>
            <div className="mt-8">
              <button
                onClick={handleGenerate}
                disabled={state.isLoading}
                className={`w-full ${config.buttonColor} text-white font-bold py-4 rounded-xl transition-all shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 active:scale-[0.98] ${showValidationErrors && !isInputValid ? 'animate-shake' : ''}`}
              >
                {state.isLoading ? <Loader2 className="animate-spin" size={20} /> : <Zap size={20} />}
                <span>{state.isLoading ? 'Procesando Inteligencia...' : 'Optimizar con IA'}</span>
              </button>
              {showValidationErrors && !isInputValid && (
                <p className="mt-4 text-[10px] font-bold text-red-500 text-center uppercase tracking-widest flex items-center justify-center gap-2 animate-in fade-in slide-in-from-top-2">
                  <AlertTriangle size={14} /> 
                  {isRoute ? 'Añade al menos 2 paradas o describe tu ruta' : 'Se requiere un supuesto técnico de al menos 5 caracteres'}
                </p>
              )}
            </div>
          </>
        )}

        <div ref={resultRef} className="scroll-mt-24">
          {state.content !== null && !showSavedList && (
            <div className={`mt-8 rounded-2xl border ${config.borderColor} overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500`}>
               <div className={`p-6 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-4 border-b border-slate-200/50 pb-3">
                    <div className="flex items-center gap-2">
                      <Clock size={14} className="text-slate-400" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Informe Generado</span>
                    </div>
                    {!state.isLoading && isRoute && !isSaving && (
                      <button 
                        onClick={() => setIsSaving(true)} 
                        className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-brand-200 text-brand-700 rounded-lg text-[10px] font-bold hover:bg-brand-50 transition-all shadow-sm"
                      >
                        <Save size={12} /> Guardar Informe
                      </button>
                    )}
                  </div>

                  {isSaving && (
                    <div className="mb-6 p-4 bg-white rounded-2xl border border-brand-200 animate-in zoom-in duration-200 shadow-inner">
                      <div className="flex items-center gap-2 mb-3 text-brand-700">
                        <Tag size={14} />
                        <label className="text-[10px] font-black uppercase tracking-widest">Título de la Ruta Guardada</label>
                      </div>
                      <div className="flex gap-2">
                        <input 
                          autoFocus
                          value={routeName} 
                          onChange={(e) => setRouteName(e.target.value)} 
                          placeholder="Ej: Reparto Martes Zona Norte" 
                          className="flex-1 px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500 transition-all shadow-sm" 
                        />
                        <button 
                          onClick={handleSaveRoute} 
                          disabled={!routeName.trim()} 
                          className="px-5 py-2.5 bg-brand-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-brand-700 disabled:opacity-50 transition-all shadow-md active:scale-95"
                        >
                          Confirmar
                        </button>
                        <button 
                          onClick={() => { setIsSaving(false); setRouteName(''); }} 
                          className="px-4 py-2.5 bg-slate-100 text-slate-500 rounded-xl text-xs font-bold hover:bg-slate-200 transition-all"
                        >
                          <X size={18} />
                        </button>
                      </div>
                    </div>
                  )}

                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm md:text-base mb-6">
                          {state.content}
                          {loadingStage === 'streaming' ? (
                            <Loader2 size={16} className="inline-block ml-2 animate-spin text-brand-500 align-text-bottom" />
                          ) : (
                            state.isLoading && <span className={`inline-block w-1.5 h-4 ml-1 ${config.bgColor} animate-pulse align-middle rounded-full`}></span>
                          )}
                      </div>
                  </div>
                  {!state.isLoading && (
                    <div className="flex justify-end pt-2">
                        <button onClick={() => { navigator.clipboard.writeText(state.content || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all border ${copied ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-500 border-slate-200 hover:text-brand-600'}`}>
                            {copied ? <Check size={14} /> : <Copy size={14} />}
                            <span>{copied ? 'Copiado' : 'Copiar'}</span>
                        </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Brain, Radiation, Ship, FileText, Gauge, Loader2, Send, AlertCircle, Sparkles, Clock, Copy, Check, RefreshCw, Lightbulb, Zap } from 'lucide-react';
import { generateLogisticsResponse } from '../services/geminiService';
import { ToolType, GeneratedContentState } from '../types';

const LOGISTICS_EXAMPLES = [
  "¿Cuáles son los requisitos específicos de señalización ADR para un vehículo que transporta Baterías de Litio (UN 3480) y qué paneles debe portar?",
  "Explica la diferencia de responsabilidades entre los Incoterms FOB y CIF según las reglas de 2020, específicamente en la transmisión del riesgo.",
  "¿Cómo se calculan los tiempos de conducción y descanso semanales según el Reglamento (CE) nº 561/2006 para un conductor de larga distancia?",
  "Redacta los puntos clave que debe contener una Carta de Porte CMR para que sea legalmente válida en un transporte internacional a Francia.",
  "Calcula el coste por kilómetro de un vehículo articulado de 40t basándote en el Observatorio de Costes del MITMA, considerando gasóleo y personal."
];

export const GeneralConsultant: React.FC = () => {
  const [input, setInput] = useState('');
  const [showError, setShowError] = useState(false);
  const [copied, setCopied] = useState(false);
  const [exampleIndex, setExampleIndex] = useState(0);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
  });

  const resultRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    return () => {
      isMounted.current = false;
    };
  }, []);

  // Auto-scroll to results area when starting to receive content or on error
  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      const timer = setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [state.content === '', state.error !== null]);

  const isValid = input.trim().length >= 10;

  const handleExampleClick = () => {
    const text = LOGISTICS_EXAMPLES[exampleIndex];
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 5);

    setExampleIndex((prev) => (prev + 1) % LOGISTICS_EXAMPLES.length);
    setShowError(false);
  };

  const handleCopy = () => {
    if (!state.content) return;
    navigator.clipboard.writeText(state.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleConsult = async () => {
    if (!isValid) {
      setShowError(true);
      textareaRef.current?.focus();
      return;
    }

    setState({ isLoading: true, content: '', error: null });
    setShowError(false);

    try {
      const stream = generateLogisticsResponse(ToolType.CONSULTANT, input);
      let fullContent = '';

      for await (const chunk of stream) {
        if (!isMounted.current) break;
        fullContent += chunk;

        setState(prev => ({
          ...prev,
          content: fullContent
        }));
      }

      if (isMounted.current) {
        setState(prev => ({ ...prev, isLoading: false }));
      }
    } catch (err: any) {
      if (isMounted.current) {
        setState({ isLoading: false, content: null, error: err.message });
      }
    }
  };

  return (
    <section className="py-12 bg-slate-50 border-y border-slate-200" id="consultor">
      <div className="container mx-auto px-4">
        <div className="mb-10 text-center max-w-3xl mx-auto">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-blue-50 text-blue-700 text-[10px] font-black uppercase tracking-widest mb-4 border border-blue-100">
                <Zap size={12} className="fill-blue-700" /> Knowledge Base Expert
            </div>
            <h2 className="text-3xl md:text-4xl font-bold text-slate-900 mb-3 tracking-tight">Consultor Logístico Integral</h2>
            <p className="text-slate-600 text-lg">
                Resuelve dudas técnicas sobre MF1012, MF1013 y Normativa ADR en tiempo real.
            </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-8 max-w-6xl mx-auto">
            <div className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 flex flex-col h-full relative overflow-hidden group/card">
                <div className="absolute top-0 right-0 w-32 h-32 bg-blue-50 rounded-full -mr-16 -mt-16 transition-transform duration-700 group-hover/card:scale-110"></div>

                <div className="relative flex items-center justify-between mb-6">
                  <h3 className="font-black text-xl text-slate-900 flex items-center gap-3">
                      <div className="bg-blue-600 p-2 rounded-xl text-white shadow-lg shadow-blue-200">
                        <Brain size={24} />
                      </div>
                      <span>Consulta Técnica</span>
                  </h3>

                  <button
                      onClick={handleExampleClick}
                      disabled={state.isLoading}
                      className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-700 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-100 transition-all active:scale-95 disabled:opacity-50 border border-blue-100 group"
                  >
                      <Lightbulb size={14} className="group-hover:text-amber-500 transition-colors" />
                      <span>Ver Ejemplo</span>
                  </button>
                </div>

                <div className="relative mb-6">
                  <textarea 
                      ref={textareaRef}
                      value={input}
                      onChange={(e) => {
                        setInput(e.target.value);
                        if (e.target.value.trim().length >= 10) setShowError(false);
                      }}
                      disabled={state.isLoading}
                      aria-invalid={showError}
                      className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm min-h-[160px] focus:ring-4 focus:ring-blue-100 focus:border-blue-500 outline-none transition-all resize-none placeholder:text-slate-400 shadow-inner ${showError ? 'border-red-400 animate-shake bg-red-50/30' : 'border-slate-100'}`} 
                      placeholder="Describe tu consulta técnica aquí (normativa, operativa, ADR...)"
                  ></textarea>
                  {showError && (
                    <div className="absolute -bottom-6 left-1 text-[11px] font-bold text-red-500 uppercase flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                      <AlertCircle size={14} /> 
                      <span>La consulta debe tener al menos 10 caracteres</span>
                    </div>
                  )}
                </div>

                <button 
                    onClick={handleConsult}
                    disabled={state.isLoading}
                    className="w-full bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white py-4 rounded-2xl font-black uppercase tracking-widest flex items-center justify-center space-x-3 transition-all shadow-xl active:scale-[0.98] group"
                >
                    {state.isLoading ? (
                        <>
                            <Loader2 className="animate-spin" size={20} />
                            <span>Analizando Consulta...</span>
                        </>
                    ) : (
                        <>
                            <span>Enviar Consulta Técnica</span>
                            <Send size={18} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                        </>
                    )}
                </button>

                <div ref={resultRef} className="scroll-mt-24">
                  {(state.content || state.error) && (
                      <div 
                          className={`mt-8 rounded-2xl overflow-hidden border animate-in fade-in slide-in-from-bottom-4 duration-500 transition-all ${state.error ? 'bg-red-50 border-red-200 text-red-800' : 'bg-slate-50 border-blue-100 text-slate-800 shadow-sm'}`}
                      >
                           <div className="bg-white/60 backdrop-blur-sm px-5 py-3 border-b border-inherit flex justify-between items-center">
                              <div className="flex items-center gap-2">
                                <Sparkles size={14} className="text-blue-600" />
                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">IA Insights</span>
                              </div>
                              {state.content && !state.isLoading && (
                                <button 
                                  onClick={handleCopy} 
                                  className={`flex items-center gap-1.5 px-2 py-1 rounded-lg transition-all ${copied ? 'text-emerald-600 bg-emerald-50' : 'text-slate-400 hover:text-blue-600 hover:bg-blue-50'}`}
                                >
                                  {copied ? <Check size={14} /> : <Copy size={14} />}
                                  <span className="text-[9px] font-bold uppercase">{copied ? 'Copiado' : 'Copiar'}</span>
                                </button>
                              )}
                           </div>
                           <div className="p-6">
                             {state.error ? (
                                 <div className="flex items-start gap-3">
                                   <AlertCircle className="shrink-0 text-red-500" size={20} />
                                   <p className="font-bold text-sm leading-relaxed">{state.error}</p>
                                 </div>
                             ) : (
                                 <div className="prose prose-sm prose-slate max-w-none">
                                    <div className="whitespace-pre-wrap font-medium leading-relaxed text-slate-800 break-words text-sm md:text-base">
                                        {state.content}
                                        {state.isLoading && <span className="inline-block w-1.5 h-4 ml-1 bg-blue-600 animate-pulse align-middle rounded-full"></span>}
                                    </div>
                                 </div>
                             )}
                           </div>
                      </div>
                  )}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                {[
                  { icon: <Radiation size={32} />, label: "ADR Clases", value: "9", sub: "Riesgos", color: "orange" },
                  { icon: <Ship size={32} />, label: "Incoterms", value: "11", sub: "Reglas", color: "emerald" },
                  { icon: <FileText size={32} />, label: "CMR", value: "INT", sub: "Porte", color: "blue" },
                  { icon: <Gauge size={32} />, label: "Tacógrafo", value: "DIG", sub: "Smart", color: "purple" }
                ].map((stat, idx) => (
                  <div key={idx} className={`bg-white p-6 rounded-3xl border border-slate-100 flex flex-col justify-center items-center text-center transition-all hover:shadow-lg hover:-translate-y-1 group relative overflow-hidden`}>
                    <div className="text-slate-600 mb-4 p-4 rounded-2xl group-hover:scale-110 transition-transform">
                      {stat.icon}
                    </div>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</span>
                    <span className="text-3xl font-black text-slate-900 mt-1">{stat.value}</span>
