import React, { useEffect, useState, useMemo, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, useMap } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, Search, Navigation, Loader2, Maximize2, Minimize2, Check, Activity, Warehouse, Building2, Factory, MapPin, List, Flag, Goal } from 'lucide-react';

// Fix for default marker icons
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
  externalCenter?: [number, number];
  onAddCurrentLocation?: () => void;
  isLocating?: boolean;
}

const createNumberedIcon = (number: number, isStart: boolean, isEnd: boolean) => {
  let bgClass = 'bg-brand-600 ring-4 ring-brand-100';
  if (isStart) bgClass = 'bg-emerald-500 ring-4 ring-emerald-100';
  else if (isEnd) bgClass = 'bg-red-500 ring-4 ring-red-100';

  return L.divIcon({
    html: `<div class="relative flex items-center justify-center group z-50">
        <div class="absolute w-10 h-10 ${bgClass} rounded-full border-2 border-white shadow-2xl transition-transform group-hover:scale-110"></div>
        <span class="relative text-white font-black text-[13px] drop-shadow-md">${number}</span>
      </div>`,
    className: 'custom-div-icon',
    iconSize: [40, 40],
    iconAnchor: [20, 20],
    popupAnchor: [0, -10]
  });
};

const createInactiveIcon = () => {
  return L.divIcon({
    html: `<div class="opacity-40 grayscale"><img src="https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png" class="w-6 h-10" /></div>`,
    className: 'custom-div-icon',
    iconSize: [25, 41],
    iconAnchor: [12, 41],
  });
};

// Controlador interno del mapa para manejar re-centrado y ajustes de tamaño
const MapController = ({ 
  centerOn, 
  routePath, 
  onAdd,
  searchQuery // Recibimos el query actual para validar el clic
}: { 
  centerOn?: [number, number], 
  routePath?: [number, number][],
  onAdd: (lat: number, lng: number, label?: string) => void,
  searchQuery: string
}) => {
  const map = useMap();

  useEffect(() => {
    if (centerOn) {
      map.setView(centerOn, 16, { animate: true });
      // Importante para móviles: refresca el cálculo del tamaño del mapa
      setTimeout(() => map.invalidateSize(), 100);
    }
  }, [centerOn, map]);

  useEffect(() => {
    if (routePath && routePath.length > 1) {
      const bounds = L.latLngBounds(routePath);
      map.fitBounds(bounds, { padding: [60, 60], maxZoom: 16, animate: true });
    }
  }, [routePath, map]);

  useMapEvents({
    click(e) {
      // Nueva lógica: requerir texto en el buscador para añadir punto por clic manual
      if (!searchQuery.trim()) {
        alert("⚠️ Por favor, introduce primero un nombre o dirección en el buscador para etiquetar este punto en el mapa, o utiliza el botón 'Ubicación Actual'.");
        return;
      }
      onAdd(e.latlng.lat, e.latlng.lng, searchQuery);
    },
  });

  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter, onAddCurrentLocation, isLocating }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [mapActivity, setMapActivity] = useState<string | null>(null);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);

  const toggleFullScreen = () => {
    setIsFullScreen(!isFullScreen);
    if (!isFullScreen) {
      document.body.classList.add('no-scroll');
    } else {
      document.body.classList.remove('no-scroll');
    }
  };

  // Reacciona a cambios externos de posición (GPS, Búsqueda, etc.)
  useEffect(() => {
    if (externalCenter) {
      setCenterOn([...externalCenter]); // Clonar array para asegurar trigger
    }
  }, [externalCenter]);

  const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    setMapActivity("Identificando...");
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`);
      const data = await resp.json();
      return data.display_name.split(',').slice(0, 2).join(',') || `Punto ${points.length + 1}`;
    } catch { 
      return `Punto ${points.length + 1}`; 
    } finally { 
      setMapActivity(null); 
    }
  };

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || await reverseGeocode(lat, lng);
    onPointsChange([...points, { lat, lng, id: Math.random().toString(36).substr(2, 9), label: finalLabel }]);
    // Si se añadió por clic usando el query, limpiamos el query para la siguiente acción
    if (label) setSearchQuery('');
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const newCenter: [number, number] = [parseFloat(lat), parseFloat(lon)];
        setCenterOn(newCenter);
        handleAddPoint(newCenter[0], newCenter[1], display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) {
      console.error("Error en búsqueda:", err);
    } finally { 
      setIsSearching(false); 
    }
  };

  const routePath = useMemo(() => {
    if (routeSequence && routeSequence.length > 0) {
      return routeSequence.filter(idx => points[idx]).map(idx => [points[idx].lat, points[idx].lng] as [number, number]);
    }
    return [];
  }, [routeSequence, points]);

  const hasActiveRoute = routeSequence && routeSequence.length > 0;

  return (
    <div className={`flex flex-col gap-4 transition-all duration-500 ${isFullScreen ? 'fixed inset-0 z-[60] bg-slate-900 p-0 sm:p-4' : ''}`}>
      {!isFullScreen && (
        <div className="flex flex-col md:flex-row gap-3">
            <form onSubmit={handleSearch} className="relative flex-1 flex gap-2">
              <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                      type="text" 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder="Escribe un nombre y pincha en el mapa..."
                      className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none"
                  />
              </div>
              <button type="submit" disabled={isSearching} className="bg-brand-600 text-white px-4 rounded-xl font-bold shadow-sm active:scale-95 transition-all">
                  {isSearching ? <Loader2 size={18} className="animate-spin" /> : 'Añadir'}
              </button>
            </form>
            <button 
              onClick={(e) => {
                e.preventDefault();
                onAddCurrentLocation?.();
              }} 
              disabled={isLocating} 
              className={`px-4 py-3 rounded-xl font-bold flex items-center justify-center gap-2 border transition-all active:scale-95 shadow-sm ${isLocating ? 'bg-slate-100 text-slate-400' : 'bg-emerald-50 text-emerald-700 border-emerald-100 hover:bg-emerald-100'}`}
            >
                {isLocating ? <Loader2 size={16} className="animate-spin" /> : <Navigation size={18} />}
                <span className="text-xs">{isLocating ? 'Localizando...' : 'Ubicación Actual'}</span>
            </button>
        </div>
      )}

      <div className={`relative transition-all duration-500 overflow-hidden border border-slate-200 shadow-2xl ${isFullScreen ? 'h-full w-full rounded-none' : 'h-[450px] w-full rounded-2xl'}`}>
        <MapContainer center={[40.4168, -3.7038]} zoom={13} zoomControl={false} style={{ height: '100%', width: '100%' }}>
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <MapController centerOn={centerOn} routePath={routePath} onAdd={handleAddPoint} searchQuery={searchQuery} />

          {points.map((point, index) => {
            const routePos = routeSequence?.indexOf(index);
            const isInRoute = routePos !== undefined && routePos !== -1;
            const markerIcon = isInRoute 
              ? createNumberedIcon(routePos! + 1, routePos === 0, routePos === (routeSequence!.length - 1))
              : hasActiveRoute ? createInactiveIcon() : undefined;

            return (
              <Marker key={point.id} position={[point.lat, point.lng]} icon={markerIcon}>
                <Popup className="custom-popup" closeButton={false}>
                  <div className="p-3 bg-white rounded-lg">
                    <p className="font-bold text-xs mb-2">{point.label}</p>
                    <button onClick={() => onPointsChange(points.filter(p => p.id !== point.id))} className="w-full text-[10px] font-bold text-red-500 bg-red-50 py-1 rounded">Eliminar</button>
                  </div>
                </Popup>
              </Marker>
            );
          })}

          {routePath.length > 1 && <Polyline positions={routePath} pathOptions={{ color: '#2563eb', weight: 5, opacity: 0.8 }} />}
        </MapContainer>

        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2">
            <button 
              onClick={(e) => { e.preventDefault(); onAddCurrentLocation?.(); }}
              disabled={isLocating}
              className="bg-white p-3 rounded-full shadow-xl border border-slate-200 text-slate-700 hover:text-emerald-600 active:scale-90 transition-all disabled:opacity-50"
              title="Añadir Ubicación Actual"
            >
                {isLocating ? <Loader2 size={24} className="animate-spin text-emerald-500" /> : <Navigation size={24} />}
            </button>
            <button onClick={toggleFullScreen} className="bg-white p-3 rounded-full shadow-xl border border-slate-200 text-slate-700 hover:text-brand-600 active:scale-90 transition-all">
                {isFullScreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
            </button>
        </div>

        {isFullScreen && (
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[1000] flex gap-2">
            <button onClick={toggleFullScreen} className="bg-slate-900 text-white px-6 py-3 rounded-full font-bold shadow-2xl border border-white/20 flex items-center gap-2 active:scale-95">
               <Minimize2 size={18} /> Salir del Mapa
            </button>
          </div>
        )}

        {mapActivity && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[1000] bg-slate-900/90 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 backdrop-blur-md">
            <Loader2 size={12} className="animate-spin text-brand-400" /> {mapActivity}
          </div>
        )}
      </div>

      {!isFullScreen && points.length > 0 && (
        <div className="bg-white border border-slate-200 rounded-2xl p-4 shadow-sm overflow-x-auto whitespace-nowrap custom-scrollbar">
            <div className="flex gap-3">
                {points.map((p, i) => (
                    <div key={p.id} className="inline-flex items-center gap-2 bg-slate-50 px-3 py-2 rounded-xl border border-slate-100 min-w-[140px]">
                        <div className="w-6 h-6 rounded-lg bg-brand-600 text-white text-[10px] font-black flex items-center justify-center shrink-0">
                            {routeSequence?.includes(i) ? routeSequence.indexOf(i) + 1 : i + 1}
                        </div>
                        <span className="text-[10px] font-bold text-slate-700 truncate max-w-[100px]">{p.label}</span>
                    </div>
                ))}
            </div>
        </div>
      )}
      <style>{`
        .custom-popup .leaflet-popup-content-wrapper { border-radius: 12px; padding: 0; overflow: hidden; }
        .custom-popup .leaflet-popup-content { margin: 0; }
        .custom-div-icon { background: none; border: none; }
        .custom-scrollbar::-webkit-scrollbar { height: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter, SortAsc, LayoutGrid, List, Activity, ExternalLink, Tag, SortDesc } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'preparing' | 'geocoding' | 'connecting' | 'streaming' | 'finalizing' | 'locating';
type SortOption = 'date' | 'name';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  // States for Saved Routes
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showSavedList, setShowSavedList] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const isRoute = type === ToolType.ROUTE;

  const hasDescription = input.trim().length >= 5;
  const isInputEmpty = input.trim().length === 0;
  const hasMinPoints = points.length >= 2;

  const isInputValid = isRoute 
    ? (hasMinPoints || hasDescription) 
    : hasDescription;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try {
          setSavedRoutes(JSON.parse(stored));
        } catch (e) {
          console.error("Error loading saved routes", e);
        }
      }
    }
    return () => {
      isMounted.current = false;
    };
  }, [type]);

  useEffect(() => {
    if (isInputValid && showValidationErrors) {
      setShowValidationErrors(false);
    }
  }, [isInputValid, showValidationErrors]);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      const timer = setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [state.content === '', state.error !== null]);

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu navegador no soporta geolocalización.");
      return;
    }

    setLoadingStage('locating');
    const geoOptions = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Ubicación detectada";
          const startPoint: MapPoint = { lat: latitude, lng: longitude, id: 'loc-' + Date.now(), label: `📍 Mi Posición: ${address}` };
          setPoints(prev => [startPoint, ...prev]);
          setExternalCenter([...[latitude, longitude]]);
        } catch (err) {
          setPoints(prev => [{ lat: latitude, lng: longitude, id: 'loc-' + Date.now(), label: "📍 Ubicación GPS" }, ...prev]);
          setExternalCenter([...[latitude, longitude]]);
        } finally { setLoadingStage('idle'); }
      },
      (error) => {
        setLoadingStage('idle');
        alert("No se pudo obtener tu ubicación.");
      },
      geoOptions
    );
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;
    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };
    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({ isLoading: false, content: route.explanation, error: null, routeData: route.routeData });
    setShowSavedList(false);
    if (route.points.length > 0) {
      setExternalCenter([...[route.points[0].lat, route.points[0].lng]]);
    }
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Estás seguro de que quieres eliminar esta ruta permanentemente?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => 
      r.name.toLowerCase().includes(searchQuery.toLowerCase())
    );
    return filtered.sort((a, b) => {
      if (sortBy === 'date') return b.timestamp - a.timestamp;
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      return 0;
    });
  }, [savedRoutes, searchQuery, sortBy]);

  const handleGenerate = async () => {
    if (!isInputValid) { setShowValidationErrors(true); textareaRef.current?.focus(); return; }
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        setLoadingStage('streaming');
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }
      if (isMounted.current && isRoute) {
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { setState(prev => ({ ...prev, isLoading: false })); }
      } else { setState(prev => ({ ...prev, isLoading: false })); }
      setLoadingStage('idle');
    } catch (err: any) { setState({ isLoading: false, content: null, error: err.message }); setLoadingStage('idle'); }
  };

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    example: isRoute ? "Optimiza esta ruta de 5 paradas en el área metropolitana para entrega prioritaria." : "Redacta una cláusula de limitación de responsabilidad según CMR."
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>
          {isRoute && (
            <button 
              onClick={() => setShowSavedList(!showSavedList)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold border transition-all ${showSavedList ? 'bg-brand-600 text-white border-brand-600' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50 shadow-sm'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">Biblioteca ({savedRoutes.length})</span>
            </button>
          )}
        </div>

        {isRoute && showSavedList ? (
          <div className="mb-6 animate-in slide-in-from-top-4 duration-300 flex-1 flex flex-col min-h-[400px]">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-5 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} /> Rutas Guardadas
                  </h4>
                  <button onClick={() => setShowSavedList(false)} className="text-[10px] font-black text-brand-600 hover:text-brand-800 uppercase flex items-center gap-1">
                    <X size={12} /> Volver
                  </button>
                </div>

                <div className="flex flex-col sm:flex-row gap-3 mb-4">
                  <div className="relative flex-1">
                    <Search className={`absolute left-3 top-1/2 -translate-y-1/2 transition-colors ${searchQuery ? 'text-brand-500' : 'text-slate-400'}`} size={16} />
                    <input 
                      type="text"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder="Filtrar por nombre..."
                      className="w-full pl-10 pr-10 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm placeholder:text-slate-400 transition-all"
                    />
                    {searchQuery && (
                      <button 
                        onClick={() => setSearchQuery('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
                      >
                        <X size={14} />
                      </button>
                    )}
                  </div>
                  <div className="flex items-center gap-1 bg-white p-1 border border-slate-200 rounded-xl shadow-sm">
                    <button 
                      onClick={() => setSortBy('date')} 
                      className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'date' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}
                      title="Ordenar por fecha"
                    >
                      <Clock size={12} className="inline mr-1" /> Fecha
                    </button>
                    <button 
                      onClick={() => setSortBy('name')} 
                      className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'name' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}
                      title="Ordenar por nombre"
                    >
                      <SortAsc size={12} className="inline mr-1" /> Nombre
                    </button>
                  </div>
                </div>

                {processedRoutes.length === 0 ? (
                  <div className="flex flex-col items-center justify-center flex-1 text-center py-12 bg-white/50 rounded-2xl border border-dashed border-slate-200">
                    <div className="p-4 bg-slate-100 rounded-full mb-3">
                      <Search size={32} className="text-slate-300" />
                    </div>
                    <p className="text-sm font-bold text-slate-500">
                      {searchQuery ? 'No se encontraron resultados' : 'Biblioteca vacía'}
                    </p>
                    <p className="text-xs text-slate-400 mt-1">
                      {searchQuery ? 'Prueba con otros términos de búsqueda' : 'Guarda una ruta optimizada para verla aquí'}
                    </p>
                  </div>
                ) : (
                  <>
                    <div className="flex justify-between items-center mb-2 px-1">
                      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">
                        Mostrando {processedRoutes.length} de {savedRoutes.length} rutas
                      </span>
                    </div>
                    <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                      {processedRoutes.map((route) => (
                        <div 
                          key={route.id} 
                          className="group bg-white p-4 rounded-xl border border-slate-200 flex items-center justify-between hover:border-brand-300 hover:shadow-lg hover:shadow-brand-500/5 transition-all animate-in fade-in zoom-in-95 duration-200"
                        >
                          <div className="flex-1 min-w-0 pr-4">
                            <p className="text-sm font-bold text-slate-800 truncate group-hover:text-brand-700 transition-colors">{route.name}</p>
                            <div className="flex items-center gap-3 mt-1.5">
                              <span className="flex items-center gap-1 text-[9px] font-bold text-slate-400 uppercase">
                                <Clock size={10} /> {new Date(route.timestamp).toLocaleDateString()}
                              </span>
                              <span className="text-[9px] font-bold text-brand-600 bg-brand-50 px-2 py-0.5 rounded-full uppercase flex items-center gap-1">
                                <MapPin size={10} /> {route.points.length} paradas
                              </span>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <button 
                              onClick={(e) => deleteSavedRoute(route.id, e)}
                              className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                              title="Eliminar ruta"
                            >
                              <Trash2 size={16} />
                            </button>
                            <button 
                              onClick={() => loadSavedRoute(route)}
                              className="px-4 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-brand-700 transition-all flex items-center gap-2 shadow-md active:scale-95"
                            >
                              <PlayCircle size={14} /> Cargar Ruta
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </>
                )}
             </div>
          </div>
        ) : (
          <>
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[240px] relative rounded-2xl overflow-hidden border-2 transition-all ${showValidationErrors && !hasMinPoints && isInputEmpty ? 'border-red-400 shadow-[0_0_15px_rgba(239,68,68,0.2)] animate-shake' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={setPoints} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating'} 
                    />
                </div>
            )}
            <div className="flex justify-end mb-2">
                <button type="button" onClick={() => setInput(config.example)} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 uppercase tracking-wider group">
                    <Sparkles size={12} className="group-hover:animate-spin" /> Sugerir Ejemplo
                </button>
            </div>
            <div className="relative">
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                disabled={state.isLoading}
                rows={isRoute ? 3 : 5}
                className={`w-full p-4 border-2 rounded-xl bg-slate-50 text-sm focus:ring-2 focus:ring-brand-500 outline-none transition-all resize-none placeholder:text-slate-400 ${showValidationErrors && !hasDescription && (!isRoute || !hasMinPoints) ? 'border-red-500 animate-shake bg-red-50/20' : 'border-slate-100'}`}
                placeholder={config.placeholder}
              />
              {showValidationErrors && !hasDescription && (!isRoute || !hasMinPoints) && (
                <div className="absolute -bottom-5 left-1 flex items-center gap-1 text-[10px] font-bold text-red-600 uppercase tracking-widest animate-in fade-in slide-in-from-top-1">
                   <AlertCircle size={12} /> Este campo es obligatorio
                </div>
              )}
            </div>
            <div className="mt-8">
              <button
                onClick={handleGenerate}
                disabled={state.isLoading}
                className={`w-full ${config.buttonColor} text-white font-bold py-4 rounded-xl transition-all shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 active:scale-[0.98] ${showValidationErrors && !isInputValid ? 'animate-shake' : ''}`}
              >
                {state.isLoading ? <Loader2 className="animate-spin" size={20} /> : <Zap size={20} />}
                <span>{state.isLoading ? 'Procesando Inteligencia...' : 'Optimizar con IA'}</span>
              </button>
              {showValidationErrors && !isInputValid && (
                <p className="mt-4 text-[10px] font-bold text-red-500 text-center uppercase tracking-widest flex items-center justify-center gap-2 animate-in fade-in slide-in-from-top-2">
                  <AlertTriangle size={14} /> 
                  {isRoute ? 'Añade al menos 2 paradas o describe tu ruta' : 'Se requiere un supuesto técnico de al menos 5 caracteres'}
                </p>
              )}
            </div>
          </>
        )}

        <div ref={resultRef} className="scroll-mt-24">
          {state.content !== null && !showSavedList && (
            <div className={`mt-8 rounded-2xl border ${config.borderColor} overflow-hidden shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500`}>
               <div className={`p-6 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-4 border-b border-slate-200/50 pb-3">
                    <div className="flex items-center gap-2">
                      <Clock size={14} className="text-slate-400" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Informe Generado</span>
                    </div>
                    {!state.isLoading && isRoute && !isSaving && (
                      <button 
                        onClick={() => setIsSaving(true)} 
                        className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-brand-200 text-brand-700 rounded-lg text-[10px] font-bold hover:bg-brand-50 transition-all shadow-sm"
                      >
                        <Save size={12} /> Guardar Informe
                      </button>
                    )}
                  </div>

                  {isSaving && (
                    <div className="mb-6 p-4 bg-white rounded-2xl border border-brand-200 animate-in zoom-in duration-200 shadow-inner">
                      <div className="flex items-center gap-2 mb-3 text-brand-700">
                        <Tag size={14} />
                        <label className="text-[10px] font-black uppercase tracking-widest">Título de la Ruta Guardada</label>
                      </div>
                      <div className="flex gap-2">
                        <input 
                          autoFocus
                          value={routeName} 
                          onChange={(e) => setRouteName(e.target.value)} 
                          placeholder="Ej: Reparto Martes Zona Norte" 
                          className="flex-1 px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 focus:border-brand-500 transition-all shadow-sm" 
                        />
                        <button 
                          onClick={handleSaveRoute} 
                          disabled={!routeName.trim()} 
                          className="px-5 py-2.5 bg-brand-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-brand-700 disabled:opacity-50 transition-all shadow-md active:scale-95"
                        >
                          Confirmar
                        </button>
                        <button 
                          onClick={() => { setIsSaving(false); setRouteName(''); }} 
                          className="px-4 py-2.5 bg-slate-100 text-slate-500 rounded-xl text-xs font-bold hover:bg-slate-200 transition-all"
                        >
                          <X size={18} />
                        </button>
                      </div>
                    </div>
                  )}

                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm md:text-base mb-6">
                          {state.content}
                          {loadingStage === 'streaming' ? (
                            <Loader2 size={16} className="inline-block ml-2 animate-spin text-brand-500 align-text-bottom" />
                          ) : (
                            state.isLoading && <span className={`inline-block w-1.5 h-4 ml-1 ${config.bgColor} animate-pulse align-middle rounded-full`}></span>
                          )}
                      </div>
                  </div>
                  {!state.isLoading && (
                    <div className="flex justify-end pt-2">
                        <button onClick={() => { navigator.clipboard.writeText(state.content || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all border ${copied ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-500 border-slate-200 hover:text-brand-600'}`}>
                            {copied ? <Check size={14} /> : <Copy size={14} />}
                            <span>{copied ? 'Copiado' : 'Copiar'}</span>
                        </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter, SortAsc, LayoutGrid, List, Activity, ExternalLink, Tag, SortDesc } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'preparing' | 'geocoding' | 'connecting' | 'streaming' | 'finalizing' | 'locating';
type SortOption = 'date' | 'name';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [showSavedList, setShowSavedList] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const isRoute = type === ToolType.ROUTE;
  const isInputValid = isRoute ? (points.length >= 2 || input.trim().length >= 5) : input.trim().length >= 5;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  useEffect(() => {
    if ((state.content !== null || state.error !== null) && resultRef.current) {
      const timer = setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [state.content === '', state.error !== null]);

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu navegador no soporta geolocalización.");
      return;
    }

    setLoadingStage('locating');

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Ubicación detectada";
          const startPoint: MapPoint = { 
            lat: latitude, 
            lng: longitude, 
            id: 'loc-' + Date.now(), 
            label: `📍 Mi Posición: ${address}` 
          };
          setPoints(prev => [startPoint, ...prev]);
          // Forzamos el centro del mapa a la nueva posición
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          setPoints(prev => [{ lat: latitude, lng: longitude, id: 'loc-' + Date.now(), label: "📍 Ubicación GPS" }, ...prev]);
          setExternalCenter([latitude, longitude]);
        } finally { setLoadingStage('idle'); }
      },
      (error) => {
        setLoadingStage('idle');
        alert("Error al obtener ubicación: " + error.message);
      },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
    );
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;
    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };
    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({ isLoading: false, content: route.explanation, error: null, routeData: route.routeData });
    setShowSavedList(false);
    if (route.points.length > 0) setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Eliminar ruta permanentemente?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => r.name.toLowerCase().includes(searchQuery.toLowerCase()));
    return filtered.sort((a, b) => sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name));
  }, [savedRoutes, searchQuery, sortBy]);

  const handleGenerate = async () => {
    if (!isInputValid) { setShowValidationErrors(true); textareaRef.current?.focus(); return; }
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        setLoadingStage('streaming');
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }
      if (isMounted.current && isRoute) {
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { setState(prev => ({ ...prev, isLoading: false })); }
      } else { setState(prev => ({ ...prev, isLoading: false })); }
      setLoadingStage('idle');
    } catch (err: any) { setState({ isLoading: false, content: null, error: err.message }); setLoadingStage('idle'); }
  };

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    example: isRoute ? "Optimiza esta ruta de 5 paradas en el área metropolitana para entrega prioritaria." : "Redacta una cláusula de limitación de responsabilidad según CMR."
  };

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>
          {isRoute && (
            <button 
              onClick={() => setShowSavedList(!showSavedList)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold border transition-all ${showSavedList ? 'bg-brand-600 text-white border-brand-600' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50 shadow-sm'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">Biblioteca ({savedRoutes.length})</span>
            </button>
          )}
        </div>

        {isRoute && showSavedList ? (
          <div className="mb-6 animate-in slide-in-from-top-4 duration-300 flex-1 flex flex-col min-h-[400px]">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-5 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} /> Rutas Guardadas
                  </h4>
                  <button onClick={() => setShowSavedList(false)} className="text-[10px] font-black text-brand-600 hover:text-brand-800 uppercase flex items-center gap-1">
                    <X size={12} /> Volver
                  </button>
                </div>

                <div className="flex flex-col sm:flex-row gap-3 mb-4">
                  <div className="relative flex-1">
                    <Search className={`absolute left-3 top-1/2 -translate-y-1/2 transition-colors ${searchQuery ? 'text-brand-500' : 'text-slate-400'}`} size={16} />
                    <input 
                      type="text"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder="Filtrar por nombre..."
                      className="w-full pl-10 pr-10 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm placeholder:text-slate-400 transition-all"
                    />
                    {searchQuery && (
                      <button 
                        onClick={() => setSearchQuery('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
                      >
                        <X size={14} />
                      </button>
                    )}
                  </div>
                  <div className="flex items-center gap-1 bg-white p-1 border border-slate-200 rounded-xl shadow-sm">
                    <button 
                      onClick={() => setSortBy('date')} 
                      className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'date' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}
                    >
                      <Clock size={12} className="inline mr-1" /> Fecha
                    </button>
                    <button 
                      onClick={() => setSortBy('name')} 
                      className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'name' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}
                    >
                      <SortAsc size={12} className="inline mr-1" /> Nombre
                    </button>
                  </div>
                </div>

                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.map((route) => (
                    <div 
                      key={route.id} 
                      className="group bg-white p-4 rounded-xl border border-slate-200 flex items-center justify-between hover:border-brand-300 hover:shadow-lg transition-all animate-in fade-in zoom-in-95 duration-200"
                    >
                      <div className="flex-1 min-w-0 pr-4">
                        <p className="text-sm font-bold text-slate-800 truncate group-hover:text-brand-700 transition-colors">{route.name}</p>
