                    Este programa otorga el Certificado de Profesionalidad de Nivel 3 en Organización del Transporte y la Logística, reconocido en todo el Espacio Europeo.
                 </p>
                 <div className="mt-6 flex gap-2">
                    <div className="w-8 h-8 rounded-lg bg-emerald-100 text-emerald-600 flex items-center justify-center"><CheckCircle2 size={16} /></div>
                    <div className="w-8 h-8 rounded-lg bg-emerald-100 text-emerald-600 flex items-center justify-center"><CheckCircle2 size={16} /></div>
                    <div className="w-8 h-8 rounded-lg bg-emerald-100 text-emerald-600 flex items-center justify-center"><CheckCircle2 size={16} /></div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* Career Tab View */}
        {activeTab === 'career' && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
             <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                  { title: 'Gestor de Tráfico', role: 'Planificación de rutas y flotas en tiempo real.', color: 'brand' },
                  { title: 'Técnico ADR', role: 'Supervisión de mercancías peligrosas y seguridad.', color: 'orange' },
                  { title: 'Jefe de Almacén', role: 'Coordinación de flujos de entrada y logística inversa.', color: 'emerald' },
                  { title: 'Consultor Logístico', role: 'Auditoría de costes y procesos de transporte.', color: 'purple' }
                ].map((item, i) => (
                  <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm hover:border-brand-300 transition-all group">
                     <div className={`w-12 h-12 rounded-xl mb-6 bg-slate-50 flex items-center justify-center text-slate-400 group-hover:bg-brand-50 group-hover:text-brand-600 transition-all`}>
                        <Briefcase size={20} />
                     </div>
                     <h4 className="font-black text-slate-900 mb-3">{item.title}</h4>
                     <p className="text-slate-500 text-xs leading-relaxed">{item.role}</p>
                  </div>
                ))}
             </div>

             <div className="mt-12 p-8 bg-brand-50 rounded-[2.5rem] border border-brand-100 flex flex-col md:flex-row items-center gap-8 shadow-sm">
                <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center text-brand-600 shadow-xl shrink-0">
                   <Globe size={40} className="animate-pulse-slow" />
                </div>
                <div>
                   <h4 className="font-black text-slate-900 text-xl mb-2">Visión de Mercado Global</h4>
                   <p className="text-slate-600 text-sm leading-relaxed">
                      La demanda de expertos en logística ha crecido un <span className="font-bold text-brand-600">24%</span> en el último bienio. Las empresas buscan perfiles capaces de integrar inteligencia artificial y sostenibilidad en la cadena de suministro tradicional.
                   </p>
                </div>
                <button className="px-8 py-4 bg-brand-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-lg hover:bg-brand-700 transition-all active:scale-95 shrink-0">
                   Ver Estadísticas
                </button>
             </div>
          </div>
        )}
      </div>
    </section>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter, SortAsc, LayoutGrid, List, Activity, ExternalLink, Tag, SortDesc, Calendar, Lightbulb, PlusCircle } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');

  // Search and Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputValid = isRoute ? (hasMinPoints || input.trim().length >= 5) : input.trim().length >= 5;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltipText: isRoute 
      ? "Calcula el orden óptimo de entregas analizando tráfico, distancias y prioridades de última milla con Gemini AI."
      : "Genera borradores legales precisos, contratos CMR y cumplimiento normativo (LOTT/ROTT) adaptados a tu caso específico.",
    example: isRoute ? "Optimiza esta ruta de 5 paradas en el área metropolitana para entrega prioritaria minimizando tiempos de retorno." : "Redacta una cláusula de limitación de responsabilidad según el Convenio CMR para transporte internacional."
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 12);
    setShowValidationErrors(false);
  };

  const getLoadingMessage = (stage: LoadingStage) => {
    switch (stage) {
      case 'validating': return 'Validando parámetros...';
      case 'connecting': return 'Conectando con Gemini AI...';
      case 'streaming': return 'Recibiendo análisis inteligente...';
      case 'finalizing': return 'Finalizando reporte...';
      case 'locating': return 'Obteniendo coordenadas GPS...';
      case 'geocoding': return 'Identificando dirección...';
      default: return 'Cargando...';
    }
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu navegador no soporta geolocalización.");
      return;
    }

    setLoadingStage('locating');

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          setLoadingStage('geocoding');
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Ubicación detectada";
          const startPoint: MapPoint = { 
            lat: latitude, 
            lng: longitude, 
            id: 'loc-' + Date.now(), 
            label: `📍 Mi Posición: ${address}` 
          };
          setPoints(prev => [startPoint, ...prev]);
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          setPoints(prev => [{ lat: latitude, lng: longitude, id: 'loc-' + Date.now(), label: "📍 Ubicación GPS" }, ...prev]);
          setExternalCenter([latitude, longitude]);
        } finally { setLoadingStage('idle'); }
      },
      (error) => {
        setLoadingStage('idle');
        alert("Error al obtener ubicación: " + error.message);
      },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
    );
  };

  const handleGenerate = async () => {
    if (!isInputValid) { setShowValidationErrors(true); textareaRef.current?.focus(); return; }

    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');

    try {
      await new Promise(r => setTimeout(r, 400));
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;

        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current && isRoute) {
        setLoadingStage('finalizing');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error al procesar la secuencia optimizada." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;
    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };
    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({ isLoading: false, content: route.explanation, error: null, routeData: route.routeData });
    setViewMode('form');
    if (route.points.length > 0) setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Eliminar ruta permanentemente?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });

    return filtered.sort((a, b) => 
      sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name)
    );
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header Section */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>

                {/* Information Tooltip Icon */}
                <div className="relative group/tooltip">
                  <Info size={16} className="text-slate-400 hover:text-brand-600 transition-colors cursor-help" />

                  {/* Custom Tooltip Bubble */}
                  <div className="absolute left-1/2 -translate-x-1/2 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/tooltip:opacity-100 group-hover/tooltip:visible transition-all duration-300 z-[100] transform scale-95 group-hover/tooltip:scale-100">
                    <p className="font-medium">{config.tooltipText}</p>
                    {/* Tooltip Arrow */}
                    <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all shadow-sm active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              {viewMode === 'form' ? (
                <>
                  <History size={16} />
                  <span className="hidden sm:inline">Biblioteca ({savedRoutes.length})</span>
                </>
              ) : (
                <>
                  <ChevronRight size={16} className="rotate-180" />
                  <span>Volver al Panel</span>
                </>
              )}
            </button>
          )}
        </div>

        {/* Conditional Content: Library View */}
        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planificación
                  </h4>
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => setShowFilters(!showFilters)}
                      className={`text-[10px] font-black uppercase tracking-wider flex items-center gap-1.5 px-3 py-1.5 rounded-lg transition-all ${showFilters || startDate || endDate ? 'bg-brand-100 text-brand-700' : 'text-slate-400 hover:bg-slate-200'}`}
                    >
                      <Filter size={12} /> {startDate || endDate ? 'Filtrado' : 'Filtros'}
                    </button>
                    <button 
                      onClick={() => setViewMode('form')}
                      className="text-[10px] font-black text-brand-600 hover:text-brand-800 uppercase flex items-center gap-1.5 px-3 py-1.5 bg-brand-50 rounded-lg"
                    >
                      <PlusCircle size={14} /> Nuevo Plan
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="flex flex-col sm:flex-row gap-3">
                    <div className="relative flex-1">
                      <Search className={`absolute left-3 top-1/2 -translate-y-1/2 transition-colors ${searchQuery ? 'text-brand-500' : 'text-slate-400'}`} size={16} />
                      <input 
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Buscar por nombre de ruta..."
                        className="w-full pl-10 pr-10 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm placeholder:text-slate-400 transition-all"
                      />
                    </div>
                    <div className="flex items-center gap-1 bg-white p-1.5 border border-slate-200 rounded-xl shadow-sm">
                      <button onClick={() => setSortBy('date')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'date' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>Fecha</button>
                      <button onClick={() => setSortBy('name')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'name' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>Nombre</button>
                    </div>
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="bg-white/70 backdrop-blur-sm p-5 rounded-2xl border border-dashed border-brand-200 animate-in slide-in-from-top-2 duration-300 shadow-inner">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                        <div className="space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                            <Calendar size={10} /> Fecha Inicio
                          </label>
                          <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="w-full px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-brand-500 transition-all"
                          />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                            <Calendar size={10} /> Fecha Fin
                          </label>
                          <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="w-full px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-brand-500 transition-all"
                          />
                        </div>
                      </div>
                      <div className="flex justify-end mt-4">
                        <button 
                          onClick={resetFilters}
                          className="text-[9px] font-black text-slate-400 hover:text-red-500 uppercase tracking-widest flex items-center gap-1.5 transition-colors group"
                        >
                          <RefreshCw size={10} className="group-hover:rotate-180 transition-transform duration-500" /> Restablecer
                        </button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.map((route) => (
                    <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md active:scale-[0.99]">
                      <div className="flex-1 min-w-0 pr-4">
                        <p className="text-sm font-bold text-slate-800 truncate group-hover:text-brand-700 transition-colors">{route.name}</p>
                        <div className="flex items-center gap-3 mt-1.5">
                          <span className="text-[9px] font-bold text-slate-400 uppercase flex items-center gap-1">
                            <Clock size={10} /> {new Date(route.timestamp).toLocaleDateString()}
                          </span>
                          <span className="text-[9px] font-bold text-brand-500 bg-brand-50 px-2.5 py-0.5 rounded-full border border-brand-100">
                            {route.points.length} paradas
                          </span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button 
                          onClick={(e) => deleteSavedRoute(route.id, e)} 
                          className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all" 
                          title="Eliminar"
                        >
                          <Trash2 size={18} />
                        </button>
                        <button 
                          onClick={() => loadSavedRoute(route)} 
                          className="px-5 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-brand-700 transition-all shadow-md flex items-center gap-2 active:scale-95"
                        >
                          <PlayCircle size={14} /> Cargar
                        </button>
                      </div>
                    </div>
                  ))}
                  {processedRoutes.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 bg-white/50 rounded-2xl border border-dashed border-slate-200">
                      <div className="bg-slate-100 p-4 rounded-full mb-4">
                        <Search size={32} className="text-slate-300" />
                      </div>
                      <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Sin resultados encontrados</p>
                      <p className="text-[10px] text-slate-300 uppercase mt-2">Prueba con otros filtros o crea una nueva ruta</p>
                    </div>
                  )}
                </div>
             </div>
          </div>
        ) : (
          /* Conditional Content: Form View (Default) */
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className="mb-6 h-[240px] relative rounded-2xl overflow-hidden border-2 border-slate-100 transition-all shadow-inner">
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={setPoints} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'} 
                    />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button 
                  type="button" 
                  onClick={handleExampleClick} 
                  disabled={state.isLoading}
                  className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider group border border-brand-100 shadow-sm active:scale-95 disabled:opacity-50"
                >
                    <Lightbulb size={12} className="group-hover:text-amber-500 transition-colors" /> Ver Ejemplo
                </button>
            </div>

            <div className="relative">
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                disabled={state.isLoading}
                rows={isRoute ? 3 : 5}
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 focus:ring-brand-100 focus:border-brand-500 outline-none transition-all resize-none placeholder:text-slate-400 shadow-inner ${showValidationErrors && !input.trim() && !hasMinPoints ? 'border-red-500 bg-red-50/20' : 'border-slate-100'}`}
                placeholder={config.placeholder}
              />
              {showValidationErrors && !input.trim() && !hasMinPoints && (
                <p className="text-[10px] font-bold text-red-500 uppercase mt-2 flex items-center gap-1.5 ml-1">
                  <AlertCircle size={12} /> Se requiere una descripción o al menos 2 puntos en el mapa
                </p>
              )}
            </div>

            {state.isLoading && (
              <div className="mt-6 animate-in fade-in slide-in-from-top-1 duration-300">
                <div className="flex items-center justify-between mb-2 px-1">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-2">
                      <Activity size={12} className="animate-pulse" /> {getLoadingMessage(loadingStage)}
                   </span>
                   <span className="text-[10px] font-bold text-slate-400 uppercase flex items-center gap-1.5">
                      <Sparkles size={12} className="text-amber-400" /> Gemini 3 Pro
                   </span>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden shadow-inner">
                   <div className={`h-full bg-brand-500 transition-all duration-700 ease-out rounded-full shadow-[0_0_10px_rgba(37,99,235,0.4)] ${loadingStage === 'streaming' ? 'w-3/4 animate-pulse' : 'w-1/3'}`}></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button
                onClick={handleGenerate}
                disabled={state.isLoading}
                className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98] group`}
              >
                {state.isLoading ? (
                  <>
                    <Loader2 className="animate-spin" size={22} />
                    <span>Procesando Inteligencia...</span>
                  </>
                ) : (
                  <>
                    <Zap size={22} className="group-hover:fill-current transition-all" />
                    <span>Optimizar con IA</span>
                  </>
                )}
              </button>
            </div>
          </div>
        )}

        {/* Results Area (Always rendered if content exists, unless switched to library) */}
        <div ref={resultRef} className={`scroll-mt-24 transition-opacity duration-300 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className={`mt-10 rounded-3xl border ${config.borderColor} overflow-hidden shadow-lg animate-in fade-in slide-in-from-bottom-6 duration-700`}>
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-100">
                        <Clock size={16} className="text-brand-500" />
                      </div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Técnico Generado</span>
                    </div>
                    {!state.isLoading && isRoute && !isSaving && (
                      <button 
                        onClick={() => setIsSaving(true)} 
                        className="flex items-center gap-2 px-4 py-2 bg-white border border-brand-200 text-brand-700 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-brand-600 hover:text-white transition-all shadow-sm active:scale-95 group"
                      >
                        <Save size={14} className="group-hover:scale-110 transition-transform" /> Guardar Plan
                      </button>
                    )}
                  </div>

                  {isSaving && (
                    <div className="mb-8 p-6 bg-white rounded-2xl border-2 border-brand-200 animate-in zoom-in duration-300 shadow-2xl">
                      <div className="flex flex-col sm:flex-row gap-3">
                        <div className="relative flex-1">
                          <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-brand-300" size={16} />
                          <input 
                            autoFocus
                            value={routeName} 
                            onChange={(e) => setRouteName(e.target.value)} 
                            placeholder="Nombre identificativo de la ruta..." 
                            className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 transition-all font-bold" 
                          />
                        </div>
                        <div className="flex gap-2">
                          <button 
                            onClick={handleSaveRoute} 
                            disabled={!routeName.trim()} 
                            className="flex-1 sm:flex-none px-6 py-3 bg-brand-600 text-white rounded-xl text-[11px] font-black uppercase tracking-widest hover:bg-brand-700 shadow-lg active:scale-95 disabled:opacity-50"
                          >
                            Confirmar
                          </button>
                          <button 
                            onClick={() => { setIsSaving(false); setRouteName(''); }} 
                            className="px-4 py-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"
                          >
                            <X size={20} />
                          </button>
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm md:text-base mb-8 bg-white/40 p-6 rounded-2xl border border-white shadow-inner">
                          {state.content}
                          {state.isLoading && <span className="inline-block w-2 h-5 ml-1 bg-brand-600 animate-pulse align-middle rounded-full shadow-[0_0_8px_rgba(37,99,235,0.6)]"></span>}
                      </div>
                  </div>

                  {!state.isLoading && (
                    <div className="flex justify-end pt-2">
                        <button 
                          onClick={() => { navigator.clipboard.writeText(state.content || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} 
                          className={`flex items-center gap-2.5 px-5 py-3 rounded-xl text-[11px] font-black uppercase tracking-[0.2em] transition-all border shadow-sm active:scale-95 ${copied ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-600 border-slate-200 hover:text-brand-600 hover:border-brand-200'}`}
                        >
                            {copied ? <Check size={16} /> : <Copy size={16} />}
                            <span>{copied ? 'Copiado al Portapapeles' : 'Copiar Resultado'}</span>
                        </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, AlertTriangle, RefreshCw, Navigation2, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, Download, Edit2, X, ChevronRight, Zap, PlayCircle, Filter, SortAsc, LayoutGrid, List, Activity, ExternalLink, Tag, SortDesc, Calendar, Lightbulb, PlusCircle } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');

  // Search and Filter States
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  // Fix: Added missing resetFilters function to clear filters and search query
  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputValid = isRoute ? (hasMinPoints || input.trim().length >= 5) : input.trim().length >= 5;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltipText: isRoute 
      ? "Calcula el orden óptimo de entregas analizando tráfico, distancias y prioridades de última milla con Gemini AI."
      : "Genera borradores legales precisos, contratos CMR y cumplimiento normativo (LOTT/ROTT) adaptados a tu caso específico.",
    example: isRoute ? "Optimiza esta ruta de 5 paradas en el área metropolitana para entrega prioritaria minimizando tiempos de retorno." : "Redacta una cláusula de limitación de responsabilidad según el Convenio CMR para transporte internacional."
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 12);
    setShowValidationErrors(false);
  };

  const getLoadingMessage = (stage: LoadingStage) => {
    switch (stage) {
      case 'validating': return 'Validando parámetros...';
      case 'connecting': return 'Conectando con Gemini AI...';
      case 'streaming': return 'Recibiendo análisis inteligente...';
      case 'finalizing': return 'Finalizando reporte...';
      case 'locating': return 'Obteniendo coordenadas GPS...';
      case 'geocoding': return 'Identificando dirección...';
      default: return 'Cargando...';
    }
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu navegador no soporta geolocalización.");
      return;
    }

    setLoadingStage('locating');

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          setLoadingStage('geocoding');
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Ubicación detectada";
          const startPoint: MapPoint = { 
            lat: latitude, 
            lng: longitude, 
            id: 'loc-' + Date.now(), 
            label: `📍 Mi Posición: ${address}` 
          };
          setPoints(prev => [startPoint, ...prev]);
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          setPoints(prev => [{ lat: latitude, lng: longitude, id: 'loc-' + Date.now(), label: "📍 Ubicación GPS" }, ...prev]);
          setExternalCenter([latitude, longitude]);
        } finally { setLoadingStage('idle'); }
      },
      (error) => {
        setLoadingStage('idle');
        alert("Error al obtener ubicación: " + error.message);
      },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
    );
  };

  const handleGenerate = async () => {
    if (!isInputValid) { setShowValidationErrors(true); textareaRef.current?.focus(); return; }

    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');

    try {
      await new Promise(r => setTimeout(r, 400));
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;

        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current && isRoute) {
        setLoadingStage('finalizing');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error al procesar la secuencia optimizada." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;
    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };
    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({ isLoading: false, content: route.explanation, error: null, routeData: route.routeData });
    setViewMode('form');
    if (route.points.length > 0) setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Eliminar ruta permanentemente?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });

    return filtered.sort((a, b) => 
      sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name)
    );
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header Section */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900">{config.title}</h3>

                {/* Information Tooltip Icon */}
                <div className="relative group/tooltip">
                  <Info size={16} className="text-slate-400 hover:text-brand-600 transition-colors cursor-help" />

                  {/* Custom Tooltip Bubble */}
                  <div className="absolute left-1/2 -translate-x-1/2 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/tooltip:opacity-100 group-hover/tooltip:visible transition-all duration-300 z-[100] transform scale-95 group-hover/tooltip:scale-100">
                    <p className="font-medium">{config.tooltipText}</p>
                    {/* Tooltip Arrow */}
                    <div className="absolute top-full left-1/2 -translate-x-1/2 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all shadow-sm active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              {viewMode === 'form' ? (
                <>
                  <History size={16} />
                  <span className="hidden sm:inline">Biblioteca ({savedRoutes.length})</span>
                </>
              ) : (
                <>
                  <ChevronRight size={16} className="rotate-180" />
                  <span>Volver al Panel</span>
                </>
              )}
            </button>
          )}
        </div>

        {/* Conditional Content: Library View */}
        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planificación
                  </h4>
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => setShowFilters(!showFilters)}
                      className={`text-[10px] font-black uppercase tracking-wider flex items-center gap-1.5 px-3 py-1.5 rounded-lg transition-all ${showFilters || startDate || endDate ? 'bg-brand-100 text-brand-700' : 'text-slate-400 hover:bg-slate-200'}`}
                    >
                      <Filter size={12} /> {startDate || endDate ? 'Filtrado' : 'Filtros'}
                    </button>
                    <button 
                      onClick={() => setViewMode('form')}
                      className="text-[10px] font-black text-brand-600 hover:text-brand-800 uppercase flex items-center gap-1.5 px-3 py-1.5 bg-brand-50 rounded-lg"
                    >
                      <PlusCircle size={14} /> Nuevo Plan
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="flex flex-col sm:flex-row gap-3">
                    <div className="relative flex-1">
                      <Search className={`absolute left-3 top-1/2 -translate-y-1/2 transition-colors ${searchQuery ? 'text-brand-500' : 'text-slate-400'}`} size={16} />
                      <input 
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Buscar por nombre de ruta..."
                        className="w-full pl-10 pr-10 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm placeholder:text-slate-400 transition-all"
                      />
                    </div>
                    <div className="flex items-center gap-1 bg-white p-1.5 border border-slate-200 rounded-xl shadow-sm">
                      <button onClick={() => setSortBy('date')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'date' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>Fecha</button>
                      <button onClick={() => setSortBy('name')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${sortBy === 'name' ? 'bg-brand-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>Nombre</button>
                    </div>
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="bg-white/70 backdrop-blur-sm p-5 rounded-2xl border border-dashed border-brand-200 animate-in slide-in-from-top-2 duration-300 shadow-inner">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                        <div className="space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                            <Calendar size={10} /> Fecha Inicio
                          </label>
                          <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="w-full px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-brand-500 transition-all"
                          />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                            <Calendar size={10} /> Fecha Fin
                          </label>
                          <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="w-full px-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:ring-2 focus:ring-brand-500 transition-all"
                          />
                        </div>
                      </div>
                      <div className="flex justify-end mt-4">
                        <button 
                          onClick={resetFilters}
                          className="text-[9px] font-black text-slate-400 hover:text-red-500 uppercase tracking-widest flex items-center gap-1.5 transition-colors group"
                        >
                          <RefreshCw size={10} className="group-hover:rotate-180 transition-transform duration-500" /> Restablecer
                        </button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.map((route) => (
                    <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md active:scale-[0.99]">
                      <div className="flex-1 min-w-0 pr-4">
                        <p className="text-sm font-bold text-slate-800 truncate group-hover:text-brand-700 transition-colors">{route.name}</p>
                        <div className="flex items-center gap-3 mt-1.5">
                          <span className="text-[9px] font-bold text-slate-400 uppercase flex items-center gap-1">
                            <Clock size={10} /> {new Date(route.timestamp).toLocaleDateString()}
                          </span>
                          <span className="text-[9px] font-bold text-brand-500 bg-brand-50 px-2.5 py-0.5 rounded-full border border-brand-100">
                            {route.points.length} paradas
                          </span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button 
                          onClick={(e) => deleteSavedRoute(route.id, e)} 
                          className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all" 
                          title="Eliminar"
                        >
                          <Trash2 size={18} />
                        </button>
                        <button 
                          onClick={() => loadSavedRoute(route)} 
                          className="px-5 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-brand-700 transition-all shadow-md flex items-center gap-2 active:scale-95"
                        >
                          <PlayCircle size={14} /> Cargar
                        </button>
                      </div>
                    </div>
                  ))}
                  {processedRoutes.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 bg-white/50 rounded-2xl border border-dashed border-slate-200">
                      <div className="bg-slate-100 p-4 rounded-full mb-4">
                        <Search size={32} className="text-slate-300" />
                      </div>
                      <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Sin resultados encontrados</p>
                      <p className="text-[10px] text-slate-300 uppercase mt-2">Prueba con otros filtros o crea una nueva ruta</p>
                    </div>
                  )}
                </div>
             </div>
          </div>
        ) : (
          /* Conditional Content: Form View (Default) */
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className="mb-6 h-[240px] relative rounded-2xl overflow-hidden border-2 border-slate-100 transition-all shadow-inner">
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={setPoints} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'} 
                    />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button 
                  type="button" 
                  onClick={handleExampleClick} 
                  disabled={state.isLoading}
                  className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider group border border-brand-100 shadow-sm active:scale-95 disabled:opacity-50"
                >
                    <Lightbulb size={12} className="group-hover:text-amber-500 transition-colors" /> Ver Ejemplo
                </button>
            </div>

            <div className="relative">
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                disabled={state.isLoading}
                rows={isRoute ? 3 : 5}
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 focus:ring-brand-100 focus:border-brand-500 outline-none transition-all resize-none placeholder:text-slate-400 shadow-inner ${showValidationErrors && !input.trim() && !hasMinPoints ? 'border-red-500 bg-red-50/20' : 'border-slate-100'}`}
                placeholder={config.placeholder}
              />
              {showValidationErrors && !input.trim() && !hasMinPoints && (
                <p className="text-[10px] font-bold text-red-500 uppercase mt-2 flex items-center gap-1.5 ml-1">
                  <AlertCircle size={12} /> Se requiere una descripción o al menos 2 puntos en el mapa
                </p>
              )}
            </div>

            {state.isLoading && (
              <div className="mt-6 animate-in fade-in slide-in-from-top-1 duration-300">
                <div className="flex items-center justify-between mb-2 px-1">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-2">
                      <Activity size={12} className="animate-pulse" /> {getLoadingMessage(loadingStage)}
                   </span>
                   <span className="text-[10px] font-bold text-slate-400 uppercase flex items-center gap-1.5">
                      <Sparkles size={12} className="text-amber-400" /> Gemini 3 Pro
                   </span>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden shadow-inner">
                   <div className={`h-full bg-brand-500 transition-all duration-700 ease-out rounded-full shadow-[0_0_10px_rgba(37,99,235,0.4)] ${loadingStage === 'streaming' ? 'w-3/4 animate-pulse' : 'w-1/3'}`}></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button
                onClick={handleGenerate}
                disabled={state.isLoading}
                className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98] group`}
              >
                {state.isLoading ? (
                  <>
                    <Loader2 className="animate-spin" size={22} />
                    <span>Procesando Inteligencia...</span>
                  </>
                ) : (
                  <>
                    <Zap size={22} className="group-hover:fill-current transition-all" />
                    <span>Optimizar con IA</span>
                  </>
                )}
              </button>
            </div>
          </div>
        )}

        {/* Results Area (Always rendered if content exists, unless switched to library) */}
        <div ref={resultRef} className={`scroll-mt-24 transition-opacity duration-300 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className={`mt-10 rounded-3xl border ${config.borderColor} overflow-hidden shadow-lg animate-in fade-in slide-in-from-bottom-6 duration-700`}>
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-100">
                        <Clock size={16} className="text-brand-500" />
                      </div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Técnico Generado</span>
                    </div>
                    {!state.isLoading && isRoute && !isSaving && (
                      <button 
                        onClick={() => setIsSaving(true)} 
                        className="flex items-center gap-2 px-4 py-2 bg-white border border-brand-200 text-brand-700 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-brand-600 hover:text-white transition-all shadow-sm active:scale-95 group"
                      >
                        <Save size={14} className="group-hover:scale-110 transition-transform" /> Guardar Plan
                      </button>
                    )}
                  </div>

                  {isSaving && (
                    <div className="mb-8 p-6 bg-white rounded-2xl border-2 border-brand-200 animate-in zoom-in duration-300 shadow-2xl">
                      <div className="flex flex-col sm:flex-row gap-3">
                        <div className="relative flex-1">
                          <Tag className="absolute left-3 top-1/2 -translate-y-1/2 text-brand-300" size={16} />
                          <input 
                            autoFocus
                            value={routeName} 
                            onChange={(e) => setRouteName(e.target.value)} 
                            placeholder="Nombre identificativo de la ruta..." 
                            className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 transition-all font-bold" 
                          />
                        </div>
                        <div className="flex gap-2">
                          <button 
                            onClick={handleSaveRoute} 
                            disabled={!routeName.trim()} 
                            className="flex-1 sm:flex-none px-6 py-3 bg-brand-600 text-white rounded-xl text-[11px] font-black uppercase tracking-widest hover:bg-brand-700 shadow-lg active:scale-95 disabled:opacity-50"
                          >
                            Confirmar
                          </button>
                          <button 
                            onClick={() => { setIsSaving(false); setRouteName(''); }} 
                            className="px-4 py-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"
                          >
                            <X size={20} />
                          </button>
                        </div>
                      </div>
                    </div>
                  )}

                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm md:text-base mb-8 bg-white/40 p-6 rounded-2xl border border-white shadow-inner">
                          {state.content}
                          {state.isLoading && <span className="inline-block w-2 h-5 ml-1 bg-brand-600 animate-pulse align-middle rounded-full shadow-[0_0_8px_rgba(37,99,235,0.6)]"></span>}
                      </div>
                  </div>

                  {!state.isLoading && (
                    <div className="flex justify-end pt-2">
                        <button 
                          onClick={() => { navigator.clipboard.writeText(state.content || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} 
                          className={`flex items-center gap-2.5 px-5 py-3 rounded-xl text-[11px] font-black uppercase tracking-[0.2em] transition-all border shadow-sm active:scale-95 ${copied ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-600 border-slate-200 hover:text-brand-600 hover:border-brand-200'}`}
                        >
                            {copied ? <Check size={16} /> : <Copy size={16} />}
                            <span>{copied ? 'Copiado al Portapapeles' : 'Copiar Resultado'}</span>
                        </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, X, ChevronRight, Zap, PlayCircle, Filter, Activity, Tag, Calendar, Lightbulb, PlusCircle } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });
  const [copied, setCopied] = useState(false);
  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [routeName, setRouteName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputValid = isRoute ? (hasMinPoints || input.trim().length >= 5) : input.trim().length >= 5;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltip: isRoute 
      ? "IA Generativa aplicada al TSP (Traveling Salesman Problem) con restricciones de carga, tiempos de conducción y optimización de km en vacío."
      : "Base de conocimiento LOTT/ROTT actualizada para la redacción automática de contratos CMR, pactos de responsabilidad y cláusulas de demora.",
    example: isRoute ? "Optimiza esta ruta de 5 paradas en el área metropolitana para entrega prioritaria minimizando tiempos de retorno." : "Redacta una cláusula de limitación de responsabilidad según el Convenio CMR para transporte internacional."
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 12);
    setShowValidationErrors(false);
  };

  const getLoadingMessage = (stage: LoadingStage) => {
    switch (stage) {
      case 'validating': return 'Validando parámetros...';
      case 'connecting': return 'Conectando con Gemini AI...';
      case 'streaming': return 'Recibiendo análisis inteligente...';
      case 'finalizing': return 'Finalizando reporte...';
      case 'locating': return 'Obteniendo coordenadas GPS...';
      case 'geocoding': return 'Identificando dirección...';
      default: return 'Cargando...';
    }
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert("Tu navegador no soporta geolocalización.");
      return;
    }
    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          setLoadingStage('geocoding');
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const address = data.display_name.split(',').slice(0, 2).join(',') || "Ubicación detectada";
          const startPoint: MapPoint = { 
            lat: latitude, 
            lng: longitude, 
            id: 'loc-' + Date.now(), 
            label: `📍 Mi Posición: ${address}` 
          };
          setPoints(prev => [startPoint, ...prev]);
          setExternalCenter([latitude, longitude]);
        } catch (err) {
          setPoints(prev => [{ lat: latitude, lng: longitude, id: 'loc-' + Date.now(), label: "📍 Ubicación GPS" }, ...prev]);
          setExternalCenter([latitude, longitude]);
        } finally { setLoadingStage('idle'); }
      },
      (error) => {
        setLoadingStage('idle');
        alert("Error al obtener ubicación: " + error.message);
      },
      { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
    );
  };

  const handleGenerate = async () => {
    if (!isInputValid) { setShowValidationErrors(true); textareaRef.current?.focus(); return; }
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    try {
      await new Promise(r => setTimeout(r, 400));
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';
      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }
      if (isMounted.current && isRoute) {
        setLoadingStage('finalizing');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error al procesar la secuencia optimizada." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const handleSaveRoute = () => {
    if (!state.routeData || !routeName.trim()) return;
    const newSavedRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: routeName.trim(),
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };
    const updated = [newSavedRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    setIsSaving(false);
    setRouteName('');
  };

  const loadSavedRoute = (route: SavedRoute) => {
    setPoints(route.points);
    setState({ isLoading: false, content: route.explanation, error: null, routeData: route.routeData });
    setViewMode('form');
    if (route.points.length > 0) setExternalCenter([route.points[0].lat, route.points[0].lng]);
  };

  const deleteSavedRoute = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm("¿Eliminar ruta permanentemente?")) {
      const updated = savedRoutes.filter(r => r.id !== id);
      setSavedRoutes(updated);
      localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
    return filtered.sort((a, b) => 
      sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name)
    );
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header con Tooltip Dinámico */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg relative`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900 tracking-tight">{config.title}</h3>

                {/* Tooltip Info Icon */}
                <div className="relative group/info">
                  <div className="p-1 rounded-full bg-slate-100 text-slate-400 hover:text-brand-600 hover:bg-brand-50 transition-all cursor-help relative overflow-hidden">
                    <Info size={14} />
                    <span className="absolute inset-0 bg-brand-500/20 animate-ping rounded-full"></span>
                  </div>

                  {/* Tooltip Content */}
                  <div className="absolute left-0 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/info:opacity-100 group-hover/info:visible transition-all duration-300 z-50 transform translate-y-2 group-hover/info:translate-y-0">
                    <div className="flex items-center gap-2 mb-2 text-brand-400 font-black uppercase tracking-widest text-[9px]">
                      <Sparkles size={10} /> Análisis Técnico
                    </div>
                    <p className="font-medium">{config.tooltip}</p>
                    <div className="absolute top-full left-4 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all shadow-sm active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              {viewMode === 'form' ? (
                <><History size={16} /><span className="hidden sm:inline">Biblioteca ({savedRoutes.length})</span></>
              ) : (
                <><ChevronRight size={16} className="rotate-180" /><span>Volver</span></>
              )}
            </button>
          )}
        </div>

        {/* Rest of the component remains largely the same, optimized for performance */}
        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planificación
                  </h4>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setShowFilters(!showFilters)} className={`text-[10px] font-black uppercase tracking-wider flex items-center gap-1.5 px-3 py-1.5 rounded-lg transition-all ${showFilters || startDate || endDate ? 'bg-brand-100 text-brand-700' : 'text-slate-400 hover:bg-slate-200'}`}>
                      <Filter size={12} /> Filtros
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="flex flex-col sm:flex-row gap-3">
                    <div className="relative flex-1">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar ruta..." className="w-full pl-10 pr-10 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-500 shadow-sm" />
                    </div>
                  </div>
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.map((route) => (
                    <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm">
                      <div className="flex-1 min-w-0 pr-4">
                        <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                        <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                          <Clock size={10} /> {new Date(route.timestamp).toLocaleDateString()}
                          <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded">{route.points.length} paradas</span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button onClick={(e) => deleteSavedRoute(route.id, e)} className="p-2 text-slate-400 hover:text-red-500 transition-colors"><Trash2 size={16} /></button>
                        <button onClick={() => loadSavedRoute(route)} className="px-4 py-2 bg-brand-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-brand-700 transition-all active:scale-95">Cargar</button>
                      </div>
                    </div>
                  ))}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className="mb-6 h-[240px] relative rounded-2xl overflow-hidden border-2 border-slate-100 shadow-inner">
                    <LogisticsMap points={points} onPointsChange={setPoints} routeSequence={state.routeData} externalCenter={externalCenter} onAddCurrentLocation={handleAddCurrentLocation} isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'} />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button type="button" onClick={handleExampleClick} disabled={state.isLoading} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider border border-brand-100 shadow-sm disabled:opacity-50">
                    <Lightbulb size={12} className="text-amber-500" /> Ver Ejemplo
                </button>
            </div>

            <div className="relative">
              <textarea ref={textareaRef} value={input} onChange={(e) => setInput(e.target.value)} disabled={state.isLoading} rows={isRoute ? 3 : 5} className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 focus:ring-brand-100 focus:border-brand-500 outline-none transition-all resize-none shadow-inner ${showValidationErrors && !input.trim() && !hasMinPoints ? 'border-red-500' : 'border-slate-100'}`} placeholder={config.placeholder} />
            </div>

            {state.isLoading && (
              <div className="mt-6 animate-pulse">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-2"><Activity size={12} /> {getLoadingMessage(loadingStage)}</span>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className="h-full bg-brand-500 w-1/3 animate-progress rounded-full"></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={state.isLoading} className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98]`}>
                {state.isLoading ? <Loader2 className="animate-spin" size={22} /> : <Zap size={22} />}
                <span>{state.isLoading ? 'Analizando...' : 'Optimizar con IA'}</span>
              </button>
            </div>
          </div>
        )}

        <div ref={resultRef} className={`scroll-mt-24 transition-opacity duration-300 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className={`mt-10 rounded-3xl border ${config.borderColor} overflow-hidden shadow-lg animate-in slide-in-from-bottom-6 duration-700`}>
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-100"><Clock size={16} className="text-brand-500" /></div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Generado</span>
                    </div>
                  </div>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm bg-white/40 p-6 rounded-2xl border border-white shadow-inner">{state.content}</div>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

