                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs" />
                        </div>
                      </div>
                      <button onClick={resetFilters} className="mt-4 w-full py-2 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 hover:text-brand-600 uppercase transition-all">
                        <RefreshCw size={12} /> Limpiar Filtros
                      </button>
                    </div>
