                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.map((route) => (
                    <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm">
                      <div className="flex-1 min-w-0 pr-4">
                        <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                        <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                          <Calendar size={10} /> {new Date(route.timestamp).toLocaleDateString()}
                          <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded">{route.points.length} paradas</span>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button onClick={() => { setPoints(route.points); setViewMode('form'); }} className="px-4 py-2 bg-brand-600 text-white rounded-lg text-[9px] font-black uppercase hover:bg-brand-700 transition-all active:scale-95">Cargar</button>
                      </div>
                    </div>
                  ))}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className="mb-6 h-[240px] relative rounded-2xl overflow-hidden border-2 border-slate-100 shadow-inner">
                    <LogisticsMap points={points} onPointsChange={setPoints} routeSequence={state.routeData} externalCenter={externalCenter} onAddCurrentLocation={handleAddCurrentLocation} isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'} />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button type="button" onClick={handleExampleClick} disabled={state.isLoading} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider border border-brand-100 shadow-sm active:scale-95 disabled:opacity-50">
                    <Lightbulb size={12} className="text-amber-500" /> Ver Ejemplo
                </button>
            </div>

            <div className="relative">
              <textarea ref={textareaRef} value={input} onChange={(e) => setInput(e.target.value)} disabled={state.isLoading} rows={isRoute ? 3 : 5} className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 focus:ring-brand-100 focus:border-brand-500 outline-none transition-all resize-none shadow-inner ${showValidationErrors && !input.trim() && !hasMinPoints ? 'border-red-500' : 'border-slate-100'}`} placeholder={config.placeholder} />
            </div>

            {state.isLoading && (
              <div className="mt-6 animate-pulse">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-2"><Activity size={12} /> {getLoadingMessage(loadingStage)}</span>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className="h-full bg-brand-500 w-1/3 animate-progress rounded-full"></div>
