                    <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl transition-all ${showFilters || startDate || endDate ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200 hover:text-brand-600'}`}>
                      <Filter size={18} />
