                disabled={state.isLoading} 
                rows={isRoute ? 3 : 5} 
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 focus:ring-brand-100 focus:border-brand-500 outline-none transition-all resize-none shadow-inner ${showValidationErrors && !isInputValid ? 'border-red-500 bg-red-50/30' : 'border-slate-100'}`} 
                placeholder={config.placeholder} 
              />
              {showValidationErrors && !isInputValid && (
                <p className="mt-2 text-xs font-bold text-red-500 flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} />
