                </p>
              )}
            </div>

            {(state.isLoading || loadingStage !== 'idle') && (
              <div className="mt-6 animate-pulse">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-2"><Activity size={12} /> {
                     loadingStage === 'locating' ? 'Obteniendo GPS...' : 
                     loadingStage === 'geocoding' ? 'Identificando dirección...' :
                     'Recibiendo respuesta...'
                   }</span>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className="h-full bg-brand-500 w-1/3 animate-progress rounded-full"></div>
                </div>
