            <button 
              onClick={closeMenu}
              className="p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-full transition-all"
            >
              <X size={20} />
            </button>
          </div>

          {/* Navigation Links */}
          <div className="flex-1 overflow-y-auto p-4 space-y-2 py-6">
            {navLinks.map((link, index) => (
              <NavLink 
                key={link.name} 
