import React, { useEffect, useState, useMemo } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMapEvents, useMap, Circle } from 'react-leaflet';
import L from 'leaflet';
import { MapPoint } from '../types';
import { Trash2, Search, Navigation, Loader2, Maximize2, Minimize2, Check, Edit2, X } from 'lucide-react';

// Fix for default marker icons
// @ts-ignore
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

interface LogisticsMapProps {
  points: MapPoint[];
  onPointsChange: (points: MapPoint[]) => void;
  routeSequence?: number[];
  externalCenter?: [number, number];
  onAddCurrentLocation?: () => void;
  isLocating?: boolean;
  onLoadingChange?: (stage: string) => void;
}

const createNumberedIcon = (number: number, isStart: boolean, isEnd: boolean, isSpecial: boolean = false, isHovered: boolean = false) => {
  let bgClass = 'bg-brand-600 ring-4 ring-brand-100';
  if (isStart) bgClass = 'bg-emerald-500 ring-4 ring-emerald-100 shadow-[0_0_20px_rgba(16,185,129,0.4)]';
  else if (isEnd) bgClass = 'bg-red-500 ring-4 ring-red-100 shadow-[0_0_20px_rgba(239,68,68,0.4)]';

  if (isSpecial) bgClass = 'bg-emerald-600 ring-[6px] ring-emerald-500/30 animate-pulse';

  const glowClass = isHovered ? 'marker-glow-active scale-110 shadow-[0_0_25px_rgba(37,99,235,0.6)]' : '';

  return L.divIcon({
    html: `<div class="relative flex items-center justify-center group z-50">
        <div class="absolute w-10 h-10 ${bgClass} ${glowClass} rounded-full border-2 border-white shadow-2xl transition-all duration-300"></div>
        <span class="relative text-white font-black text-[13px] drop-shadow-md transition-transform duration-300 ${isHovered ? 'scale-110' : ''}">${number}</span>
      </div>`,
    className: 'custom-div-icon',
    iconSize: [40, 40],
    iconAnchor: [20, 20],
    popupAnchor: [0, -10]
  });
};

const createInactiveIcon = (label: string) => {
  return L.divIcon({
    html: `<div class="relative flex items-center justify-center opacity-40 grayscale group">
        <div class="absolute w-8 h-8 bg-slate-400 rounded-full border-2 border-white"></div>
        <span class="relative text-white font-bold text-[10px]">${label}</span>
      </div>`,
    className: 'custom-div-icon',
    iconSize: [32, 32],
    iconAnchor: [16, 16],
  });
};

const MapController = ({ 
  centerOn, 
  routePath, 
  onAdd,
  searchQuery,
  isFullScreen
}: { 
  centerOn?: [number, number], 
  routePath?: [number, number][],
  onAdd: (lat: number, lng: number, label?: string) => void,
  searchQuery: string,
  isFullScreen: boolean
}) => {
  const map = useMap();

  // Ensure map adjusts size when entering/exiting full screen
  useEffect(() => {
    const timer = setTimeout(() => {
      map.invalidateSize();
    }, 450); // Slightly more than the 300-500ms transition
    return () => clearTimeout(timer);
  }, [isFullScreen, map]);

  useEffect(() => {
    if (centerOn) {
      map.flyTo(centerOn, 16, { animate: true, duration: 1.5 });
      setTimeout(() => map.invalidateSize(), 300);
    }
  }, [centerOn, map]);

  useEffect(() => {
    if (routePath && routePath.length > 1) {
      const bounds = L.latLngBounds(routePath);
      map.fitBounds(bounds, { padding: [100, 100], maxZoom: 16, animate: true });
    }
  }, [routePath, map]);

  useMapEvents({
    click(e) {
      if (!searchQuery.trim()) {
        return;
      }
      onAdd(e.latlng.lat, e.latlng.lng, searchQuery);
    },
  });

  return null;
};

export const LogisticsMap: React.FC<LogisticsMapProps> = ({ points, onPointsChange, routeSequence, externalCenter, onAddCurrentLocation, isLocating, onLoadingChange }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [centerOn, setCenterOn] = useState<[number, number] | undefined>(undefined);
  const [hoveredPointId, setHoveredPointId] = useState<string | null>(null);

  // Edit State
  const [editingPointId, setEditingPointId] = useState<string | null>(null);
  const [tempLabel, setTempLabel] = useState('');

  const toggleFullScreen = () => {
    const newState = !isFullScreen;
    setIsFullScreen(newState);
    if (newState) {
      document.body.classList.add('no-scroll');
    } else {
      document.body.classList.remove('no-scroll');
    }
  };

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      document.body.classList.remove('no-scroll');
    };
  }, []);

  useEffect(() => {
    if (externalCenter) {
      setCenterOn([...externalCenter]);
    }
  }, [externalCenter]);

  const handleAddPoint = async (lat: number, lng: number, label?: string) => {
    const finalLabel = label || `Punto ${points.length + 1}`;
    onPointsChange([...points, { lat, lng, id: Math.random().toString(36).substr(2, 9), label: finalLabel }]);
    if (label) setSearchQuery('');
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    onLoadingChange?.('geocoding');
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(searchQuery)}`);
      const data = await resp.json();
      if (data && data.length > 0) {
        const { lat, lon, display_name } = data[0];
        const newCenter: [number, number] = [parseFloat(lat), parseFloat(lon)];
        setCenterOn(newCenter);
        handleAddPoint(newCenter[0], newCenter[1], display_name.split(',')[0]);
        setSearchQuery('');
      }
    } catch (err) { 
      console.error(err); 
    } finally { 
      setIsSearching(false); 
      onLoadingChange?.('idle');
    }
  };

  const startEditing = (point: MapPoint) => {
    setEditingPointId(point.id);
    setTempLabel(point.label || '');
  };

  const saveEdit = (id: string) => {
    if (!tempLabel.trim()) return;
    onPointsChange(points.map(p => p.id === id ? { ...p, label: tempLabel.trim() } : p));
    setEditingPointId(null);
  };

  const cancelEdit = () => {
    setEditingPointId(null);
    setTempLabel('');
  };

  const routePath = useMemo(() => {
    if (routeSequence && routeSequence.length > 0) {
      return routeSequence
        .filter(idx => points[idx] !== undefined)
        .map(idx => [points[idx].lat, points[idx].lng] as [number, number]);
    }
    return [];
  }, [routeSequence, points]);

  const hasActiveRoute = routeSequence && routeSequence.length > 0;

  return (
    <div className={`flex flex-col gap-4 transition-all duration-500 ${isFullScreen ? 'fixed inset-0 z-[60] bg-slate-900 p-0 sm:p-4' : 'relative'}`}>
      {!isFullScreen && (
        <div className="flex flex-col md:flex-row gap-3">
            <form onSubmit={handleSearch} className="relative flex-1 flex gap-2">
              <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                      type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder="Buscar dirección o cliente..."
                      className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 outline-none shadow-sm"
                  />
              </div>
              <button type="submit" disabled={isSearching} className="bg-brand-600 text-white px-6 rounded-xl font-bold shadow-lg shadow-brand-500/20 active:scale-95 transition-all">
                  {isSearching ? <Loader2 size={18} className="animate-spin" /> : 'Añadir'}
              </button>
            </form>
            <button 
              onClick={(e) => { e.preventDefault(); onAddCurrentLocation?.(); }} 
              disabled={isLocating} 
              className={`px-4 py-3 rounded-xl font-bold flex items-center justify-center gap-2 border transition-all active:scale-95 shadow-sm ${isLocating ? 'bg-slate-100 text-slate-400' : 'bg-emerald-50 text-emerald-700 border-emerald-100 hover:bg-emerald-100'}`}
            >
                {isLocating ? <Loader2 size={16} className="animate-spin" /> : <Navigation size={18} />}
                <span className="text-xs">GPS Actual</span>
            </button>
        </div>
      )}

      <div className={`relative transition-all duration-500 overflow-hidden border border-slate-200 shadow-2xl ${isFullScreen ? 'h-full w-full rounded-none' : 'h-[450px] w-full rounded-3xl'}`}>
        <MapContainer center={[40.4168, -3.7038]} zoom={13} zoomControl={false} style={{ height: '100%', width: '100%' }}>
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <MapController 
            centerOn={centerOn} 
            routePath={routePath} 
            onAdd={handleAddPoint} 
            searchQuery={searchQuery} 
            isFullScreen={isFullScreen} 
          />

          {points.map((point, index) => {
            const isGPS = point.id.startsWith('loc-');
            const routePos = routeSequence?.indexOf(index);
            const isInRoute = routePos !== undefined && routePos !== -1;
            const isHovered = hoveredPointId === point.id;

            const markerIcon = isInRoute 
              ? createNumberedIcon(routePos! + 1, routePos === 0, routePos === (routeSequence!.length - 1), isGPS, isHovered)
              : hasActiveRoute ? createInactiveIcon((index + 1).toString()) : createNumberedIcon(index + 1, false, false, isGPS, isHovered);

            const isEditing = editingPointId === point.id;

            return (
              <React.Fragment key={point.id}>
                {isGPS && <Circle center={[point.lat, point.lng]} radius={30} pathOptions={{ color: '#10b981', fillColor: '#10b981', fillOpacity: 0.2 }} />}
                <Marker 
                  position={[point.lat, point.lng]} 
                  icon={markerIcon}
                  eventHandlers={{
                    mouseover: () => setHoveredPointId(point.id),
                    mouseout: () => setHoveredPointId(null),
                  }}
                >
                  <Popup 
                    closeButton={false} 
                    minWidth={180}
                    className={isHovered ? 'popup-glow-active' : ''}
                  >
                    <div className="p-2 bg-white rounded-lg min-w-[160px]">
                      {isEditing ? (
                        <div className="space-y-2 animate-in fade-in duration-200">
                          <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Nombre Entrega</p>
                          <input 
                            autoFocus
                            type="text"
                            value={tempLabel}
                            onChange={(e) => setTempLabel(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') saveEdit(point.id);
                              if (e.key === 'Escape') cancelEdit();
                            }}
                            className="w-full px-2 py-1.5 border border-brand-300 rounded text-xs outline-none focus:ring-2 focus:ring-brand-500 font-bold"
                          />
                          <div className="flex gap-2">
                            <button onClick={() => saveEdit(point.id)} className="flex-1 bg-brand-600 text-white py-1 rounded text-[10px] font-bold flex items-center justify-center gap-1"><Check size={12} /> OK</button>
                            <button onClick={cancelEdit} className="px-2 bg-slate-100 text-slate-500 py-1 rounded text-[10px] font-bold"><X size={12} /></button>
                          </div>
                        </div>
                      ) : (
                        <div className="animate-in fade-in duration-200">
                          <div className="flex items-center gap-2 mb-3 border-b border-slate-100 pb-2">
                            <div className="w-5 h-5 bg-brand-600 rounded-full flex items-center justify-center text-[10px] text-white font-black">{isInRoute ? routePos! + 1 : index + 1}</div>
                            <p className="font-bold text-xs text-slate-900 truncate flex-1">{point.label}</p>
                          </div>
                          <div className="flex flex-col gap-1.5">
                            <button 
                              onClick={() => startEditing(point)} 
                              className="w-full text-[10px] font-black uppercase tracking-wider text-brand-600 bg-brand-50 py-1.5 rounded flex items-center justify-center gap-1.5 hover:bg-brand-100 transition-colors"
                            >
                              <Edit2 size={12} /> Renombrar
                            </button>
                            <button 
                              onClick={() => onPointsChange(points.filter(p => p.id !== point.id))} 
                              className="w-full text-[10px] font-black uppercase tracking-wider text-red-500 bg-red-50 py-1.5 rounded flex items-center justify-center gap-1.5 hover:bg-red-100 transition-colors"
                            >
                              <Trash2 size={12} /> Eliminar
                            </button>
                          </div>
                        </div>
                      )}
                    </div>
                  </Popup>
                </Marker>
              </React.Fragment>
            );
          })}

          {routePath.length > 1 && (
            <>
              {/* Outer stroke for contrast */}
              <Polyline positions={routePath} pathOptions={{ color: '#fff', weight: 10, opacity: 0.8 }} />
              {/* Main path */}
              <Polyline positions={routePath} pathOptions={{ color: '#3b82f6', weight: 6, opacity: 1, lineJoin: 'round', dashArray: '1, 12' }} />
              {/* Animated effect (optional visual clue) */}
              <Polyline positions={routePath} pathOptions={{ color: '#2563eb', weight: 6, opacity: 0.6, lineJoin: 'round' }} />
            </>
          )}
        </MapContainer>

        <div className="absolute top-4 right-4 z-[1000] flex flex-col gap-2">
            <button 
              onClick={(e) => { e.preventDefault(); onAddCurrentLocation?.(); }} 
              disabled={isLocating} 
              className="bg-white p-3 rounded-full shadow-xl border border-slate-200 text-slate-700 hover:text-emerald-600 hover:scale-110 active:scale-90 transition-all group"
              title="Centrar en mi ubicación"
            >
                {isLocating ? <Loader2 size={24} className="animate-spin text-emerald-500" /> : <Navigation size={24} />}
            </button>
            <button 
              onClick={toggleFullScreen} 
              className={`p-3 rounded-full shadow-xl border transition-all hover:scale-110 active:scale-90 ${isFullScreen ? 'bg-slate-900 text-white border-slate-700' : 'bg-white text-slate-700 border-slate-200'}`}
              title={isFullScreen ? "Salir de pantalla completa" : "Pantalla completa"}
            >
                {isFullScreen ? <Minimize2 size={24} /> : <Maximize2 size={24} />}
            </button>
        </div>

        {hasActiveRoute && (
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[1000] bg-slate-900/90 text-white px-5 py-2.5 rounded-2xl flex items-center gap-3 backdrop-blur-md shadow-2xl border border-white/10 animate-in slide-in-from-bottom-2">
             <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></div>
             <span className="text-[10px] font-black uppercase tracking-widest">Ruta Optimizada Activa</span>
          </div>
        )}

        {isLocating && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[1000] bg-slate-900/80 text-white px-6 py-3 rounded-2xl flex items-center gap-3 backdrop-blur-md shadow-2xl animate-in zoom-in-90 duration-200">
            <Loader2 size={20} className="animate-spin text-emerald-400" />
            <span className="text-xs font-black uppercase tracking-widest">Buscando Posición...</span>
          </div>
        )}
      </div>

      <style>{`
        .custom-div-icon { background: none; border: none; }
        .no-scroll { overflow: hidden !important; position: fixed; width: 100%; height: 100%; }
        .leaflet-popup-content-wrapper { 
          border-radius: 16px; 
          box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1); 
          border: 1px solid #f1f5f9; 
          transition: all 0.3s ease;
        }
        .popup-glow-active .leaflet-popup-content-wrapper {
          border-color: #3b82f6;
          box-shadow: 0 0 20px rgba(59, 130, 246, 0.4), 0 20px 25px -5px rgb(0 0 0 / 0.1);
        }
        .marker-glow-active {
          animation: marker-glow-pulse 1.5s infinite alternate;
        }
        @keyframes marker-glow-pulse {
          from { box-shadow: 0 0 15px rgba(37, 99, 235, 0.4); }
          to { box-shadow: 0 0 30px rgba(37, 99, 235, 0.8); }
        }
        .leaflet-popup-tip { display: none; }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, X, ChevronRight, Zap, PlayCircle, Filter, Activity, Tag, Calendar, Lightbulb, PlusCircle, RefreshCw, CheckCircle2 } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputEmpty = input.trim().length === 0;

  // Refined validation logic: description is mandatory for both tools
  // For routes, we check if text is present. Map points are context but text is the instruction.
  const isInputValid = !isInputEmpty;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltip: isRoute 
      ? "IA Generativa aplicada al TSP (Traveling Salesman Problem) con restricciones de carga y tiempos."
      : "Base de conocimiento LOTT/ROTT actualizada para la redacción de contratos CMR y pactos legales.",
    example: isRoute 
      ? "Optimiza esta ruta de 5 paradas en el área metropolitana de Madrid para entrega prioritaria en farmacias, minimizando tiempos de retorno y km en vacío." 
      : "Cláusula de limitación de responsabilidad según CMR para transporte de productos electrónicos con valor declarado de 50.000€."
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 15);
    setShowValidationErrors(false);
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const handleSaveCurrentRoute = () => {
    if (!state.routeData || points.length === 0) return;
    setIsSaving(true);
    const newRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Ruta Optimizada ${new Date().toLocaleDateString()} - ${points.length} paradas`,
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };

    const updated = [newRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));

    setSaveSuccess(true);
    setTimeout(() => {
      setSaveSuccess(false);
      setIsSaving(false);
    }, 2000);
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      setState(prev => ({ ...prev, error: "Geolocalización no soportada por el navegador." }));
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        setExternalCenter([latitude, longitude]);

        setLoadingStage('geocoding');
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const label = data.display_name ? data.display_name.split(',')[0] : "Mi Ubicación";

          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: label
          }]);
          // Note: map points don't satisfy the "mandatory text" requirement now, 
          // but they are valid context. Text instruction remains required.
        } catch (e) {
          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: "Mi Ubicación"
          }]);
        } finally {
          setLoadingStage('idle');
        }
      },
      (error) => {
        console.error(error);
        setState(prev => ({ ...prev, error: "Error al obtener la ubicación. Por favor, revisa los permisos del navegador." }));
        setLoadingStage('idle');
      }
    );
  };

  const deleteRoute = (id: string) => {
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
  };

  const handleGenerate = async () => {
    if (!isInputValid) { 
      setShowValidationErrors(true); 
      textareaRef.current?.focus(); 
      return; 
    }
    setShowValidationErrors(false);
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');
    try {
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';
      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }
      if (isMounted.current && isRoute) {
        setLoadingStage('finalizing');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { setState(prev => ({ ...prev, isLoading: false, error: "Error de formato." })); }
      } else { setState(prev => ({ ...prev, isLoading: false })); }
      setLoadingStage('idle');

      setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (err: any) { setState({ isLoading: false, content: null, error: err.message }); setLoadingStage('idle'); }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
    return filtered.sort((a, b) => sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name));
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg relative`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900 tracking-tight">{config.title}</h3>
                <div className="relative group/info">
                  <div className="p-1 rounded-full bg-slate-100 text-slate-400 hover:text-brand-600 hover:bg-brand-50 transition-all cursor-help">
                    <Info size={14} />
                  </div>
                  <div className="absolute left-0 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/info:opacity-100 group-hover/info:visible transition-all duration-300 z-50 transform translate-y-2 group-hover/info:translate-y-0">
                    <p className="font-medium">{config.tooltip}</p>
                    <div className="absolute top-full left-4 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">{viewMode === 'form' ? `Biblioteca (${savedRoutes.length})` : 'Volver'}</span>
            </button>
          )}
        </div>

        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planes
                  </h4>
                  <div className="flex gap-2">
                    <button onClick={() => setSortBy(sortBy === 'date' ? 'name' : 'date')} className="p-2 bg-white text-slate-400 border border-slate-200 rounded-xl hover:text-brand-600 transition-colors">
                      <ChevronRight size={18} className={`transition-transform ${sortBy === 'name' ? 'rotate-90' : ''}`} />
                    </button>
                    <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl transition-all ${showFilters || startDate || endDate ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200 hover:text-brand-600'}`}>
                      <Filter size={18} />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar por nombre..." className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-brand-100" />
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="p-5 bg-white rounded-2xl border border-brand-100 shadow-xl animate-in slide-in-from-top-2 duration-300 relative">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Desde Fecha</label>
                          <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Hasta Fecha</label>
                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                      </div>
                      <div className="flex gap-2 mt-4">
                        <button onClick={resetFilters} className="flex-1 py-2.5 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 hover:text-brand-600 uppercase transition-all bg-slate-50 rounded-xl border border-slate-100">
                          <RefreshCw size={12} /> Limpiar
                        </button>
                        <button onClick={() => setShowFilters(false)} className="px-6 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-brand-500/20">Aplicar</button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                      <Search size={40} className="mb-4 opacity-20" />
                      <p className="text-sm font-medium">No se encontraron rutas.</p>
                    </div>
                  ) : (
                    processedRoutes.map((route) => (
                      <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md">
                        <div className="flex-1 min-w-0 pr-4">
                          <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                          <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                            <Calendar size={10} className="text-brand-500" /> {new Date(route.timestamp).toLocaleDateString()}
                            <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded-full">{route.points.length} paradas</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => { setPoints(route.points); setState(prev => ({ ...prev, routeData: route.routeData, content: route.explanation })); setViewMode('form'); }} 
                            className="px-4 py-2 bg-brand-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-brand-700 transition-all active:scale-95 shadow-md shadow-brand-500/10"
                          >
                            Ver
                          </button>
                          <button 
                            onClick={() => deleteRoute(route.id)}
                            className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[300px] relative rounded-3xl overflow-hidden border-2 shadow-inner transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-amber-200 bg-amber-50/10' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={(newPoints) => {
                        setPoints(newPoints);
                      }} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'}
                      onLoadingChange={(stage) => setLoadingStage(stage as any)}
                    />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button type="button" onClick={handleExampleClick} disabled={state.isLoading} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider border border-brand-100 shadow-sm active:scale-95 disabled:opacity-50">
                    <Lightbulb size={12} className="text-amber-500" /> Ver Ejemplo
                </button>
            </div>

            <div className="relative">
              <textarea 
                ref={textareaRef} 
                value={input} 
                onChange={(e) => {
                  setInput(e.target.value);
                  if (showValidationErrors && e.target.value.trim().length > 0) setShowValidationErrors(false);
                }} 
                disabled={state.isLoading} 
                rows={isRoute ? 3 : 5} 
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 outline-none transition-all resize-none shadow-inner ${showValidationErrors && isInputEmpty ? 'border-red-500 bg-red-50/30 focus:ring-red-50' : 'border-slate-100 focus:ring-brand-100 focus:border-brand-500'}`} 
                placeholder={config.placeholder} 
              />
              {showValidationErrors && isInputEmpty && (
                <p className="mt-2 text-xs font-bold text-red-500 flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} />
                  Este campo es obligatorio
                </p>
              )}
            </div>

            {(state.isLoading || loadingStage !== 'idle') && (
              <div className="mt-6 animate-pulse">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest flex items-center gap-2"><Activity size={12} /> {
                     loadingStage === 'locating' ? 'Obteniendo GPS...' : 
                     loadingStage === 'geocoding' ? 'Identificando dirección...' :
                     'Recibiendo respuesta...'
                   }</span>
                </div>
                <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className="h-full bg-brand-500 w-1/3 animate-progress rounded-full"></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={state.isLoading || loadingStage !== 'idle'} className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98]`}>
                {(state.isLoading || loadingStage !== 'idle') ? <Loader2 className="animate-spin" size={22} /> : <Zap size={22} />}
                <span>{(state.isLoading || loadingStage !== 'idle') ? 'Analizando...' : 'Optimizar con IA'}</span>
              </button>
            </div>
          </div>
        )}

        <div ref={resultRef} className={`scroll-mt-24 transition-all duration-500 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className="mt-10 rounded-3xl border border-slate-200 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-10 duration-700">
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><Clock size={16} className="text-brand-500" /></div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Estratégico AI</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {isRoute && !saveSuccess && (
                        <button 
                          onClick={handleSaveCurrentRoute}
                          disabled={isSaving}
                          className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-50"
                        >
                          {isSaving ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
                          Guardar Ruta
                        </button>
                      )}
                      {saveSuccess && (
                        <div className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-xl text-[10px] font-black uppercase tracking-widest animate-in zoom-in-95 duration-300">
                          <CheckCircle2 size={14} /> Guardada
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm bg-white/60 p-8 rounded-3xl border border-white shadow-inner">{state.content}</div>
                  </div>
                  <div className="mt-6 flex justify-end">
                    <button 
                      onClick={handleCopy}
                      className={`flex items-center gap-2 text-[10px] font-black uppercase transition-all px-4 py-2 rounded-xl border ${isCopied ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'text-slate-400 border-slate-100 hover:text-brand-600 hover:bg-white hover:shadow-sm'}`}
                    >
                      {isCopied ? <Check size={14} className="animate-in zoom-in-50" /> : <Copy size={14} />}
                      {isCopied ? '¡Copiado!' : 'Copiar al Portapapeles'}
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, X, ChevronRight, Zap, PlayCircle, Filter, Activity, Tag, Calendar, Lightbulb, PlusCircle, RefreshCw, CheckCircle2, Navigation, Map as MapIcon, Database, Cpu } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding' | 'calculating';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputEmpty = input.trim().length === 0;

  // Refined validation logic: description is mandatory for both tools
  const isInputValid = !isInputEmpty;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltip: isRoute 
      ? "IA Generativa aplicada al TSP (Traveling Salesman Problem) con restricciones de carga y tiempos."
      : "Base de conocimiento LOTT/ROTT actualizada para la redacción de contratos CMR y pactos legales.",
    example: isRoute 
      ? "Optimiza esta ruta de 5 paradas en el área metropolitana de Madrid para entrega prioritaria en farmacias, minimizando tiempos de retorno y km en vacío." 
      : "Cláusula de limitación de responsabilidad según CMR para transporte de productos electrónicos con valor declarado de 50.000€."
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'locating': return { text: 'Accediendo a sensores GPS...', icon: <Navigation size={12} className="text-emerald-500" /> };
      case 'geocoding': return { text: 'Buscando coordenadas exactas...', icon: <Search size={12} className="text-blue-500" /> };
      case 'validating': return { text: 'Verificando parámetros de entrada...', icon: <Check size={12} className="text-brand-500" /> };
      case 'connecting': return { text: 'Conectando con Motor Logístico AI...', icon: <Database size={12} className="text-purple-500" /> };
      case 'streaming': return { text: 'Generando informe estratégico...', icon: <Sparkles size={12} className="text-amber-500" /> };
      case 'finalizing': return { text: 'Dibujando trazado en el mapa...', icon: <MapIcon size={12} className="text-emerald-500" /> };
      case 'calculating': return { text: 'Calculando eficiencia de ruta...', icon: <Cpu size={12} className="text-brand-500" /> };
      default: return { text: 'Procesando datos...', icon: <Activity size={12} className="text-brand-600" /> };
    }
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 15);
    setShowValidationErrors(false);
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const handleSaveCurrentRoute = () => {
    if (!state.routeData || points.length === 0) return;
    setIsSaving(true);
    const newRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Ruta Optimizada ${new Date().toLocaleDateString()} - ${points.length} paradas`,
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };

    const updated = [newRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));

    setSaveSuccess(true);
    setTimeout(() => {
      setSaveSuccess(false);
      setIsSaving(false);
    }, 2000);
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      setState(prev => ({ ...prev, error: "Geolocalización no soportada por el navegador." }));
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        setExternalCenter([latitude, longitude]);

        setLoadingStage('geocoding');
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const label = data.display_name ? data.display_name.split(',')[0] : "Mi Ubicación";

          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: label
          }]);
        } catch (e) {
          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: "Mi Ubicación"
          }]);
        } finally {
          setLoadingStage('idle');
        }
      },
      (error) => {
        console.error(error);
        setState(prev => ({ ...prev, error: "Error al obtener la ubicación. Por favor, revisa los permisos del navegador." }));
        setLoadingStage('idle');
      }
    );
  };

  const deleteRoute = (id: string) => {
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
  };

  const handleGenerate = async () => {
    if (!isInputValid) { 
      setShowValidationErrors(true); 
      textareaRef.current?.focus(); 
      return; 
    }
    setShowValidationErrors(false);
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');

    try {
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current && isRoute) {
        setLoadingStage('calculating');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setLoadingStage('finalizing');
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error de formato." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');

      setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
    return filtered.sort((a, b) => sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name));
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;
  const loadingInfo = getLoadingMessage();

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg relative`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900 tracking-tight">{config.title}</h3>
                <div className="relative group/info">
                  <div className="p-1 rounded-full bg-slate-100 text-slate-400 hover:text-brand-600 hover:bg-brand-50 transition-all cursor-help">
                    <Info size={14} />
                  </div>
                  <div className="absolute left-0 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/info:opacity-100 group-hover/info:visible transition-all duration-300 z-50 transform translate-y-2 group-hover/info:translate-y-0">
                    <p className="font-medium">{config.tooltip}</p>
                    <div className="absolute top-full left-4 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">{viewMode === 'form' ? `Biblioteca (${savedRoutes.length})` : 'Volver'}</span>
            </button>
          )}
        </div>

        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planes
                  </h4>
                  <div className="flex gap-2">
                    <button onClick={() => setSortBy(sortBy === 'date' ? 'name' : 'date')} className="p-2 bg-white text-slate-400 border border-slate-200 rounded-xl hover:text-brand-600 transition-colors">
                      <ChevronRight size={18} className={`transition-transform ${sortBy === 'name' ? 'rotate-90' : ''}`} />
                    </button>
                    <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl transition-all ${showFilters || startDate || endDate ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200 hover:text-brand-600'}`}>
                      <Filter size={18} />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar por nombre..." className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-brand-100" />
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="p-5 bg-white rounded-2xl border border-brand-100 shadow-xl animate-in slide-in-from-top-2 duration-300 relative">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Desde Fecha</label>
                          <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Hasta Fecha</label>
                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                      </div>
                      <div className="flex gap-2 mt-4">
                        <button onClick={resetFilters} className="flex-1 py-2.5 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 hover:text-brand-600 uppercase transition-all bg-slate-50 rounded-xl border border-slate-100">
                          <RefreshCw size={12} /> Limpiar
                        </button>
                        <button onClick={() => setShowFilters(false)} className="px-6 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-brand-500/20">Aplicar</button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                      <Search size={40} className="mb-4 opacity-20" />
                      <p className="text-sm font-medium">No se encontraron rutas.</p>
                    </div>
                  ) : (
                    processedRoutes.map((route) => (
                      <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md">
                        <div className="flex-1 min-w-0 pr-4">
                          <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                          <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                            <Calendar size={10} className="text-brand-500" /> {new Date(route.timestamp).toLocaleDateString()}
                            <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded-full">{route.points.length} paradas</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => { setPoints(route.points); setState(prev => ({ ...prev, routeData: route.routeData, content: route.explanation })); setViewMode('form'); }} 
                            className="px-4 py-2 bg-brand-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-brand-700 transition-all active:scale-95 shadow-md shadow-brand-500/10"
                          >
                            Ver
                          </button>
                          <button 
                            onClick={() => deleteRoute(route.id)}
                            className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[300px] relative rounded-3xl overflow-hidden border-2 shadow-inner transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-amber-200 bg-amber-50/10' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={(newPoints) => {
                        setPoints(newPoints);
                      }} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'}
                      onLoadingChange={(stage) => setLoadingStage(stage as any)}
                    />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button type="button" onClick={handleExampleClick} disabled={state.isLoading} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider border border-brand-100 shadow-sm active:scale-95 disabled:opacity-50">
                    <Lightbulb size={12} className="text-amber-500" /> Ver Ejemplo
                </button>
            </div>

            <div className="relative">
              <textarea 
                ref={textareaRef} 
                value={input} 
                onChange={(e) => {
                  setInput(e.target.value);
                  if (showValidationErrors && e.target.value.trim().length > 0) setShowValidationErrors(false);
                }} 
                disabled={state.isLoading} 
                rows={isRoute ? 3 : 5} 
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 outline-none transition-all resize-none shadow-inner ${showValidationErrors && isInputEmpty ? 'border-red-500 bg-red-50/30 focus:ring-red-50' : 'border-slate-100 focus:ring-brand-100 focus:border-brand-500'}`} 
                placeholder={config.placeholder} 
              />
              {showValidationErrors && isInputEmpty && (
                <p className="mt-2 text-xs font-bold text-red-500 flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} />
                  Este campo es obligatorio
                </p>
              )}
            </div>

            {(state.isLoading || loadingStage !== 'idle') && (
              <div className="mt-6 animate-in fade-in duration-300">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-[0.1em] flex items-center gap-2">
                     <span className="animate-spin">{loadingInfo.icon}</span>
                     {loadingInfo.text}
                   </span>
                </div>
                <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className={`h-full bg-brand-500 transition-all duration-700 rounded-full ${loadingStage === 'streaming' ? 'w-2/3 animate-pulse' : 'w-1/3 animate-progress'}`}></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={state.isLoading || loadingStage !== 'idle'} className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98]`}>
                {(state.isLoading || loadingStage !== 'idle') ? <Loader2 className="animate-spin" size={22} /> : <Zap size={22} />}
                <span>{(state.isLoading || loadingStage !== 'idle') ? 'Procesando...' : 'Optimizar con IA'}</span>
              </button>
            </div>
          </div>
        )}

        <div ref={resultRef} className={`scroll-mt-24 transition-all duration-500 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className="mt-10 rounded-3xl border border-slate-200 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-10 duration-700">
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><Clock size={16} className="text-brand-500" /></div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Estratégico AI</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {isRoute && !saveSuccess && (
                        <button 
                          onClick={handleSaveCurrentRoute}
                          disabled={isSaving}
                          className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-50"
                        >
                          {isSaving ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
                          Guardar Ruta
                        </button>
                      )}
                      {saveSuccess && (
                        <div className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-xl text-[10px] font-black uppercase tracking-widest animate-in zoom-in-95 duration-300">
                          <CheckCircle2 size={14} /> Guardada
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm bg-white/60 p-8 rounded-3xl border border-white shadow-inner">{state.content}</div>
                  </div>
                  <div className="mt-6 flex justify-end">
                    <button 
                      onClick={handleCopy}
                      className={`flex items-center gap-2 text-[10px] font-black uppercase transition-all px-4 py-2 rounded-xl border ${isCopied ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'text-slate-400 border-slate-100 hover:text-brand-600 hover:bg-white hover:shadow-sm'}`}
                    >
                      {isCopied ? <Check size={14} className="animate-in zoom-in-50" /> : <Copy size={14} />}
                      {isCopied ? '¡Copiado!' : 'Copiar al Portapapeles'}
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, X, ChevronRight, Zap, Filter, Activity, Calendar, Lightbulb, RefreshCw, CheckCircle2, Navigation, Map as MapIcon, Database, Cpu } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding' | 'calculating';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [shake, setShake] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputEmpty = input.trim().length === 0;
  const isInputValid = !isInputEmpty;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltip: isRoute 
      ? "IA Generativa aplicada al TSP (Traveling Salesman Problem) con restricciones de carga y tiempos."
      : "Base de conocimiento LOTT/ROTT actualizada para la redacción de contratos CMR y pactos legales.",
    example: isRoute 
      ? "Optimiza esta ruta de 5 paradas en el área metropolitana de Madrid para entrega prioritaria en farmacias, minimizando tiempos de retorno y km en vacío." 
      : "Cláusula de limitación de responsabilidad según CMR para transporte de productos electrónicos con valor declarado de 50.000€."
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'locating': return { text: 'Accediendo a sensores GPS...', icon: <Navigation size={12} className="text-emerald-500" /> };
      case 'geocoding': return { text: 'Buscando coordenadas exactas...', icon: <Search size={12} className="text-blue-500" /> };
      case 'validating': return { text: 'Verificando parámetros de entrada...', icon: <Check size={12} className="text-brand-500" /> };
      case 'connecting': return { text: 'Conectando con Motor Logístico AI...', icon: <Database size={12} className="text-purple-500" /> };
      case 'streaming': return { text: 'Generando informe estratégico...', icon: <Sparkles size={12} className="text-amber-500" /> };
      case 'finalizing': return { text: 'Dibujando trazado en el mapa...', icon: <MapIcon size={12} className="text-emerald-500" /> };
      case 'calculating': return { text: 'Calculando eficiencia de ruta...', icon: <Cpu size={12} className="text-brand-500" /> };
      default: return { text: 'Procesando datos...', icon: <Activity size={12} className="text-brand-600" /> };
    }
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 15);
    setShowValidationErrors(false);
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const handleSaveCurrentRoute = () => {
    if (!state.routeData || points.length === 0) return;
    setIsSaving(true);
    const newRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Ruta Optimizada ${new Date().toLocaleDateString()} - ${points.length} paradas`,
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };

    const updated = [newRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));

    setSaveSuccess(true);
    setTimeout(() => {
      setSaveSuccess(false);
      setIsSaving(false);
    }, 2000);
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      setState(prev => ({ ...prev, error: "Geolocalización no soportada por el navegador." }));
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        setExternalCenter([latitude, longitude]);

        setLoadingStage('geocoding');
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const label = data.display_name ? data.display_name.split(',')[0] : "Mi Ubicación";

          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: label
          }]);
        } catch (e) {
          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: "Mi Ubicación"
          }]);
        } finally {
          setLoadingStage('idle');
        }
      },
      (error) => {
        console.error(error);
        setState(prev => ({ ...prev, error: "Error al obtener la ubicación. Por favor, revisa los permisos del navegador." }));
        setLoadingStage('idle');
      }
    );
  };

  const deleteRoute = (id: string) => {
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
  };

  const handleGenerate = async () => {
    if (!isInputValid) { 
      setShowValidationErrors(true);
      setShake(true);
      setTimeout(() => setShake(false), 500);
      textareaRef.current?.focus(); 
      return; 
    }

    setShowValidationErrors(false);
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');

    try {
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current && isRoute) {
        setLoadingStage('calculating');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setLoadingStage('finalizing');
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error de formato." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');

      setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
    return filtered.sort((a, b) => sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name));
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;
  const loadingInfo = getLoadingMessage();

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg relative`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900 tracking-tight">{config.title}</h3>
                <div className="relative group/info">
                  <div className="p-1 rounded-full bg-slate-100 text-slate-400 hover:text-brand-600 hover:bg-brand-50 transition-all cursor-help">
                    <Info size={14} />
                  </div>
                  <div className="absolute left-0 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/info:opacity-100 group-hover/info:visible transition-all duration-300 z-50 transform translate-y-2 group-hover/info:translate-y-0">
                    <p className="font-medium">{config.tooltip}</p>
                    <div className="absolute top-full left-4 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">{viewMode === 'form' ? `Biblioteca (${savedRoutes.length})` : 'Volver'}</span>
            </button>
          )}
        </div>

        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planes
                  </h4>
                  <div className="flex gap-2">
                    <button onClick={() => setSortBy(sortBy === 'date' ? 'name' : 'date')} className="p-2 bg-white text-slate-400 border border-slate-200 rounded-xl hover:text-brand-600 transition-colors">
                      <ChevronRight size={18} className={`transition-transform ${sortBy === 'name' ? 'rotate-90' : ''}`} />
                    </button>
                    <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl transition-all ${showFilters || startDate || endDate ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200 hover:text-brand-600'}`}>
                      <Filter size={18} />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar por nombre..." className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-brand-100" />
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="p-5 bg-white rounded-2xl border border-brand-100 shadow-xl animate-in slide-in-from-top-2 duration-300 relative">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Desde Fecha</label>
                          <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Hasta Fecha</label>
                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                      </div>
                      <div className="flex gap-2 mt-4">
                        <button onClick={resetFilters} className="flex-1 py-2.5 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 hover:text-brand-600 uppercase transition-all bg-slate-50 rounded-xl border border-slate-100">
                          <RefreshCw size={12} /> Limpiar
                        </button>
                        <button onClick={() => setShowFilters(false)} className="px-6 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-brand-500/20">Aplicar</button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                      <Search size={40} className="mb-4 opacity-20" />
                      <p className="text-sm font-medium">No se encontraron rutas.</p>
                    </div>
                  ) : (
                    processedRoutes.map((route) => (
                      <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md">
                        <div className="flex-1 min-w-0 pr-4">
                          <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                          <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                            <Calendar size={10} className="text-brand-500" /> {new Date(route.timestamp).toLocaleDateString()}
                            <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded-full">{route.points.length} paradas</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => { setPoints(route.points); setState(prev => ({ ...prev, routeData: route.routeData, content: route.explanation })); setViewMode('form'); }} 
                            className="px-4 py-2 bg-brand-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-brand-700 transition-all active:scale-95 shadow-md shadow-brand-500/10"
                          >
                            Ver
                          </button>
                          <button 
                            onClick={() => deleteRoute(route.id)}
                            className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[300px] relative rounded-3xl overflow-hidden border-2 shadow-inner transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-amber-200 bg-amber-50/10' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={(newPoints) => {
                        setPoints(newPoints);
                      }} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'}
                      onLoadingChange={(stage) => setLoadingStage(stage as any)}
                    />
                </div>
            )}

            <div className="flex justify-end mb-2">
                <button type="button" onClick={handleExampleClick} disabled={state.isLoading} className="text-[10px] font-bold text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-2 rounded-lg transition-all flex items-center gap-2 uppercase tracking-wider border border-brand-100 shadow-sm active:scale-95 disabled:opacity-50">
                    <Lightbulb size={12} className="text-amber-500" /> Ver Ejemplo
                </button>
            </div>

            <div className={`relative transition-transform ${shake ? 'animate-shake' : ''}`}>
              <textarea 
                ref={textareaRef} 
                value={input} 
                onChange={(e) => {
                  setInput(e.target.value);
                  if (showValidationErrors && e.target.value.trim().length > 0) setShowValidationErrors(false);
                }} 
                disabled={state.isLoading} 
                rows={isRoute ? 3 : 5} 
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 outline-none transition-all resize-none shadow-inner ${showValidationErrors && isInputEmpty ? 'border-red-500 bg-red-50/30 focus:ring-red-50' : 'border-slate-100 focus:ring-brand-100 focus:border-brand-500'}`} 
                placeholder={config.placeholder} 
              />
              {showValidationErrors && isInputEmpty && (
                <p className="mt-2 text-xs font-bold text-red-600 flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} className="animate-pulse" />
                  Este campo es obligatorio
                </p>
              )}
            </div>

            {(state.isLoading || loadingStage !== 'idle') && (
              <div className="mt-6 animate-in fade-in duration-300">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-[0.1em] flex items-center gap-2">
                     <span className="animate-spin">{loadingInfo.icon}</span>
                     {loadingInfo.text}
                   </span>
                </div>
                <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className={`h-full bg-brand-500 transition-all duration-700 rounded-full ${loadingStage === 'streaming' ? 'w-2/3 animate-pulse' : 'w-1/3 animate-progress'}`}></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={state.isLoading || loadingStage !== 'idle'} className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98]`}>
                {(state.isLoading || loadingStage !== 'idle') ? <Loader2 className="animate-spin" size={22} /> : <Zap size={22} />}
                <span>{(state.isLoading || loadingStage !== 'idle') ? 'Procesando...' : 'Optimizar con IA'}</span>
              </button>
            </div>
          </div>
        )}

        <div ref={resultRef} className={`scroll-mt-24 transition-all duration-500 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className="mt-10 rounded-3xl border border-slate-200 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-10 duration-700">
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><Clock size={16} className="text-brand-500" /></div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Estratégico AI</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {isRoute && !saveSuccess && (
                        <button 
                          onClick={handleSaveCurrentRoute}
                          disabled={isSaving}
                          className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-50"
                        >
                          {isSaving ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
                          Guardar Ruta
                        </button>
                      )}
                      {saveSuccess && (
                        <div className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-xl text-[10px] font-black uppercase tracking-widest animate-in zoom-in-95 duration-300">
                          <CheckCircle2 size={14} /> Guardada
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm bg-white/60 p-8 rounded-3xl border border-white shadow-inner">{state.content}</div>
                  </div>
                  <div className="mt-6 flex justify-end">
                    <button 
                      onClick={handleCopy}
                      className={`flex items-center gap-2 text-[10px] font-black uppercase transition-all px-4 py-2 rounded-xl border ${isCopied ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'text-slate-400 border-slate-100 hover:text-brand-600 hover:bg-white hover:shadow-sm'}`}
                    >
                      {isCopied ? <Check size={14} className="animate-in zoom-in-50" /> : <Copy size={14} />}
                      {isCopied ? '¡Copiado!' : 'Copiar al Portapapeles'}
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          50% { transform: translateX(5px); }
          75% { transform: translateX(-5px); }
        }
        .animate-shake {
          animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, X, ChevronRight, Zap, Filter, Activity, Calendar, Lightbulb, RefreshCw, CheckCircle2, Navigation, Map as MapIcon, Database, Cpu } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'connecting' | 'streaming' | 'finalizing' | 'locating' | 'geocoding' | 'calculating';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [shake, setShake] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputEmpty = input.trim().length === 0;
  const isInputValid = !isInputEmpty;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltip: isRoute 
      ? "IA Generativa aplicada al TSP (Traveling Salesman Problem) con restricciones de carga y tiempos."
      : "Base de conocimiento LOTT/ROTT actualizada para la redacción de contratos CMR y pactos legales.",
    example: isRoute 
      ? "Optimiza esta ruta de 5 paradas en el área metropolitana de Madrid para entrega prioritaria en farmacias, minimizando tiempos de retorno y km en vacío." 
      : "Redacta una cláusula de limitación de responsabilidad según CMR para transporte de productos electrónicos con valor declarado de 50.000€."
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'locating': return { text: 'Accediendo a sensores GPS...', icon: <Navigation size={12} className="text-emerald-500" /> };
      case 'geocoding': return { text: 'Buscando coordenadas exactas...', icon: <Search size={12} className="text-blue-500" /> };
      case 'validating': return { text: 'Verificando parámetros de entrada...', icon: <Check size={12} className="text-brand-500" /> };
      case 'connecting': return { text: 'Conectando con Motor Logístico AI...', icon: <Database size={12} className="text-purple-500" /> };
      case 'streaming': return { text: 'Generando informe estratégico...', icon: <Sparkles size={12} className="text-amber-500" /> };
      case 'finalizing': return { text: 'Dibujando trazado en el mapa...', icon: <MapIcon size={12} className="text-emerald-500" /> };
      case 'calculating': return { text: 'Calculando eficiencia de ruta...', icon: <Cpu size={12} className="text-brand-500" /> };
      default: return { text: 'Procesando datos...', icon: <Activity size={12} className="text-brand-600" /> };
    }
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 12);
    setShowValidationErrors(false);
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const handleSaveCurrentRoute = () => {
    if (!state.routeData || points.length === 0) return;
    setIsSaving(true);
    const newRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Ruta Optimizada ${new Date().toLocaleDateString()} - ${points.length} paradas`,
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };

    const updated = [newRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));

    setSaveSuccess(true);
    setTimeout(() => {
      setSaveSuccess(false);
      setIsSaving(false);
    }, 2000);
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      setState(prev => ({ ...prev, error: "Geolocalización no soportada por el navegador." }));
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        setExternalCenter([latitude, longitude]);

        setLoadingStage('geocoding');
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const label = data.display_name ? data.display_name.split(',')[0] : "Mi Ubicación";

          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: label
          }]);
        } catch (e) {
          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: "Mi Ubicación"
          }]);
        } finally {
          setLoadingStage('idle');
        }
      },
      (error) => {
        console.error(error);
        setState(prev => ({ ...prev, error: "Error al obtener la ubicación. Por favor, revisa los permisos del navegador." }));
        setLoadingStage('idle');
      }
    );
  };

  const deleteRoute = (id: string) => {
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
  };

  const handleGenerate = async () => {
    if (!isInputValid) { 
      setShowValidationErrors(true);
      setShake(true);
      setTimeout(() => setShake(false), 500);
      textareaRef.current?.focus(); 
      return; 
    }

    setShowValidationErrors(false);
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');

    try {
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current && isRoute) {
        setLoadingStage('calculating');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setLoadingStage('finalizing');
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error de formato." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');

      setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
    return filtered.sort((a, b) => sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name));
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;
  const loadingInfo = getLoadingMessage();

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg relative`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900 tracking-tight">{config.title}</h3>
                <div className="relative group/info">
                  <div className="p-1 rounded-full bg-slate-100 text-slate-400 hover:text-brand-600 hover:bg-brand-50 transition-all cursor-help">
                    <Info size={14} />
                  </div>
                  <div className="absolute left-0 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/info:opacity-100 group-hover/info:visible transition-all duration-300 z-50 transform translate-y-2 group-hover/info:translate-y-0">
                    <p className="font-medium">{config.tooltip}</p>
                    <div className="absolute top-full left-4 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">{viewMode === 'form' ? `Biblioteca (${savedRoutes.length})` : 'Volver'}</span>
            </button>
          )}
        </div>

        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planes
                  </h4>
                  <div className="flex gap-2">
                    <button onClick={() => setSortBy(sortBy === 'date' ? 'name' : 'date')} className="p-2 bg-white text-slate-400 border border-slate-200 rounded-xl hover:text-brand-600 transition-colors">
                      <ChevronRight size={18} className={`transition-transform ${sortBy === 'name' ? 'rotate-90' : ''}`} />
                    </button>
                    <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl transition-all ${showFilters || startDate || endDate ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200 hover:text-brand-600'}`}>
                      <Filter size={18} />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar por nombre..." className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-brand-100" />
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="p-5 bg-white rounded-2xl border border-brand-100 shadow-xl animate-in slide-in-from-top-2 duration-300 relative">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Desde Fecha</label>
                          <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Hasta Fecha</label>
                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                      </div>
                      <div className="flex gap-2 mt-4">
                        <button onClick={resetFilters} className="flex-1 py-2.5 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 hover:text-brand-600 uppercase transition-all bg-slate-50 rounded-xl border border-slate-100">
                          <RefreshCw size={12} /> Limpiar
                        </button>
                        <button onClick={() => setShowFilters(false)} className="px-6 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-brand-500/20">Aplicar</button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                      <Search size={40} className="mb-4 opacity-20" />
                      <p className="text-sm font-medium">No se encontraron rutas.</p>
                    </div>
                  ) : (
                    processedRoutes.map((route) => (
                      <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md">
                        <div className="flex-1 min-w-0 pr-4">
                          <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                          <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                            <Calendar size={10} className="text-brand-500" /> {new Date(route.timestamp).toLocaleDateString()}
                            <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded-full">{route.points.length} paradas</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => { setPoints(route.points); setState(prev => ({ ...prev, routeData: route.routeData, content: route.explanation })); setViewMode('form'); }} 
                            className="px-4 py-2 bg-brand-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-brand-700 transition-all active:scale-95 shadow-md shadow-brand-500/10"
                          >
                            Ver
                          </button>
                          <button 
                            onClick={() => deleteRoute(route.id)}
                            className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[300px] relative rounded-3xl overflow-hidden border-2 shadow-inner transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-amber-200 bg-amber-50/10' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={(newPoints) => {
                        setPoints(newPoints);
                      }} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'}
                      onLoadingChange={(stage) => setLoadingStage(stage as any)}
                    />
                </div>
            )}

            <div className="flex items-end justify-between mb-2 px-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Instrucciones AI</label>
                <button 
                  type="button" 
                  onClick={handleExampleClick} 
                  disabled={state.isLoading} 
                  className="group flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 border border-slate-200 text-slate-600 text-[10px] font-black uppercase tracking-widest transition-all hover:bg-white hover:border-brand-300 hover:text-brand-600 active:scale-95 disabled:opacity-50"
                >
                    <Lightbulb size={12} className="text-amber-500 group-hover:scale-110 transition-transform" />
                    Ver Ejemplo
                </button>
            </div>

            <div className={`relative transition-transform ${shake ? 'animate-shake' : ''}`}>
              <textarea 
                ref={textareaRef} 
                value={input} 
                onChange={(e) => {
                  setInput(e.target.value);
                  if (showValidationErrors && e.target.value.trim().length > 0) setShowValidationErrors(false);
                }} 
                disabled={state.isLoading} 
                rows={isRoute ? 3 : 5} 
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 outline-none transition-all resize-none shadow-inner ${showValidationErrors && isInputEmpty ? 'border-red-500 bg-red-50/30 focus:ring-red-50' : 'border-slate-100 focus:ring-brand-100 focus:border-brand-500'}`} 
                placeholder={config.placeholder} 
              />
              {showValidationErrors && isInputEmpty && (
                <p className="mt-2 text-xs font-bold text-red-600 flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} className="animate-pulse" />
                  Este campo es obligatorio
                </p>
              )}
            </div>

            {(state.isLoading || loadingStage !== 'idle') && (
              <div className="mt-6 animate-in fade-in duration-300">
                <div className="flex items-center justify-between mb-2">
                   <span className="text-[10px] font-black text-brand-600 uppercase tracking-[0.1em] flex items-center gap-2">
                     <span className="animate-spin">{loadingInfo.icon}</span>
                     {loadingInfo.text}
                   </span>
                </div>
                <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                   <div className={`h-full bg-brand-500 transition-all duration-700 rounded-full ${loadingStage === 'streaming' ? 'w-2/3 animate-pulse' : 'w-1/3 animate-progress'}`}></div>
                </div>
              </div>
            )}

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={state.isLoading || loadingStage !== 'idle'} className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98]`}>
                {(state.isLoading || loadingStage !== 'idle') ? <Loader2 className="animate-spin" size={22} /> : <Zap size={22} />}
                <span>{(state.isLoading || loadingStage !== 'idle') ? 'Procesando...' : 'Optimizar con IA'}</span>
              </button>
            </div>
          </div>
        )}

        <div ref={resultRef} className={`scroll-mt-24 transition-all duration-500 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className="mt-10 rounded-3xl border border-slate-200 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-10 duration-700">
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><Clock size={16} className="text-brand-500" /></div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Estratégico AI</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {isRoute && !saveSuccess && (
                        <button 
                          onClick={handleSaveCurrentRoute}
                          disabled={isSaving}
                          className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-50"
                        >
                          {isSaving ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
                          Guardar Ruta
                        </button>
                      )}
                      {saveSuccess && (
                        <div className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-xl text-[10px] font-black uppercase tracking-widest animate-in zoom-in-95 duration-300">
                          <CheckCircle2 size={14} /> Guardada
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm bg-white/60 p-8 rounded-3xl border border-white shadow-inner">{state.content}</div>
                  </div>
                  <div className="mt-6 flex justify-end">
                    <button 
                      onClick={handleCopy}
                      className={`flex items-center gap-2 text-[10px] font-black uppercase transition-all px-4 py-2 rounded-xl border ${isCopied ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'text-slate-400 border-slate-100 hover:text-brand-600 hover:bg-white hover:shadow-sm'}`}
                    >
                      {isCopied ? <Check size={14} className="animate-in zoom-in-50" /> : <Copy size={14} />}
                      {isCopied ? '¡Copiado!' : 'Copiar al Portapapeles'}
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          50% { transform: translateX(5px); }
          75% { transform: translateX(-5px); }
        }
        .animate-shake {
          animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Sparkles, MapPin, FileText, Loader2, Copy, Check, Info, Clock, Save, History, Trash2, FolderOpen, AlertCircle, Search, X, ChevronRight, Zap, Filter, Activity, Calendar, Lightbulb, RefreshCw, CheckCircle2, Navigation, Map as MapIcon, Database, Cpu, Layers } from 'lucide-react';
import { ToolType, GeneratedContentState, MapPoint, RouteResponse, SavedRoute } from '../types';
import { generateLogisticsResponse } from '../services/geminiService';
import { LogisticsMap } from './LogisticsMap';

interface AIToolCardProps {
  type: ToolType;
}

type LoadingStage = 'idle' | 'validating' | 'locating' | 'geocoding' | 'connecting' | 'thinking' | 'streaming' | 'parsing' | 'calculating' | 'finalizing';
type SortOption = 'date' | 'name';
type ViewMode = 'form' | 'library';

export const AIToolCard: React.FC<AIToolCardProps> = ({ type }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('form');
  const [input, setInput] = useState('');
  const [points, setPoints] = useState<MapPoint[]>([]);
  const [externalCenter, setExternalCenter] = useState<[number, number] | undefined>(undefined);
  const [loadingStage, setLoadingStage] = useState<LoadingStage>('idle');
  const [showValidationErrors, setShowValidationErrors] = useState(false);
  const [shake, setShake] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [state, setState] = useState<GeneratedContentState>({
    isLoading: false,
    content: null,
    error: null,
    routeData: undefined
  });

  const [savedRoutes, setSavedRoutes] = useState<SavedRoute[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const resultRef = useRef<HTMLDivElement>(null);
  const isMounted = useRef(true);

  const resetFilters = () => {
    setSearchQuery('');
    setStartDate('');
    setEndDate('');
    setShowFilters(false);
  };

  const isRoute = type === ToolType.ROUTE;
  const hasMinPoints = points.length >= 2;
  const isInputEmpty = input.trim().length === 0;
  const isInputValid = !isInputEmpty;

  useEffect(() => {
    if (type === ToolType.ROUTE) {
      const stored = localStorage.getItem('logistics_saved_routes');
      if (stored) {
        try { setSavedRoutes(JSON.parse(stored)); } catch (e) { console.error(e); }
      }
    }
    return () => { isMounted.current = false; };
  }, [type]);

  const config = {
    title: isRoute ? 'Planificador de Rutas' : 'Generador Legal',
    icon: isRoute ? MapPin : FileText,
    bgColor: isRoute ? 'bg-brand-600' : 'bg-purple-600',
    lightBg: isRoute ? 'bg-brand-50' : 'bg-purple-50',
    borderColor: isRoute ? 'border-brand-200' : 'border-purple-200',
    buttonColor: isRoute ? 'bg-brand-600 hover:bg-brand-700' : 'bg-purple-600 hover:bg-purple-700',
    placeholder: isRoute ? 'O describe tu ruta: "Reparto zona norte, 5 paradas..."' : 'Ej: Contrato de transporte, cláusulas LOTT...',
    description: isRoute ? 'Optimiza secuencias de entrega usando mapa y IA.' : 'Redacta cláusulas y contratos basados en normativa.',
    tooltip: isRoute 
      ? "IA Generativa aplicada al TSP (Traveling Salesman Problem) con restricciones de carga y tiempos."
      : "Base de conocimiento LOTT/ROTT actualizada para la redacción de contratos CMR y pactos legales.",
    example: isRoute 
      ? "Optimiza esta ruta de 5 paradas en el área metropolitana de Madrid para entrega prioritaria en farmacias, minimizando tiempos de retorno y km en vacío." 
      : "Redacta una cláusula de limitación de responsabilidad según CMR para transporte de productos electrónicos con valor declarado de 50.000€."
  };

  const getLoadingMessage = () => {
    switch (loadingStage) {
      case 'locating': return { text: 'Accediendo a sensores GPS...', icon: <Navigation size={12} className="text-emerald-500" />, progress: 20 };
      case 'geocoding': return { text: 'Buscando coordenadas exactas...', icon: <Search size={12} className="text-blue-500" />, progress: 40 };
      case 'validating': return { text: 'Verificando parámetros y contexto...', icon: <Check size={12} className="text-brand-500" />, progress: 10 };
      case 'connecting': return { text: 'Conectando con Motor Logístico AI...', icon: <Database size={12} className="text-purple-500" />, progress: 25 };
      case 'thinking': return { text: 'La IA está razonando la solución...', icon: <Sparkles size={12} className="text-amber-500" />, progress: 45 };
      case 'streaming': return { text: 'Recibiendo informe estratégico...', icon: <Activity size={12} className="text-brand-600" />, progress: 70 };
      case 'parsing': return { text: 'Interpretando datos estructurados...', icon: <Layers size={12} className="text-indigo-500" />, progress: 85 };
      case 'calculating': return { text: 'Calculando eficiencia de ruta...', icon: <Cpu size={12} className="text-brand-500" />, progress: 90 };
      case 'finalizing': return { text: 'Dibujando trazado en el mapa...', icon: <MapIcon size={12} className="text-emerald-500" />, progress: 98 };
      default: return { text: 'Procesando...', icon: <Activity size={12} className="text-brand-600" />, progress: 50 };
    }
  };

  const handleExampleClick = () => {
    const text = config.example;
    setInput('');
    let i = 0;
    const interval = setInterval(() => {
      if (i < text.length) {
        setInput(text.substring(0, i + 1));
        i++;
      } else {
        clearInterval(interval);
      }
    }, 12);
    setShowValidationErrors(false);
  };

  const handleCopy = () => {
    if (state.content) {
      navigator.clipboard.writeText(state.content);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const handleSaveCurrentRoute = () => {
    if (!state.routeData || points.length === 0) return;
    setIsSaving(true);
    const newRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Ruta Optimizada ${new Date().toLocaleDateString()} - ${points.length} paradas`,
      timestamp: Date.now(),
      points: [...points],
      routeData: [...state.routeData],
      explanation: state.content || ''
    };

    const updated = [newRoute, ...savedRoutes];
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));

    setSaveSuccess(true);
    setTimeout(() => {
      setSaveSuccess(false);
      setIsSaving(false);
    }, 2000);
  };

  const handleAddCurrentLocation = () => {
    if (!navigator.geolocation) {
      setState(prev => ({ ...prev, error: "Geolocalización no soportada por el navegador." }));
      return;
    }

    setLoadingStage('locating');
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        setExternalCenter([latitude, longitude]);

        setLoadingStage('geocoding');
        try {
          const resp = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
          const data = await resp.json();
          const label = data.display_name ? data.display_name.split(',')[0] : "Mi Ubicación";

          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: label
          }]);
        } catch (e) {
          setPoints(prev => [...prev, {
            lat: latitude,
            lng: longitude,
            id: `loc-${Date.now()}`,
            label: "Mi Ubicación"
          }]);
        } finally {
          setLoadingStage('idle');
        }
      },
      (error) => {
        console.error(error);
        setState(prev => ({ ...prev, error: "Error al obtener la ubicación. Por favor, revisa los permisos del navegador." }));
        setLoadingStage('idle');
      }
    );
  };

  const deleteRoute = (id: string) => {
    const updated = savedRoutes.filter(r => r.id !== id);
    setSavedRoutes(updated);
    localStorage.setItem('logistics_saved_routes', JSON.stringify(updated));
  };

  const handleGenerate = async () => {
    if (!isInputValid) { 
      setShowValidationErrors(true);
      setShake(true);
      setTimeout(() => setShake(false), 500);
      textareaRef.current?.focus(); 
      return; 
    }

    setShowValidationErrors(false);
    setState({ isLoading: true, content: '', error: null, routeData: undefined });
    setLoadingStage('validating');

    try {
      setLoadingStage('connecting');
      const stream = generateLogisticsResponse(type, input, points);
      let fullJsonString = '';

      setLoadingStage('thinking');
      // Simulate thinking time for UX
      await new Promise(resolve => setTimeout(resolve, 800));

      setLoadingStage('streaming');
      for await (const chunk of stream) {
        if (!isMounted.current) break;
        if (isRoute) {
          fullJsonString += chunk;
          const match = fullJsonString.match(/"explanation":\s*"((?:[^"\\]|\\.)*)/);
          if (match && match[1]) {
            setState(prev => ({ ...prev, content: match[1].replace(/\\n/g, '\n').replace(/\\"/g, '"') }));
          }
        } else {
          setState(prev => ({ ...prev, content: (prev.content || '') + chunk }));
        }
      }

      if (isMounted.current && isRoute) {
        setLoadingStage('parsing');
        try {
          const finalData = JSON.parse(fullJsonString.trim()) as RouteResponse;
          setLoadingStage('calculating');
          await new Promise(resolve => setTimeout(resolve, 600));
          setLoadingStage('finalizing');
          setState({ isLoading: false, content: finalData.explanation, error: null, routeData: finalData.optimizedSequence });
        } catch (e) { 
          setState(prev => ({ ...prev, isLoading: false, error: "Error de formato." })); 
        }
      } else { 
        setState(prev => ({ ...prev, isLoading: false })); 
      }
      setLoadingStage('idle');

      setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (err: any) { 
      setState({ isLoading: false, content: null, error: err.message }); 
      setLoadingStage('idle'); 
    }
  };

  const processedRoutes = useMemo(() => {
    let filtered = savedRoutes.filter(r => {
      const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
      const routeDate = new Date(r.timestamp).setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate).setHours(0, 0, 0, 0) : null;
      const end = endDate ? new Date(endDate).setHours(23, 59, 59, 999) : null;
      const matchesStart = start ? routeDate >= start : true;
      const matchesEnd = end ? routeDate <= end : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
    return filtered.sort((a, b) => sortBy === 'date' ? b.timestamp - a.timestamp : a.name.localeCompare(b.name));
  }, [savedRoutes, searchQuery, sortBy, startDate, endDate]);

  const Icon = config.icon;
  const loadingInfo = getLoadingMessage();

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden flex flex-col h-full transition-all duration-300 hover:shadow-2xl">
      <div className="p-8 flex-1 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-4">
            <div className={`${config.bgColor} text-white p-3 rounded-2xl shadow-lg relative`}>
              <Icon size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2 group relative">
                <h3 className="text-xl font-bold text-slate-900 tracking-tight">{config.title}</h3>
                <div className="relative group/info">
                  <div className="p-1 rounded-full bg-slate-100 text-slate-400 hover:text-brand-600 hover:bg-brand-50 transition-all cursor-help">
                    <Info size={14} />
                  </div>
                  <div className="absolute left-0 bottom-full mb-3 w-64 p-4 bg-slate-900 text-white text-[11px] leading-relaxed rounded-2xl shadow-2xl opacity-0 invisible group-hover/info:opacity-100 group-hover/info:visible transition-all duration-300 z-50 transform translate-y-2 group-hover/info:translate-y-0">
                    <p className="font-medium">{config.tooltip}</p>
                    <div className="absolute top-full left-4 border-[6px] border-transparent border-t-slate-900"></div>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  <Sparkles size={10} className="text-amber-500" />
                  <span>AI Engine 3.0</span>
              </div>
            </div>
          </div>

          {isRoute && (
            <button 
              onClick={() => setViewMode(viewMode === 'form' ? 'library' : 'form')}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest border transition-all active:scale-95 ${viewMode === 'library' ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-brand-600 border-brand-200 hover:bg-brand-50'}`}
            >
              <History size={16} />
              <span className="hidden sm:inline">{viewMode === 'form' ? `Biblioteca (${savedRoutes.length})` : 'Volver'}</span>
            </button>
          )}
        </div>

        {isRoute && viewMode === 'library' ? (
          <div className="flex-1 flex flex-col min-h-[500px] animate-in slide-in-from-right-4 fade-in duration-300">
             <div className="bg-slate-50 rounded-2xl border border-slate-200 p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <FolderOpen size={14} className="text-brand-500" /> Historial de Planes
                  </h4>
                  <div className="flex gap-2">
                    <button onClick={() => setSortBy(sortBy === 'date' ? 'name' : 'date')} className="p-2 bg-white text-slate-400 border border-slate-200 rounded-xl hover:text-brand-600 transition-colors">
                      <ChevronRight size={18} className={`transition-transform ${sortBy === 'name' ? 'rotate-90' : ''}`} />
                    </button>
                    <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl transition-all ${showFilters || startDate || endDate ? 'bg-brand-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200 hover:text-brand-600'}`}>
                      <Filter size={18} />
                    </button>
                  </div>
                </div>

                <div className="space-y-4 mb-6">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar por nombre..." className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-sm outline-none shadow-sm focus:ring-2 focus:ring-brand-100" />
                  </div>

                  {(showFilters || startDate || endDate) && (
                    <div className="p-5 bg-white rounded-2xl border border-brand-100 shadow-xl animate-in slide-in-from-top-2 duration-300 relative">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Desde Fecha</label>
                          <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] ml-1">Hasta Fecha</label>
                          <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs focus:ring-2 focus:ring-brand-500 outline-none" />
                        </div>
                      </div>
                      <div className="flex gap-2 mt-4">
                        <button onClick={resetFilters} className="flex-1 py-2.5 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 hover:text-brand-600 uppercase transition-all bg-slate-50 rounded-xl border border-slate-100">
                          <RefreshCw size={12} /> Limpiar
                        </button>
                        <button onClick={() => setShowFilters(false)} className="px-6 py-2.5 bg-brand-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-brand-500/20">Aplicar</button>
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                  {processedRoutes.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                      <Search size={40} className="mb-4 opacity-20" />
                      <p className="text-sm font-medium">No se encontraron rutas.</p>
                    </div>
                  ) : (
                    processedRoutes.map((route) => (
                      <div key={route.id} className="group bg-white p-5 rounded-2xl border border-slate-200 flex items-center justify-between hover:border-brand-300 transition-all shadow-sm hover:shadow-md">
                        <div className="flex-1 min-w-0 pr-4">
                          <p className="text-sm font-bold text-slate-800 truncate">{route.name}</p>
                          <div className="flex items-center gap-3 mt-1.5 text-[9px] font-bold text-slate-400 uppercase">
                            <Calendar size={10} className="text-brand-500" /> {new Date(route.timestamp).toLocaleDateString()}
                            <span className="text-brand-500 bg-brand-50 px-2 py-0.5 rounded-full">{route.points.length} paradas</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <button 
                            onClick={() => { setPoints(route.points); setState(prev => ({ ...prev, routeData: route.routeData, content: route.explanation })); setViewMode('form'); }} 
                            className="px-4 py-2 bg-brand-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-brand-700 transition-all active:scale-95 shadow-md shadow-brand-500/10"
                          >
                            Ver
                          </button>
                          <button 
                            onClick={() => deleteRoute(route.id)}
                            className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
             </div>
          </div>
        ) : (
          <div className="animate-in fade-in slide-in-from-left-4 duration-300 flex-1 flex flex-col">
            <p className="text-slate-500 mb-6 text-sm leading-relaxed">{config.description}</p>
            {isRoute && (
                <div className={`mb-6 h-[300px] relative rounded-3xl overflow-hidden border-2 shadow-inner transition-colors duration-300 ${showValidationErrors && !hasMinPoints ? 'border-amber-200 bg-amber-50/10' : 'border-slate-100'}`}>
                    <LogisticsMap 
                      points={points} 
                      onPointsChange={(newPoints) => {
                        setPoints(newPoints);
                      }} 
                      routeSequence={state.routeData} 
                      externalCenter={externalCenter} 
                      onAddCurrentLocation={handleAddCurrentLocation} 
                      isLocating={loadingStage === 'locating' || loadingStage === 'geocoding'}
                      onLoadingChange={(stage) => setLoadingStage(stage as any)}
                    />
                </div>
            )}

            <div className="flex items-end justify-between mb-2 px-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Instrucciones AI</label>
                <button 
                  type="button" 
                  onClick={handleExampleClick} 
                  disabled={state.isLoading} 
                  className="group flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 border border-slate-200 text-slate-600 text-[10px] font-black uppercase tracking-widest transition-all hover:bg-white hover:border-brand-300 hover:text-brand-600 active:scale-95 disabled:opacity-50"
                >
                    <Lightbulb size={12} className="text-amber-500 group-hover:scale-110 transition-transform" />
                    Ver Ejemplo
                </button>
            </div>

            <div className={`relative transition-transform ${shake ? 'animate-shake' : ''}`}>
              <textarea 
                ref={textareaRef} 
                value={input} 
                onChange={(e) => {
                  setInput(e.target.value);
                  if (showValidationErrors && e.target.value.trim().length > 0) setShowValidationErrors(false);
                }} 
                disabled={state.isLoading} 
                rows={isRoute ? 3 : 5} 
                className={`w-full p-5 border-2 rounded-2xl bg-slate-50 text-sm focus:ring-4 outline-none transition-all resize-none shadow-inner ${showValidationErrors && isInputEmpty ? 'border-red-500 bg-red-50/30 focus:ring-red-50' : 'border-slate-100 focus:ring-brand-100 focus:border-brand-500'}`} 
                placeholder={config.placeholder} 
              />
              {showValidationErrors && isInputEmpty && (
                <p className="mt-2 text-xs font-bold text-red-600 flex items-center gap-1.5 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} className="animate-pulse" />
                  Este campo es obligatorio
                </p>
              )}
            </div>

            {(state.isLoading || loadingStage !== 'idle') && (
              <div className="mt-6 animate-in fade-in duration-300 bg-slate-50 p-4 rounded-2xl border border-slate-100 shadow-inner">
                <div className="flex items-center justify-between mb-3">
                   <div className="flex items-center gap-2">
                     <span className="animate-spin text-brand-600">{loadingInfo.icon}</span>
                     <span className="text-[11px] font-black text-slate-700 uppercase tracking-widest">{loadingInfo.text}</span>
                   </div>
                   <span className="text-[10px] font-black text-brand-600">{loadingInfo.progress}%</span>
                </div>
                <div className="h-2 w-full bg-slate-200 rounded-full overflow-hidden">
                   <div 
                     className="h-full bg-brand-500 transition-all duration-700 ease-out rounded-full shadow-[0_0_10px_rgba(37,99,235,0.4)]"
                     style={{ width: `${loadingInfo.progress}%` }}
                   ></div>
                </div>

                {/* Visual Step Indicator */}
                <div className="mt-4 flex justify-between gap-1">
                  {[1, 2, 3, 4].map((step) => {
                    const isActive = (loadingInfo.progress / 25) >= (step - 0.5);
                    return (
                      <div key={step} className={`h-1 flex-1 rounded-full transition-colors duration-500 ${isActive ? 'bg-brand-500' : 'bg-slate-200'}`}></div>
                    );
                  })}
                </div>
              </div>
            )}

            <div className="mt-8">
              <button onClick={handleGenerate} disabled={state.isLoading || loadingStage !== 'idle'} className={`w-full ${config.buttonColor} text-white font-black uppercase tracking-[0.15em] py-5 rounded-2xl transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-50 active:scale-[0.98]`}>
                {(state.isLoading || loadingStage !== 'idle') ? <Loader2 className="animate-spin" size={22} /> : <Zap size={22} />}
                <span>{(state.isLoading || loadingStage !== 'idle') ? 'Procesando...' : 'Optimizar con IA'}</span>
              </button>
            </div>
          </div>
        )}

        <div ref={resultRef} className={`scroll-mt-24 transition-all duration-500 ${viewMode === 'library' ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
          {state.content !== null && (
            <div className="mt-10 rounded-3xl border border-slate-200 overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-10 duration-700">
               <div className={`p-8 ${config.lightBg}`}>
                  <div className="flex items-center justify-between mb-6 border-b border-slate-200/50 pb-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><Clock size={16} className="text-brand-500" /></div>
                      <span className="text-[11px] font-black uppercase tracking-widest text-slate-500">Informe Estratégico AI</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {isRoute && !saveSuccess && (
                        <button 
                          onClick={handleSaveCurrentRoute}
                          disabled={isSaving}
                          className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-50"
                        >
                          {isSaving ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
                          Guardar Ruta
                        </button>
                      )}
                      {saveSuccess && (
                        <div className="flex items-center gap-2 px-4 py-2 bg-emerald-100 text-emerald-700 rounded-xl text-[10px] font-black uppercase tracking-widest animate-in zoom-in-95 duration-300">
                          <CheckCircle2 size={14} /> Guardada
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="prose prose-sm prose-slate max-w-none">
                      <div className="whitespace-pre-wrap text-slate-800 font-medium leading-relaxed text-sm bg-white/60 p-8 rounded-3xl border border-white shadow-inner">{state.content}</div>
                  </div>
                  <div className="mt-6 flex justify-end">
                    <button 
                      onClick={handleCopy}
                      className={`flex items-center gap-2 text-[10px] font-black uppercase transition-all px-4 py-2 rounded-xl border ${isCopied ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'text-slate-400 border-slate-100 hover:text-brand-600 hover:bg-white hover:shadow-sm'}`}
                    >
                      {isCopied ? <Check size={14} className="animate-in zoom-in-50" /> : <Copy size={14} />}
                      {isCopied ? '¡Copiado!' : 'Copiar al Portapapeles'}
                    </button>
                  </div>
               </div>
            </div>
          )}
        </div>
      </div>
      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          50% { transform: translateX(5px); }
          75% { transform: translateX(-5px); }
        }
        .animate-shake {
          animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both;
        }
      `}</style>
    </div>
  );
};

